/**
 * @file detail/typed_view.hpp
 * @brief An array's elements as `int64_t` or `double`, with the dtype switch
 * taken once per array instead of once per element.
 *
 * A **core-private** header (the `slot_runs.hpp` precedent): no installed
 * header names it, and it adds nothing to the API or the ABI.
 *
 * `Int64View` reads every element exactly as `detail::read_int` does, and
 * `DoubleView` exactly as `detail::read_double` does -- a pointer into the
 * array itself when its dtype already is the target, otherwise one converted
 * copy made in parallel through `dispatch_dtype`. A hot loop then indexes a
 * plain pointer. `DoubleSink` is the write-side twin: a hot loop stores into a
 * plain `double*`, and one `Commit()` converts it exactly as `write_double`
 * would. Roadmap §3, "Hoist the dtype switch in operations".
 */

// System includes
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <type_traits>
#include <vector>

// Project includes

namespace meshioplusplus {
namespace detail {

/// One element as `read_int` converts it.
template <class T>
inline std::int64_t typed_view_int(T v) {
    if constexpr (std::is_floating_point_v<T>) {
        const double d = static_cast<double>(v);
        if (!(d == d))
            return 0;
        if (d >= 9223372036854775807.0)
            return std::numeric_limits<std::int64_t>::max();
        if (d < -9223372036854775808.0)
            return std::numeric_limits<std::int64_t>::min();
        return static_cast<std::int64_t>(d);
    } else {
        return static_cast<std::int64_t>(v);
    }
}

/// An array read as `int64_t`, as `read_int` reads each element.
class Int64View {
public:
    explicit Int64View(const NDArray& rA) {
        const std::size_t n = rA.Size();
        if (rA.Dtype() == DType::Int64) {
            mpData = rA.As<std::int64_t>();
            return;
        }
        mOwned.resize(n);
        dispatch_dtype(rA.Dtype(), [&]<class T>() {
            const T* src = rA.As<T>();
            std::int64_t* dst = mOwned.data();
            parallel_for_bw(n, [&](std::size_t i) { dst[i] = typed_view_int<T>(src[i]); });
        });
        mpData = mOwned.data();
    }
    Int64View(const Int64View&) = delete;
    Int64View& operator=(const Int64View&) = delete;

    const std::int64_t* Data() const { return mpData; }
    std::int64_t operator[](std::size_t i) const { return mpData[i]; }

private:
    const std::int64_t* mpData = nullptr;
    std::vector<std::int64_t> mOwned;
};

/// An array read as `double`, as `read_double` reads each element.
class DoubleView {
public:
    explicit DoubleView(const NDArray& rA) {
        const std::size_t n = rA.Size();
        if (rA.Dtype() == DType::Float64) {
            mpData = rA.As<double>();
            return;
        }
        mOwned.resize(n);
        dispatch_dtype(rA.Dtype(), [&]<class T>() {
            const T* src = rA.As<T>();
            double* dst = mOwned.data();
            parallel_for_bw(n, [&](std::size_t i) { dst[i] = static_cast<double>(src[i]); });
        });
        mpData = mOwned.data();
    }
    DoubleView(const DoubleView&) = delete;
    DoubleView& operator=(const DoubleView&) = delete;

    const double* Data() const { return mpData; }
    double operator[](std::size_t i) const { return mpData[i]; }

private:
    const double* mpData = nullptr;
    std::vector<double> mOwned;
};

/// One element as `write_double` stores it into a `T` array.
template <class T>
inline T typed_view_store(double v) {
    if constexpr (std::is_floating_point_v<T>) {
        return static_cast<T>(v);
    } else {
        if (!std::isfinite(v))
            return static_cast<T>(0);
        const long double r = std::round(static_cast<long double>(v));
        const long double lo = static_cast<long double>(std::numeric_limits<T>::min());
        const long double hi = static_cast<long double>(std::numeric_limits<T>::max());
        return static_cast<T>(r < lo ? lo : (r > hi ? hi : r));
    }
}

/// The write-side twin of `DoubleView`: elements `[First, First + Count)` of an
/// array, written as `double` and stored as `write_double` would store them.
///
/// `Data()[i]` is element `First + i`. When the array already is float64 that
/// is the array itself and `Commit()` has nothing to do; otherwise it is an
/// owned `double` buffer that `Commit()` converts into the array in one
/// parallel pass. A hot loop writes a plain pointer instead of dispatching on
/// the destination dtype for every value.
class DoubleSink {
public:
    DoubleSink(NDArray& rA, std::size_t First, std::size_t Count)
        : mrArray(rA), mFirst(First), mCount(Count) {
        if (rA.Dtype() == DType::Float64) {
            mpData = rA.As<double>() + First;
        } else {
            mOwned.resize(Count);
            mpData = mOwned.data();
        }
    }
    DoubleSink(const DoubleSink&) = delete;
    DoubleSink& operator=(const DoubleSink&) = delete;

    double* Data() { return mpData; }

    /// Stores the buffered values into the array. Call once, after the loop.
    void Commit() {
        if (mOwned.empty())
            return;
        dispatch_dtype(mrArray.Dtype(), [&]<class T>() {
            T* dst = mrArray.As<T>() + mFirst;
            const double* src = mOwned.data();
            parallel_for_bw(mCount, [&](std::size_t i) { dst[i] = typed_view_store<T>(src[i]); });
        });
    }

private:
    NDArray& mrArray;
    std::size_t mFirst;
    std::size_t mCount;
    double* mpData = nullptr;
    std::vector<double> mOwned;
};

}  // namespace detail
}  // namespace meshioplusplus
// ===== end src/cpp/src/detail/typed_view.hpp =====
// ===== begin src/cpp/src/detail/vtk_hex_order.hpp =====
/**
 * @file detail/vtk_hex_order.hpp
 * @brief The edge order of VTK's higher-order hexahedra across file versions.
 *
 * A **core-private** header (the `typed_view.hpp` precedent): no installed
 * header names it, and it adds nothing to the API or the ABI.
 *
 * VTK 9.1 swapped the nodes of edges 10 and 11 of `VTK_LAGRANGE_HEXAHEDRON`
 * and `VTK_BEZIER_HEXAHEDRON` (both edges run along the third direction), and
 * marks files in the new order by version: VTK XML 2.2 and later, legacy 5.1.
 * Its readers convert an older file on read and its legacy writer converts on
 * writing 4.2. meshio++ holds the current order (`lagrange::vtk_lattice`), so a
 * reader converts a file older than those versions, and a writer of an older
 * version converts on the way out. The swap is its own inverse.
 */

// System includes
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <vector>

// Project includes

namespace meshioplusplus {
namespace detail {

/// Whether a VTK cell type id is a higher-order hexahedron (72 Lagrange, 79 Bezier).
inline bool vtk_hex_order_applies(std::int64_t VtkType) {
    return VtkType == 72 || VtkType == 79;
}

/**
 * @brief Swap the nodes of edges 10 and 11 of one higher-order hexahedron.
 * @param pNodes the cell's @p NumNodes nodes, swapped in place
 * @param NumNodes the cell's node count
 * @param pDegrees its degrees per direction (VTK's `HigherOrderDegrees`), or
 *        `nullptr` for an isotropic cell (its degree follows from the count)
 * @return false when the degrees do not account for the node count (nothing done)
 */
inline bool vtk_hex_swap_edges(std::int64_t* pNodes, std::size_t NumNodes,
                               const std::int64_t* pDegrees) {
    std::int64_t p[3];
    if (pDegrees) {
        std::copy(pDegrees, pDegrees + 3, p);
    } else {
        const auto q =
            static_cast<std::int64_t>(std::llround(std::cbrt(static_cast<double>(NumNodes))));
        p[0] = p[1] = p[2] = q - 1;
    }
    if (p[0] < 1 || p[1] < 1 || p[2] < 1 ||
        (p[0] + 1) * (p[1] + 1) * (p[2] + 1) != static_cast<std::int64_t>(NumNodes))
        return false;
    const std::int64_t m = p[2] - 1;  // nodes on each edge along the third direction
    const std::int64_t s = 8 + 4 * (p[0] - 1) + 4 * (p[1] - 1) + 2 * m;
    std::swap_ranges(pNodes + s, pNodes + s + m, pNodes + s + m);
    return true;
}

/**
 * @brief Swap edges 10 and 11 of every higher-order hexahedron of a VTK cell
 * stream (`rTypes` VTK ids, `rOffsets` the end offsets into @p pConn).
 *
 * @p pDegrees is the `HigherOrderDegrees` cell array (one row of three per
 * cell), or `nullptr`; a cell whose degrees cannot be told is left alone, with
 * one warning naming @p pWhat.
 */
inline void vtk_hex_swap_stream(std::int64_t* pConn, const std::vector<std::int64_t>& rOffsets,
                                const std::vector<std::int64_t>& rTypes, const NDArray* pDegrees,
                                const char* pWhat) {
    const bool degrees = pDegrees && pDegrees->Size() == 3 * rTypes.size() && !rTypes.empty();
    bool warned = false;
    for (std::size_t c = 0; c < rTypes.size() && c < rOffsets.size(); ++c) {
        if (!vtk_hex_order_applies(rTypes[c]))
            continue;
        const std::int64_t start = c == 0 ? 0 : rOffsets[c - 1];
        const std::int64_t n = rOffsets[c] - start;
        std::int64_t deg[3];
        if (degrees)
            for (std::size_t k = 0; k < 3; ++k)
                deg[k] = read_int(*pDegrees, 3 * c + k);
        if (n > 0 &&
            !vtk_hex_swap_edges(pConn + start, static_cast<std::size_t>(n),
                                degrees ? deg : nullptr) &&
            !warned) {
            log::warn(
                "{}: a higher-order hexahedron of {} nodes in a file older than VTK 9.1 has no "
                "degrees that explain its size; its edge order is left as written",
                pWhat, n);
            warned = true;
        }
    }
}

}  // namespace detail
}  // namespace meshioplusplus
// ===== end src/cpp/src/detail/vtk_hex_order.hpp =====
