const std::uint8_t* colormap_table(const std::string& rName) {
    if (rName == "viridis")
        return kViridis;
    if (rName == "coolwarm")
        return kCoolwarm;
    if (rName == "turbo")
        return kTurbo;
    if (rName == "magma")
        return kMagma;
    if (rName == "inferno")
        return kInferno;
    if (rName == "plasma")
        return kPlasma;
    if (rName == "grey")
        return kGrey;
    if (rName == "synthwave")
        return kSynthwave;
    if (rName == "viridis_r")
        return kViridisR;
    if (rName == "coolwarm_r")
        return kCoolwarmR;
    if (rName == "turbo_r")
        return kTurboR;
    if (rName == "magma_r")
        return kMagmaR;
    if (rName == "inferno_r")
        return kInfernoR;
    if (rName == "plasma_r")
        return kPlasmaR;
    if (rName == "grey_r")
        return kGreyR;
    if (rName == "synthwave_r")
        return kSynthwaveR;
    throw std::invalid_argument("meshio++: unknown colormap '" + rName +
                                "' (available: viridis, coolwarm, turbo, magma, inferno, plasma, grey, synthwave, viridis_r, coolwarm_r, turbo_r, magma_r, inferno_r, plasma_r, grey_r, synthwave_r)");
}

// clang-format off
std::vector<std::string> colormap_names() {
    return {"viridis", "coolwarm", "turbo", "magma", "inferno", "plasma", "grey", "synthwave", "viridis_r", "coolwarm_r", "turbo_r", "magma_r", "inferno_r", "plasma_r", "grey_r", "synthwave_r"};
}
// clang-format on

const std::uint32_t* srgb_to_linear_bits() {
    return kSrgbLinearBits;
}

Rgb colormap_lookup(const std::uint8_t* pTable, double t) {
    if (!(t > 0.0))  // also catches NaN
        t = 0.0;
    if (t > 1.0)
        t = 1.0;
    const int i = static_cast<int>(t * 255.0 + 0.5);
    return Rgb{pTable[i * 3], pTable[i * 3 + 1], pTable[i * 3 + 2]};
}

