// Project includes

namespace meshioplusplus {

namespace {

// Record flags (the flags word's top byte).
constexpr unsigned kRstBsparse = 0x08;
constexpr unsigned kRstWsparse = 0x10;
constexpr unsigned kRstZlib = 0x20;
constexpr unsigned kRstPrec = 0x40;
constexpr unsigned kRstInt = 0x80;

// MAPDL's "no value".
const double kRstUndefined = std::ldexp(1.0, 100);

[[noreturn]] void rst_fail(const std::string& rWhat) {
    throw ReadError("Ansys .rst: " + rWhat);
}

// One decoded record: its values (integers are exact in a double) and the
// pointer of the record after it.
struct RstRecord {
    std::vector<double> mValues;
    std::uint64_t mNext = 0;

    std::int64_t Int(std::size_t K) const {
        return K < mValues.size() ? detail::checked_integer<std::int64_t>(mValues[K], "Ansys .rst")
                                  : 0;
    }
};

class RstFile {
public:
    RstFile(const std::string& rPath, const ReadOptions& rOptions)
        : mSource(rPath, rOptions.mMmap), mWords(mSource.Size() / 4) {}

    std::int32_t Word(std::uint64_t K) const {
        if (K >= mWords)
            rst_fail("word " + std::to_string(K) + " is outside the file");
        std::int32_t v;
        std::memcpy(&v, mSource.Data() + K * 4, 4);
        return v;
    }

    RstRecord Record(std::uint64_t Ptr) const {
        if (Ptr > mWords || mWords - Ptr < 2)
            rst_fail("record pointer " + std::to_string(Ptr) + " is outside the file");
        const std::int32_t n = Word(Ptr);
        const unsigned flags = (static_cast<std::uint32_t>(Word(Ptr + 1)) >> 24) & 0xFFu;
        const std::uint64_t end = Ptr + 2 + static_cast<std::uint64_t>(n < 0 ? 0 : n);
        if (n < 0 || end > mWords)
            rst_fail("the record at word " + std::to_string(Ptr) +
                     " runs past the end of the file");
        if (flags & kRstZlib)
            rst_fail("zlib-compressed records are not supported; write the file with /FCOMP,RST,0");
        const bool is_int = (flags & kRstInt) != 0, prec = (flags & kRstPrec) != 0;
        const std::size_t item = is_int ? (prec ? 2 : 4) : (prec ? 4 : 8);
        const char* raw = mSource.Data() + (Ptr + 2) * 4;
        const std::size_t bytes = static_cast<std::size_t>(n) * 4;
        const auto value = [&](std::size_t Offset) -> double {
            if (is_int && prec) {
                std::int16_t v;
                std::memcpy(&v, raw + Offset, 2);
                return v;
            }
            if (is_int) {
                std::int32_t v;
                std::memcpy(&v, raw + Offset, 4);
                return v;
            }
            if (prec) {
                float v;
                std::memcpy(&v, raw + Offset, 4);
                return v;
            }
            double v;
            std::memcpy(&v, raw + Offset, 8);
            return v;
        };
        const auto word = [&](std::size_t K) {
            std::int32_t v;
            std::memcpy(&v, raw + K * 4, 4);
            return v;
        };
        const std::string where = " at word " + std::to_string(Ptr);

        RstRecord out;
        out.mNext = Ptr + static_cast<std::uint64_t>(n) + 3;
        if (flags & kRstBsparse) {
            // A size, a bit mask, then the values of the set bits.
            if (bytes < 8)
                rst_fail("the bit-sparse record" + where + " is truncated");
            const std::int32_t size = word(0);
            const auto bits = static_cast<std::uint32_t>(word(1));
            if (size < 0 || size > 32)
                rst_fail("the bit-sparse record" + where + " has size " + std::to_string(size));
            out.mValues.assign(static_cast<std::size_t>(size), 0.0);
            std::size_t k = 0;
            for (int i = 0; i < size; ++i)
                if ((bits >> i) & 1u) {
                    if (8 + (k + 1) * item > bytes)
                        rst_fail("the bit-sparse record" + where + " is truncated");
                    out.mValues[static_cast<std::size_t>(i)] = value(8 + k * item);
                    ++k;
                }
        } else if (flags & kRstWsparse) {
            // A size, a window count, then windows: an isolated value (loc > 0),
            // a run of values, or a repeated constant.
            if (item == 2)
                rst_fail("the record" + where + " is a windowed-sparse int16 record");
            const std::size_t n_words = bytes / 4;
            if (n_words < 2)
                rst_fail("the windowed-sparse record" + where + " is truncated");
            const std::int32_t size = word(0), n_windows = word(1);
            const std::size_t shift = item / 4;
            // A constant window expands a few words into many values, so the
            // expanded size may exceed the record; not beyond 64 values per
            // word of the whole file, though, or a corrupt size would be an
            // allocation of gigabytes.
            if (static_cast<std::uint64_t>(std::max(size, 0)) >
                std::max<std::uint64_t>(std::uint64_t{1} << 20, 64 * mWords))
                rst_fail("the windowed-sparse record" + where + " declares an implausible size");
            out.mValues.assign(static_cast<std::size_t>(std::max(size, 0)), 0.0);
            std::size_t pos = 2;
            const auto take = [&](std::size_t Count) {
                if (pos + shift * Count > n_words)
                    rst_fail("the windowed-sparse record" + where + " is truncated");
                const std::size_t at = pos;
                pos += shift * Count;
                return at;
            };
            for (std::int32_t w = 0; w < n_windows; ++w) {
                if (pos >= n_words)
                    rst_fail("the windowed-sparse record" + where + " is truncated");
                const std::int32_t loc = word(pos++);
                if (loc > 0) {
                    if (loc >= size)
                        rst_fail("the windowed-sparse record" + where + " is corrupt");
                    out.mValues[static_cast<std::size_t>(loc)] = value(take(1) * 4);
                    continue;
                }
                if (pos >= n_words)
                    rst_fail("the windowed-sparse record" + where + " is truncated");
                const std::int64_t start = -static_cast<std::int64_t>(loc);
                const std::int32_t length = word(pos++);
                const std::int64_t count = length < 0 ? -static_cast<std::int64_t>(length) : length;
                if (start + count > size)
                    rst_fail("the windowed-sparse record" + where + " is corrupt");
                if (length > 0) {
                    const std::size_t at = take(static_cast<std::size_t>(count));
                    for (std::int64_t k = 0; k < count; ++k)
                        out.mValues[static_cast<std::size_t>(start + k)] =
                            value((at + static_cast<std::size_t>(k) * shift) * 4);
                } else {
                    const double v = value(take(1) * 4);
                    for (std::int64_t k = 0; k < count; ++k)
                        out.mValues[static_cast<std::size_t>(start + k)] = v;
                }
            }
        } else {
            out.mValues.resize(bytes / item);
            for (std::size_t k = 0; k < out.mValues.size(); ++k)
                out.mValues[k] = value(k * item);
        }
        return out;
    }

private:
    detail::FileSource mSource;
    std::uint64_t mWords;
};

// A 64-bit word pointer split over rHeader[Lo] (low, unsigned) and rHeader[Hi];
// an older file's shorter header has only the 32-bit rHeader[Fallback] (or
// rHeader[Lo] itself).
std::uint64_t rst_pointer(const RstRecord& rHeader, std::size_t Lo, std::size_t Hi,
                          std::size_t Fallback = std::numeric_limits<std::size_t>::max()) {
    const auto low = [&](std::size_t K) {
        return static_cast<std::uint64_t>(static_cast<std::uint32_t>(rHeader.Int(K)));
    };
    if (Hi < rHeader.mValues.size())
        return low(Lo) | (static_cast<std::uint64_t>(rHeader.Int(Hi)) << 32);
    if (Fallback != std::numeric_limits<std::size_t>::max())
        Lo = Fallback;
    return Lo < rHeader.mValues.size() ? low(Lo) : 0;
}

// A name stored as 4-character words, each byte-reversed; cut at the first NUL
// and stripped of spaces and control characters.
std::string rst_name(const RstRecord& rTable, std::size_t Begin, std::size_t End) {
    std::string out;
    for (std::size_t k = Begin; k < End; ++k) {
        const auto v = static_cast<std::uint32_t>(rTable.Int(k));
        for (int shift : {24, 16, 8, 0})
            out += static_cast<char>((v >> shift) & 0xFFu);
    }
    out = out.substr(0, out.find('\0'));
    const auto blank = [](char c) { return static_cast<unsigned char>(c) <= 32; };
    while (!out.empty() && blank(out.back()))
        out.pop_back();
    std::size_t a = 0;
    while (a < out.size() && blank(out[a]))
        ++a;
    return out.substr(a);
}

// numpy.isclose's default tolerances: how mode pairs are recognised.
bool rst_close(double A, double B) {
    return std::fabs(A - B) <= 1e-8 + 1e-5 * std::fabs(B);
}

struct RstSet {
    std::uint64_t mPointer = 0;
    double mTime = 0.0;
    std::int64_t mLoadStep = 0, mSubstep = 0, mCumulative = 0;
};

// The headers and the per-set pointers of a results file.
struct RstResults {
    std::int64_t mNumNodes = 0, mNumSectors = 0, mKan = 0;
    std::int64_t mCsEls = 0, mCsCord = 0, mCsNds = 0, mGlobalNodes = 0;
    std::vector<std::int64_t> mHarmonic;  // a cyclic model's harmonic index per set
    bool mSparseEns = true;               // else ENS holds 11 items per node
    bool mDistributed = false;
    std::uint64_t mPtrGnod = 0;
    std::vector<std::int64_t> mNeqv;
    std::vector<RstSet> mSets;
    std::uint64_t mGeometry = 0;

    explicit RstResults(const RstFile& rFile) {
        const RstRecord standard = rFile.Record(0);
        if (standard.mValues.size() < 2 || standard.Int(0) != 12)
            rst_fail("not a MAPDL results file (its standard header does not name file 12)");
        const RstRecord h = rFile.Record(standard.mNext);
        mNumNodes = h.Int(2);
        const std::int64_t resmax = h.Int(3), nsets = h.Int(8);
        mKan = h.Int(7);
        mCsEls = h.Int(18);
        mNumSectors = h.Int(20);
        mCsCord = h.Int(21);
        mCsNds = h.Int(31);
        mSparseEns = h.Int(39) != 0;
        mGlobalNodes = h.Int(48);
        mPtrGnod = rst_pointer(h, 49, 50);
        mDistributed = mGlobalNodes != 0 && mGlobalNodes != mNumNodes;
        const RstRecord neqv = rFile.Record(rst_pointer(h, 14, 45));
        for (std::size_t k = 0; k < neqv.mValues.size() && k < static_cast<std::size_t>(mNumNodes);
             ++k)
            mNeqv.push_back(neqv.Int(k));
        if (nsets > 0) {
            const RstRecord dsi = rFile.Record(rst_pointer(h, 10, 40));
            const RstRecord tim = rFile.Record(rst_pointer(h, 11, 41));
            const RstRecord lsp = rFile.Record(rst_pointer(h, 12, 42));
            for (std::int64_t i = 0; i < nsets; ++i) {
                const auto k = static_cast<std::size_t>(i);
                RstSet s;
                s.mPointer =
                    static_cast<std::uint64_t>(static_cast<std::uint32_t>(dsi.Int(k))) |
                    (static_cast<std::uint64_t>(dsi.Int(static_cast<std::size_t>(resmax) + k))
                     << 32);
                if (k >= tim.mValues.size())
                    rst_fail("the time table is shorter than the " + std::to_string(nsets) +
                             " result sets");
                s.mTime = tim.mValues[k];
                s.mLoadStep = lsp.Int(3 * k);
                s.mSubstep = lsp.Int(3 * k + 1);
                s.mCumulative = lsp.Int(3 * k + 2);
                mSets.push_back(s);
            }
        }
        mGeometry = rst_pointer(h, 15, 46);
        if (const std::uint64_t ptr_cyc = rst_pointer(h, 16, 43); ptr_cyc && nsets > 0) {
            const RstRecord cyc = rFile.Record(ptr_cyc);
            for (std::size_t k = 0; k < mSets.size() && k < cyc.mValues.size(); ++k)
                mHarmonic.push_back(cyc.Int(k));
            // Before v18 the second set of a mode pair repeats the positive
            // index: negated, as later versions write it.
            if (std::none_of(mHarmonic.begin(), mHarmonic.end(),
                             [](std::int64_t H) { return H < -1; }))
                for (std::size_t k = 0; k + 1 < mHarmonic.size(); ++k)
                    if (rst_close(mSets[k].mTime, mSets[k + 1].mTime))
                        mHarmonic[k + 1] = -mHarmonic[k + 1];
        }
    }
};

// Where an element type's results sit: nodes with element nodal forces (item 63),
// nodes with stresses and strains (item 94: the corners), and the surfaces a
// layered shell stores them for (SHELL181/281 with KEYOPT(8) = 0: bottom, top).
struct RstLayout {
    std::int64_t mNodfor = 0, mNodstr = 0;
    int mLayers = 1;
};

// One results file of a read: its records, headers and model.
struct RstPart {
    RstFile mFile;
    RstResults mResults;
    detail::AnsysModel mModel;
    std::vector<double> mAngles;  // THXY, THYZ, THZX per node, in degrees
    std::map<int, RstLayout> mLayout;
    std::uint64_t mPtrCsy = 0;
    std::int64_t mMaxCsy = 0;
    bool mMapFlag = false;

    RstPart(const std::string& rPath, const ReadOptions& rOptions)
        : mFile(rPath, rOptions), mResults(mFile) {}

    void ReadModel();
    std::pair<std::array<double, 9>, std::array<double, 3>> CoordinateSystem(
        std::int64_t Number) const;
};

void RstPart::ReadModel() {
    const RstFile& file = mFile;
    const RstRecord g = file.Record(mResults.mGeometry);
    const std::int64_t maxety = g.Int(1), nnod = g.Int(3), nelm = g.Int(4);
    const std::uint64_t ptr_ety = rst_pointer(g, 20, 21, 6);
    const std::uint64_t ptr_loc = rst_pointer(g, 26, 27, 8);
    const std::uint64_t ptr_eid = rst_pointer(g, 28, 29, 10);
    mMapFlag = g.Int(64) != 0;
    mPtrCsy = rst_pointer(g, 24, 25, 9);
    mMaxCsy = g.Int(5);

    std::unordered_map<int, std::int64_t> nodelm;
    // Element types: an index record of offsets from ptrETY (in the record after
    // it since 2021R1's mapFlag), each to one type's description.
    const RstRecord table = file.Record(ptr_ety);
    std::vector<std::int64_t> offsets;
    if (mMapFlag) {
        const RstRecord map = file.Record(table.mNext);
        for (std::size_t k = 0; k < map.mValues.size(); ++k)
            offsets.push_back(map.Int(k));
    } else {
        for (std::size_t k = 0; k < table.mValues.size() && k < static_cast<std::size_t>(maxety);
             ++k)
            if (table.Int(k))
                offsets.push_back(table.Int(k));
    }
    for (std::int64_t off : offsets) {
        const RstRecord info = file.Record(ptr_ety + static_cast<std::uint64_t>(off));
        if (info.mValues.size() < 2)
            continue;
        const int slot = static_cast<int>(info.Int(0));
        const int routine = static_cast<int>(info.Int(1));
        mModel.mRoutine[slot] = routine;
        mModel.mKeyopt[slot][1] = static_cast<int>(info.Int(2));
        nodelm[slot] = info.Int(60);
        RstLayout layout;
        layout.mNodfor = info.Int(62);
        layout.mNodstr = info.Int(93);
        layout.mLayers = (routine == 181 || routine == 281) && info.Int(9) == 0 ? 2 : 1;
        mLayout[slot] = layout;
    }

    std::uint64_t ptr = ptr_loc;
    for (std::int64_t k = 0; k < nnod; ++k) {
        const RstRecord node = file.Record(ptr);
        ptr = node.mNext;
        const auto at = [&](std::size_t K) {
            return K < node.mValues.size() ? node.mValues[K] : 0.0;
        };
        mModel.mNodeIds.push_back(detail::checked_integer<std::int64_t>(at(0), "Ansys .rst"));
        for (std::size_t d = 1; d <= 3; ++d)
            mModel.mCoords.push_back(at(d));
        for (std::size_t d = 4; d <= 6; ++d)
            mAngles.push_back(at(d));
    }

    if (nelm > 0) {
        // The element index holds 64-bit offsets from ptrEID in 32-bit words.
        const RstRecord index = file.Record(ptr_eid);
        for (std::int64_t e = 0; e < nelm; ++e) {
            const auto k = static_cast<std::size_t>(e);
            const std::int64_t off = static_cast<std::int64_t>(
                static_cast<std::uint64_t>(static_cast<std::uint32_t>(index.Int(2 * k))) |
                (static_cast<std::uint64_t>(index.Int(2 * k + 1)) << 32));
            const std::uint64_t at = ptr_eid + static_cast<std::uint64_t>(off);
            const RstRecord rec = file.Record(at);
            if (rec.mValues.size() < 10)
                rst_fail("the element record at word " + std::to_string(at) + " is truncated");
            detail::AnsysElement el;
            el.mMat = rec.Int(0);
            el.mSlot = static_cast<int>(rec.Int(1));
            el.mReal = rec.Int(2);
            el.mSecnum = rec.Int(3);
            el.mId = rec.Int(8);
            std::size_t n = rec.mValues.size() - 10;
            if (const auto it = nodelm.find(el.mSlot); it != nodelm.end() && it->second > 0)
                n = std::min(n, static_cast<std::size_t>(it->second));
            for (std::size_t j = 0; j < n; ++j)
                el.mNodes.push_back(rec.Int(10 + j));
            mModel.mElements.push_back(std::move(el));
        }
    }

    ptr = rst_pointer(g, 50, 51);
    const std::int64_t n_components = ptr ? g.Int(48) : 0;
    for (std::int64_t c = 0; c < n_components; ++c) {
        const RstRecord comp = file.Record(ptr);
        ptr = comp.mNext;
        const std::int64_t kind = comp.Int(0);
        if (comp.mValues.size() < 9 || (kind != 1 && kind != 2))
            continue;
        detail::AnsysComponent out;
        out.mName = rst_name(comp, 1, 9);
        out.mNodes = kind == 1;
        // Ids with -last closing a run opened by the value before it.
        for (std::size_t k = 9; k < comp.mValues.size(); ++k) {
            const std::int64_t v = comp.Int(k);
            if (v > 0)
                out.mIds.push_back(v);
            else if (v < 0 && !out.mIds.empty())
                for (std::int64_t id = out.mIds.back() + 1; id <= -v; ++id)
                    out.mIds.push_back(id);
        }
        mModel.mComponents.push_back(std::move(out));
    }
}

// (axes, origin) of local coordinate system Number: the rows of axes are its X,
// Y and Z axes in global coordinates.
std::pair<std::array<double, 9>, std::array<double, 3>> RstPart::CoordinateSystem(
    std::int64_t Number) const {
    if (mPtrCsy) {
        const RstRecord table = mFile.Record(mPtrCsy);
        std::vector<std::int64_t> offsets;
        if (mMapFlag) {
            const RstRecord map = mFile.Record(table.mNext);
            for (std::size_t k = 0; k < map.mValues.size(); ++k)
                offsets.push_back(map.Int(k));
        } else {
            for (std::size_t k = 0;
                 k < table.mValues.size() &&
                 k < static_cast<std::size_t>(std::max<std::int64_t>(mMaxCsy, 0));
                 ++k)
                offsets.push_back(table.Int(k));
        }
        for (std::int64_t off : offsets) {
            if (!off)
                continue;
            const RstRecord data = mFile.Record(mPtrCsy + static_cast<std::uint64_t>(off));
            if (data.mValues.size() >= 22 && data.Int(21) == Number) {
                std::array<double, 9> axes{};
                std::array<double, 3> origin{};
                std::copy(data.mValues.begin(), data.mValues.begin() + 9, axes.begin());
                std::copy(data.mValues.begin() + 9, data.mValues.begin() + 12, origin.begin());
                return {axes, origin};
            }
        }
    }
    rst_fail("coordinate system " + std::to_string(Number) +
             " (the cyclic axis) is not in the file");
}

// Nodal to global: a node's axes are the global ones turned about Z by THXY,
// then about the new X by THYZ, then about the newest Y by THZX, so
// v_global = Rz Rx Ry v_nodal.
void rst_rotate(double* pV, const double* pAngles) {
    const double xy = pAngles[0], yz = pAngles[1], zx = pAngles[2];
    if (xy == 0.0 && yz == 0.0 && zx == 0.0)
        return;
    const double deg = std::acos(-1.0) / 180.0;
    double x = pV[0], y = pV[1], z = pV[2];
    double c = std::cos(zx * deg), s = std::sin(zx * deg);
    double nx = c * x + s * z, nz = -s * x + c * z;
    x = nx;
    z = nz;
    c = std::cos(yz * deg);
    s = std::sin(yz * deg);
    double ny = c * y - s * z;
    nz = s * y + c * z;
    y = ny;
    z = nz;
    c = std::cos(xy * deg);
    s = std::sin(xy * deg);
    nx = c * x - s * y;
    ny = s * x + c * y;
    pV[0] = nx;
    pV[1] = ny;
    pV[2] = z;
}

// The inverse of rst_rotate: a global vector in the node's own axes.
void rst_unrotate(double* pV, const double* pAngles) {
    const double xy = pAngles[0], yz = pAngles[1], zx = pAngles[2];
    if (xy == 0.0 && yz == 0.0 && zx == 0.0)
        return;
    const double deg = std::acos(-1.0) / 180.0;
    double x = pV[0], y = pV[1], z = pV[2];
    double c = std::cos(xy * deg), s = std::sin(xy * deg);
    double nx = c * x + s * y, ny = -s * x + c * y;
    x = nx;
    y = ny;
    c = std::cos(yz * deg);
    s = std::sin(yz * deg);
    ny = c * y + s * z;
    double nz = -s * y + c * z;
    y = ny;
    z = nz;
    c = std::cos(zx * deg);
    s = std::sin(zx * deg);
    nx = c * x - s * z;
    nz = s * x + c * z;
    pV[0] = nx;
    pV[1] = y;
    pV[2] = nz;
}

const char* rst_scalar_name(std::int64_t Code) {
    switch (Code) {
        case 16:
            return "WARP";
        case 17:
            return "CONC";
        case 18:
            return "HDSP";
        case 19:
            return "PRES";
        case 20:
            return "TEMP";
        case 21:
            return "VOLT";
        case 22:
            return "MAG";
        case 23:
            return "ENKE";
        case 24:
            return "ENDS";
        case 25:
            return "EMF";
        case 26:
            return "CURR";
        default:
            return nullptr;
    }
}

// A DOF's label, for RF_<label> reaction names.
std::string rst_dof_label(std::int64_t Code) {
    static const char* const kLabels[] = {"UX", "UY", "UZ", "ROTX", "ROTY", "ROTZ",
                                          "AX", "AY", "AZ", "VX",   "VY",   "VZ"};
    if (Code >= 1 && Code <= 12)
        return kLabels[Code - 1];
    if (const char* known = rst_scalar_name(Code))
        return known;
    return "DOF" + std::to_string(Code);
}

// The element solution: each element's pointer table (ptrESL) has one entry per
// kind of record, in this order (fdresu.inc).
constexpr std::size_t kRstEnf = 1, kRstEns = 2, kRstEel = 5, kRstEpl = 6, kRstEcr = 7, kRstEth = 8,
                      kRstEul = 9;

// Element nodal tensors: name, table entry, items per node (the first six are
// the components xx yy zz xy yz xz), stress (else engineering strain).
struct RstTensor {
    const char* mName;
    std::size_t mEntry;
    std::size_t mItems;
    bool mStress;
};
constexpr RstTensor kRstTensors[] = {
    {"S", kRstEns, 6, true},     {"EPEL", kRstEel, 7, false}, {"EPPL", kRstEpl, 7, false},
    {"EPCR", kRstEcr, 7, false}, {"EPTH", kRstEth, 8, false},
};
constexpr const char* kRstTop = "@top";  // a layered shell's top surface

// Element records read as they are written, one row per element (NaN-padded to
// the longest): their items depend on the element type (the element's
// documentation, "Element Output Definitions").
struct RstRawRecord {
    const char* mName;
    std::size_t mEntry;
};
constexpr RstRawRecord kRstRawRecords[] = {
    {"EMS", 0},  {"ENG", 3},  {"EGR", 4},  {"EUL", 9},  {"EFX", 10},
    {"EMN", 12}, {"ENL", 14}, {"EPT", 16}, {"ECT", 20}, {"ESV", 23},
};

bool rst_is_tensor(const std::string& rName, bool* pStress) {
    for (const RstTensor& t : kRstTensors)
        if (rName == t.mName || rName == std::string(t.mName) + kRstTop) {
            if (pStress)
                *pStress = t.mStress;
            return true;
        }
    return false;
}

bool rst_is_vector(const std::string& rName) {
    return rName == "U" || rName == "ROT" || rName == "A" || rName == "V" || rName == "RF" ||
           rName == "RMOM";
}

// Q T Q^T for one tensor xx yy zz xy yz xz (in place); a strain's shear
// components are engineering strains.
void rst_rotate_tensor(double* pT, const double* pQ, bool Stress) {
    const double shear = Stress ? 1.0 : 0.5;
    const double t[9] = {pT[0],         shear * pT[3], shear * pT[5], shear * pT[3], pT[1],
                         shear * pT[4], shear * pT[5], shear * pT[4], pT[2]};
    double qt[9], out[9];
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j) {
            double v = 0.0;
            for (int k = 0; k < 3; ++k)
                v += pQ[i * 3 + k] * t[k * 3 + j];
            qt[i * 3 + j] = v;
        }
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j) {
            double v = 0.0;
            for (int k = 0; k < 3; ++k)
                v += qt[i * 3 + k] * pQ[j * 3 + k];
            out[i * 3 + j] = v;
        }
    pT[0] = out[0];
    pT[1] = out[4];
    pT[2] = out[8];
    pT[3] = out[1] / shear;
    pT[4] = out[5] / shear;
    pT[5] = out[2] / shear;
}

// MAPDL's element rotation (THXY, THYZ, THZX in degrees, 3-1-2) as the matrix
// Q = R^T taking a tensor from the element system to the global one.
std::array<double, 9> rst_euler_to_global(const double* pAngles) {
    const double deg = std::acos(-1.0) / 180.0;
    const double c1 = std::cos(pAngles[0] * deg), c2 = std::cos(pAngles[1] * deg),
                 c3 = std::cos(pAngles[2] * deg);
    const double s1 = std::sin(pAngles[0] * deg), s2 = std::sin(pAngles[1] * deg),
                 s3 = std::sin(pAngles[2] * deg);
    const double r[9] = {
        c1 * c3 - s1 * s2 * s3, s1 * c3 + c1 * s2 * s3, -s3 * c2, -s1 * c2, c1 * c2, s2,
        c1 * s3 + s1 * s2 * c3, s1 * s3 - c1 * c3 * s2, c2 * c3};
    return {r[0], r[3], r[6], r[1], r[4], r[7], r[2], r[5], r[8]};
}

// Rodrigues: the rotation by Theta about unit vector pAxis.
std::array<double, 9> rst_axis_rotation(const double* pAxis, double Theta) {
    const double x = pAxis[0], y = pAxis[1], z = pAxis[2];
    const double c = std::cos(Theta), s = std::sin(Theta), t = 1.0 - c;
    return {c + t * x * x,     t * x * y - s * z, t * x * z + s * y,
            t * x * y + s * z, c + t * y * y,     t * y * z - s * x,
            t * x * z - s * y, t * y * z + s * x, c + t * z * z};
}

// The model of one results file, or of a distributed solve's files merged by
// node number (each element lives in one file).
struct RstModel {
    std::vector<std::unique_ptr<RstPart>> mParts;
    std::vector<std::size_t> mOffsets;  // each part's first element in the merged list
    detail::AnsysModel mModel;
    std::map<int, RstLayout> mLayout;
    std::vector<double> mAngles;
    Mesh mMesh;
    std::unordered_map<std::int64_t, std::int64_t> mNodeIndex;
    std::vector<detail::AnsysCellLocation> mCells;
};

// The results file, with its partial siblings when it is the main file of a
// distributed solve (file0.rst beside file1.rst ...).
std::vector<std::unique_ptr<RstPart>> rst_open(const std::string& rPath,
                                               const ReadOptions& rOptions) {
    std::vector<std::unique_ptr<RstPart>> parts;
    parts.push_back(std::make_unique<RstPart>(rPath, rOptions));
    const RstResults& main = parts[0]->mResults;
    if (!main.mDistributed)
        return parts;
    if (!main.mPtrGnod)
        rst_fail("a partial result file of a distributed solve (" + std::to_string(main.mNumNodes) +
                 " of " + std::to_string(main.mGlobalNodes) +
                 " nodes) that is not the main one; read the file whose name ends in 0 (it "
                 "finds the others), or the combined file (RESCOMBINE)");
    const std::filesystem::path path(rPath);
    const std::string stem = path.stem().string();
    const std::string ext = path.extension().string();
    if (stem.empty() || stem.back() != '0')
        rst_fail("the main file of a distributed solve must be named <job>0" + ext +
                 " to find its partial files");
    const std::string job = stem.substr(0, stem.size() - 1);
    for (;;) {
        const std::filesystem::path sibling =
            path.parent_path() / (job + std::to_string(parts.size()) + ext);
        std::error_code ec;
        if (!std::filesystem::exists(sibling, ec))
            break;
        auto part = std::make_unique<RstPart>(sibling.string(), rOptions);
        if (!part->mResults.mDistributed || part->mResults.mSets.size() != main.mSets.size())
            rst_fail(sibling.filename().string() + " is not a partial file of the same solve");
        parts.push_back(std::move(part));
    }
    return parts;
}

RstModel rst_model(std::vector<std::unique_ptr<RstPart>> Parts, bool Lenient) {
    RstModel out;
    out.mParts = std::move(Parts);
    std::unordered_map<std::int64_t, std::size_t> seen;
    std::vector<std::pair<std::string, bool>> component_order;
    std::map<std::pair<std::string, bool>, std::vector<std::int64_t>> components;
    for (auto& part : out.mParts) {
        part->ReadModel();
        const detail::AnsysModel& m = part->mModel;
        out.mOffsets.push_back(out.mModel.mElements.size());
        out.mModel.mElements.insert(out.mModel.mElements.end(), m.mElements.begin(),
                                    m.mElements.end());
        for (const auto& [slot, routine] : m.mRoutine)
            out.mModel.mRoutine.emplace(slot, routine);
        for (const auto& [slot, keys] : m.mKeyopt)
            out.mModel.mKeyopt.emplace(slot, keys);
        for (const auto& [slot, layout] : part->mLayout)
            out.mLayout.emplace(slot, layout);
        for (std::size_t k = 0; k < m.mNodeIds.size(); ++k) {
            if (!seen.emplace(m.mNodeIds[k], out.mModel.mNodeIds.size()).second)
                continue;
            out.mModel.mNodeIds.push_back(m.mNodeIds[k]);
            for (std::size_t d = 0; d < 3; ++d) {
                out.mModel.mCoords.push_back(m.mCoords[k * 3 + d]);
                out.mAngles.push_back(part->mAngles[k * 3 + d]);
            }
        }
        for (const detail::AnsysComponent& c : m.mComponents) {
            const auto key = std::make_pair(c.mName, c.mNodes);
            auto [it, fresh] = components.emplace(key, std::vector<std::int64_t>{});
            if (fresh) {
                component_order.push_back(key);
                it->second = c.mIds;
                continue;
            }
            std::unordered_set<std::int64_t> known(it->second.begin(), it->second.end());
            for (std::int64_t id : c.mIds)
                if (known.insert(id).second)
                    it->second.push_back(id);
        }
    }
    if (out.mParts.size() > 1) {
        const RstPart& main = *out.mParts[0];
        const RstRecord gnod = main.mFile.Record(main.mResults.mPtrGnod);
        std::size_t missing = 0;
        for (std::size_t k = 0; k < gnod.mValues.size(); ++k)
            if (!seen.count(gnod.Int(k)))
                ++missing;
        if (missing)
            rst_fail("the partial files hold " + std::to_string(seen.size()) + " of the " +
                     std::to_string(seen.size() + missing) +
                     " nodes of the distributed solve; one is missing");
    }
    for (const auto& key : component_order) {
        detail::AnsysComponent c;
        c.mName = key.first;
        c.mNodes = key.second;
        c.mIds = components[key];
        out.mModel.mComponents.push_back(std::move(c));
    }
    AnsysInfo info;
    out.mMesh = detail::ansys_build_mesh(out.mModel, Lenient, "Ansys .rst", info, out.mNodeIndex,
                                         out.mCells);
    return out;
}

std::int64_t rst_point_of(const RstModel& rModel, std::int64_t Number) {
    const auto it = rModel.mNodeIndex.find(Number);
    return it == rModel.mNodeIndex.end() ? -1 : it->second;
}

NDArray rst_filled(std::size_t Rows, std::size_t Cols) {
    NDArray out = Cols ? NDArray(DType::Float64, {Rows, Cols}) : NDArray(DType::Float64, {Rows});
    double* p = out.As<double>();
    std::fill(p, p + out.Size(), std::numeric_limits<double>::quiet_NaN());
    return out;
}

// The nodal DOF solution of result set Index, from every part.
void rst_solution(RstModel& rModel, std::size_t Index, const ReadOptions& rOptions) {
    const std::size_t n_points = rModel.mMesh.NumPoints();
    std::map<std::string, NDArray> vectors, scalars;
    for (const auto& part : rModel.mParts) {
        const RstFile& file = part->mFile;
        const RstResults& results = part->mResults;
        const std::uint64_t base = results.mSets[Index].mPointer;
        const RstRecord s = file.Record(base);
        const std::int64_t nnod = s.Int(2), numdof = s.Int(19);
        // The DOF labels are words 20.. of this header, so their count is
        // bounded by the header's length; a larger one is corruption.
        if (numdof > 0 && static_cast<std::uint64_t>(numdof) + 20 > s.mValues.size())
            rst_fail("result set " + std::to_string(Index + 1) + " has a corrupt DOF count");
        std::vector<std::int64_t> dofs;
        dofs.reserve(static_cast<std::size_t>(std::max<std::int64_t>(numdof, 0)));
        for (std::int64_t k = 0; k < numdof; ++k)
            dofs.push_back(s.Int(20 + static_cast<std::size_t>(k)));
        const std::int64_t sumdof = numdof + s.Int(97);
        const std::uint64_t ptr_nsl = rst_pointer(s, 104, 105, 10);
        if (!ptr_nsl || numdof <= 0)
            continue;
        if (sumdof < numdof)  // each row holds every DOF, then the extras
            rst_fail("result set " + std::to_string(Index + 1) + " has a corrupt DOF count");
        const RstRecord values = file.Record(base + ptr_nsl);
        const auto width = static_cast<std::size_t>(sumdof);
        const std::size_t rows = std::min(static_cast<std::size_t>(std::max<std::int64_t>(nnod, 0)),
                                          values.mValues.size() / width);
        std::vector<std::int64_t> numbers;
        if (rows < static_cast<std::size_t>(nnod)) {
            // Not every node has a solution: the next record lists which.
            const RstRecord which = file.Record(values.mNext);
            if (which.mValues.size() < rows)
                rst_fail("result set " + std::to_string(Index + 1) + " has a corrupt node index");
            for (std::size_t r = 0; r < rows; ++r) {
                const std::int64_t k = which.Int(r) - 1;
                if (k < 0 || k >= static_cast<std::int64_t>(results.mNeqv.size()))
                    rst_fail("result set " + std::to_string(Index + 1) +
                             " has a corrupt node index");
                numbers.push_back(results.mNeqv[static_cast<std::size_t>(k)]);
            }
        } else {
            for (std::size_t r = 0; r < rows; ++r)
                numbers.push_back(r < results.mNeqv.size() ? results.mNeqv[r] : -1);
        }
        std::vector<std::int64_t> points(rows, -1);
        for (std::size_t r = 0; r < rows; ++r)
            points[r] = rst_point_of(rModel, numbers[r]);
        const auto cell = [&](std::size_t R, std::size_t K) {
            const double v = values.mValues[R * width + K];
            return std::fabs(v) == kRstUndefined ? std::numeric_limits<double>::quiet_NaN() : v;
        };

        std::unordered_map<std::int64_t, std::size_t> column;
        for (std::size_t k = 0; k < dofs.size(); ++k)
            column.emplace(dofs[k], k);
        static const std::pair<const char*, std::int64_t> kVectors[] = {
            {"U", 1}, {"ROT", 4}, {"A", 7}, {"V", 10}};
        for (const auto& [name, first] : kVectors) {
            const bool any =
                column.count(first) || column.count(first + 1) || column.count(first + 2);
            if (!any || !rOptions.WantsArray(name))
                continue;
            auto it = vectors.find(name);
            if (it == vectors.end())
                it = vectors.emplace(name, rst_filled(n_points, 3)).first;
            double* p = it->second.As<double>();
            for (std::size_t r = 0; r < rows; ++r) {
                if (points[r] < 0)
                    continue;
                double v[3] = {0.0, 0.0, 0.0};
                for (std::int64_t d = 0; d < 3; ++d)
                    if (const auto c = column.find(first + d); c != column.end())
                        v[d] = cell(r, c->second);
                const auto point = static_cast<std::size_t>(points[r]);
                rst_rotate(v, &rModel.mAngles[point * 3]);
                std::copy(v, v + 3, p + point * 3);
            }
        }
        for (std::size_t k = 0; k < dofs.size(); ++k) {
            const std::int64_t code = dofs[k];
            if (code >= 1 && code <= 12)
                continue;
            const char* known = rst_scalar_name(code);
            const std::string name = known ? known : "DOF" + std::to_string(code);
            if (!rOptions.WantsArray(name))
                continue;
            auto it = scalars.find(name);
            if (it == scalars.end())
                it = scalars.emplace(name, rst_filled(n_points, 0)).first;
            double* p = it->second.As<double>();
            for (std::size_t r = 0; r < rows; ++r)
                if (points[r] >= 0)
                    p[points[r]] = cell(r, k);
        }
    }
    for (auto& [name, data] : vectors)
        rModel.mMesh.AddPointData(name, std::move(data));
    for (auto& [name, data] : scalars)
        rModel.mMesh.AddPointData(name, std::move(data));
}

// The reaction forces of result set Index: RF and RMOM (global axes) and
// RF_<DOF label>.
void rst_reactions(RstModel& rModel, std::size_t Index, const ReadOptions& rOptions) {
    const std::size_t n_points = rModel.mMesh.NumPoints();
    std::map<std::string, NDArray> out;
    for (const auto& part : rModel.mParts) {
        const RstFile& file = part->mFile;
        const RstResults& results = part->mResults;
        const std::uint64_t base = results.mSets[Index].mPointer;
        const RstRecord s = file.Record(base);
        const std::int64_t nrf = s.Int(7), numdof = s.Int(19);
        const std::uint64_t ptr_rf = rst_pointer(s, 106, 107, 12);
        if (nrf <= 0 || !ptr_rf || numdof <= 0)
            continue;
        std::vector<std::int64_t> dofs;
        dofs.reserve(std::min<std::size_t>(static_cast<std::size_t>(numdof), s.mValues.size()));
        for (std::int64_t k = 0; k < numdof; ++k)
            dofs.push_back(s.Int(20 + static_cast<std::size_t>(k)));
        // (N - 1) * numdof + k: N the node's position in the nodal equivalence
        // table, k the DOF's position in the set's DOF list (1-based).
        const RstRecord table = file.Record(base + ptr_rf);
        const RstRecord values = file.Record(table.mNext);
        const auto n = static_cast<std::size_t>(nrf);
        if (table.mValues.size() < 2 * n || values.mValues.size() < n)
            rst_fail("result set " + std::to_string(Index + 1) +
                     " has a truncated reaction record");
        for (std::size_t r = 0; r < n; ++r) {
            const std::int64_t index = static_cast<std::int64_t>(
                static_cast<std::uint64_t>(static_cast<std::uint32_t>(table.Int(2 * r))) |
                (static_cast<std::uint64_t>(table.Int(2 * r + 1)) << 32));
            const std::int64_t position = (index - 1) / numdof;
            const auto k = static_cast<std::size_t>((index - 1) % numdof);
            if (index < 1 || position >= static_cast<std::int64_t>(results.mNeqv.size()))
                rst_fail("result set " + std::to_string(Index + 1) +
                         " has a corrupt reaction record");
            const std::int64_t point =
                rst_point_of(rModel, results.mNeqv[static_cast<std::size_t>(position)]);
            if (point < 0)
                continue;
            const std::int64_t code = dofs[k];
            std::string name;
            std::size_t component = 0, width = 0;
            if (code >= 1 && code <= 3) {
                name = "RF";
                component = static_cast<std::size_t>(code - 1);
                width = 3;
            } else if (code >= 4 && code <= 6) {
                name = "RMOM";
                component = static_cast<std::size_t>(code - 4);
                width = 3;
            } else {
                name = "RF_" + rst_dof_label(code);
            }
            if (!rOptions.WantsArray(name))
                continue;
            auto it = out.find(name);
            if (it == out.end())
                it = out.emplace(name, rst_filled(n_points, width)).first;
            // A distributed solve's files each hold their share of a reaction at
            // the nodes they have in common: summed.
            double* p = it->second.As<double>();
            if (width) {
                double* row = p + static_cast<std::size_t>(point) * 3;
                for (std::size_t d = 0; d < 3; ++d)
                    if (std::isnan(row[d]))
                        row[d] = 0.0;
                row[component] += values.mValues[r];
            } else {
                p[point] = std::isnan(p[point]) ? values.mValues[r] : p[point] + values.mValues[r];
            }
        }
    }
    for (const char* name : {"RF", "RMOM"}) {
        const auto it = out.find(name);
        if (it == out.end())
            continue;
        double* p = it->second.As<double>();
        for (std::size_t point = 0; point < n_points; ++point)
            if (!std::isnan(p[point * 3]))
                rst_rotate(p + point * 3, &rModel.mAngles[point * 3]);
    }
    for (auto& [name, data] : out)
        rModel.mMesh.AddPointData(name, std::move(data));
}

// Entry Entry of the pointer table at word Table: false when the element has
// no such record. A negative entry -n stands for a record of n zeros that is
// not written.
bool rst_element_record(const RstFile& rFile, std::uint64_t Table, const RstRecord& rPointers,
                        std::size_t Entry, std::vector<double>& rOut) {
    if (Entry >= rPointers.mValues.size())
        return false;
    const std::int64_t ptr = rPointers.Int(Entry);
    if (ptr == 0)
        return false;
    if (ptr < 0) {
        rOut.assign(static_cast<std::size_t>(-ptr), 0.0);
        return true;
    }
    rOut = rFile.Record(Table + static_cast<std::uint64_t>(ptr)).mValues;
    return true;
}

bool rst_no_result_cell(const std::string& rType) {
    return rType == "vertex" || rType == "line" || rType == "line3";
}

// Element nodal stresses and strains (cell data per element node, and averaged
// at the corner nodes as point data) and element nodal forces of result set
// Index.
void rst_elements(RstModel& rModel, std::size_t Index, const ReadOptions& rOptions,
                  std::vector<std::int64_t>& rEnfDofs) {
    Mesh& mesh = rModel.mMesh;
    const std::size_t n_points = mesh.NumPoints();
    const std::size_t n_blocks = mesh.NumCellBlocks();
    std::vector<std::string> types(n_blocks);
    std::vector<std::size_t> rows_of(n_blocks), width_of(n_blocks);
    std::vector<const std::int64_t*> conn(n_blocks);
    std::size_t npc = 0;  // the widest block's node count: every array's
    for (std::size_t b = 0; b < n_blocks; ++b) {
        const auto view = mesh.Cells(b);
        types[b] = view.Type();
        rows_of[b] = view.NumCells();
        width_of[b] = view.NodesPerCell();
        conn[b] = view.Conn().template As<std::int64_t>();
        npc = std::max(npc, width_of[b]);
    }
    struct Accumulator {
        std::vector<NDArray> mCells;
        std::vector<double> mSum;
        std::vector<std::int64_t> mCount;
    };
    std::map<std::string, Accumulator> tensors;
    const auto accumulator = [&](const std::string& rName) -> Accumulator& {
        auto it = tensors.find(rName);
        if (it != tensors.end())
            return it->second;
        Accumulator a;
        // (cells, nodes, 6) flattened point-major, NaN-padded to the widest
        // block, so that any writer holds it.
        for (std::size_t b = 0; b < n_blocks; ++b) {
            NDArray arr(DType::Float64, {rows_of[b], npc * 6});
            std::fill(arr.As<double>(), arr.As<double>() + arr.Size(),
                      std::numeric_limits<double>::quiet_NaN());
            a.mCells.push_back(std::move(arr));
        }
        a.mSum.assign(n_points * 6, 0.0);
        a.mCount.assign(n_points, 0);
        return tensors.emplace(rName, std::move(a)).first->second;
    };
    bool want_any_tensor = false;
    for (const RstTensor& t : kRstTensors)
        want_any_tensor = want_any_tensor || rOptions.WantsArray(t.mName) ||
                          rOptions.WantsArray(std::string(t.mName) + kRstTop);
    const bool want_enf = rOptions.WantsArray("ENF");
    bool want_any_raw = false;
    for (const RstRawRecord& r : kRstRawRecords)
        want_any_raw = want_any_raw || rOptions.WantsArray(r.mName);
    if (!want_any_tensor && !want_enf && !want_any_raw)
        return;
    // Per raw record: per block, the rows read and their values.
    std::map<std::string, std::vector<std::vector<std::pair<std::size_t, std::vector<double>>>>>
        raw;
    std::vector<NDArray> enf;
    std::size_t enf_width = 0;
    std::vector<double> values, rotation;
    for (std::size_t p = 0; p < rModel.mParts.size(); ++p) {
        const RstPart& part = *rModel.mParts[p];
        const RstFile& file = part.mFile;
        const RstResults& results = part.mResults;
        const std::uint64_t base = results.mSets[Index].mPointer;
        const RstRecord s = file.Record(base);
        const std::uint64_t ptr_esl = rst_pointer(s, 118, 119, 11);
        if (!ptr_esl)
            continue;
        std::vector<std::int64_t> dofs;
        dofs.reserve(static_cast<std::size_t>(
            std::clamp<std::int64_t>(s.Int(19), 0, static_cast<std::int64_t>(s.mValues.size()))));
        for (std::int64_t k = 0; k < s.Int(19); ++k)
            dofs.push_back(s.Int(20 + static_cast<std::size_t>(k)));
        const RstRecord index = file.Record(base + ptr_esl);
        const std::size_t n_elements = index.mValues.size() / 2;
        for (std::size_t k = 0; k < n_elements; ++k) {
            const std::int64_t off = static_cast<std::int64_t>(
                static_cast<std::uint64_t>(static_cast<std::uint32_t>(index.Int(2 * k))) |
                (static_cast<std::uint64_t>(index.Int(2 * k + 1)) << 32));
            const std::size_t pos = rModel.mOffsets[p] + k;
            if (off == 0 || pos >= rModel.mCells.size() || rModel.mCells[pos].mBlock < 0)
                continue;
            const detail::AnsysCellLocation& loc = rModel.mCells[pos];
            const auto b = static_cast<std::size_t>(loc.mBlock);
            const auto row = static_cast<std::size_t>(loc.mRow);
            const std::uint64_t table = base + ptr_esl + static_cast<std::uint64_t>(off);
            const RstRecord pointers = file.Record(table);
            for (const RstRawRecord& r : kRstRawRecords) {
                if (!rOptions.WantsArray(r.mName) ||
                    !rst_element_record(file, table, pointers, r.mEntry, values) || values.empty())
                    continue;
                for (double& v : values)
                    if (std::fabs(v) == kRstUndefined)
                        v = std::numeric_limits<double>::quiet_NaN();
                auto& per_block = raw[r.mName];
                if (per_block.empty())
                    per_block.resize(n_blocks);
                per_block[b].emplace_back(row, values);
            }
            if (rst_no_result_cell(types[b]))
                continue;
            RstLayout layout;
            if (const auto it = rModel.mLayout.find(rModel.mModel.mElements[pos].mSlot);
                it != rModel.mLayout.end())
                layout = it->second;
            const std::int64_t* cell_nodes = conn[b] + row * width_of[b];
            const auto nodstr = static_cast<std::size_t>(std::max<std::int64_t>(layout.mNodstr, 0));
            bool have_rotation = false;
            for (const RstTensor& t : kRstTensors) {
                if (!rOptions.WantsArray(t.mName) &&
                    !rOptions.WantsArray(std::string(t.mName) + kRstTop))
                    continue;
                const std::size_t items =
                    t.mEntry == kRstEns && !results.mSparseEns ? 11 : t.mItems;
                if (!nodstr || !rst_element_record(file, table, pointers, t.mEntry, values))
                    continue;
                std::size_t n_layers = static_cast<std::size_t>(layout.mLayers);
                if (values.size() < nodstr * n_layers * items) {
                    n_layers = 1;
                    if (values.size() < nodstr * items)
                        continue;
                }
                // The first six items of each node: xx yy zz xy yz xz.
                std::vector<double> nodes(nodstr * n_layers * 6);
                for (std::size_t i = 0; i < nodstr * n_layers; ++i)
                    for (std::size_t c = 0; c < 6; ++c) {
                        const double v = values[i * items + c];
                        nodes[i * 6 + c] = std::fabs(v) == kRstUndefined
                                               ? std::numeric_limits<double>::quiet_NaN()
                                               : v;
                    }
                if (!have_rotation) {
                    if (!rst_element_record(file, table, pointers, kRstEul, rotation))
                        rotation.clear();
                    have_rotation = true;
                }
                if (rotation.size() >= 3) {
                    const std::size_t per_node = rotation.size() / 3;
                    for (std::size_t i = 0; i < nodstr * n_layers; ++i) {
                        const std::size_t j = per_node == 1 ? 0 : i % per_node;
                        const double* angles = &rotation[3 * j];
                        if (angles[0] == 0.0 && angles[1] == 0.0 && angles[2] == 0.0)
                            continue;
                        const auto q = rst_euler_to_global(angles);
                        rst_rotate_tensor(&nodes[i * 6], q.data(), t.mStress);
                    }
                }
                for (std::size_t layer = 0; layer < n_layers; ++layer) {
                    const std::string key = std::string(t.mName) + (layer ? kRstTop : "");
                    if (!rOptions.WantsArray(key))
                        continue;
                    Accumulator& acc = accumulator(key);
                    double* target = acc.mCells[b].As<double>() + row * npc * 6;
                    for (std::size_t j = 0; j < loc.mSlots.size() && j < width_of[b]; ++j) {
                        const auto slot = static_cast<std::size_t>(loc.mSlots[j]);
                        if (slot >= nodstr)
                            continue;
                        const double* v = &nodes[(layer * nodstr + slot) * 6];
                        std::copy(v, v + 6, target + j * 6);
                        bool finite = true;
                        for (std::size_t c = 0; c < 6; ++c)
                            finite = finite && std::isfinite(v[c]);
                        if (finite) {
                            const auto point = static_cast<std::size_t>(cell_nodes[j]);
                            for (std::size_t c = 0; c < 6; ++c)
                                acc.mSum[point * 6 + c] += v[c];
                            ++acc.mCount[point];
                        }
                    }
                }
            }
            const auto nodfor = static_cast<std::size_t>(std::max<std::int64_t>(layout.mNodfor, 0));
            if (want_enf && nodfor && !dofs.empty() &&
                rst_element_record(file, table, pointers, kRstEnf, values) &&
                values.size() >= nodfor * dofs.size()) {
                if (enf.empty()) {
                    enf_width = dofs.size();
                    rEnfDofs = dofs;
                    for (std::size_t bb = 0; bb < n_blocks; ++bb)
                        enf.push_back([&] {
                            NDArray arr(DType::Float64, {rows_of[bb], npc * enf_width});
                            std::fill(arr.As<double>(), arr.As<double>() + arr.Size(),
                                      std::numeric_limits<double>::quiet_NaN());
                            return arr;
                        }());
                }
                if (dofs.size() != enf_width)
                    continue;
                double* target = enf[b].As<double>() + row * npc * enf_width;
                for (std::size_t j = 0; j < loc.mSlots.size() && j < width_of[b]; ++j) {
                    const auto slot = static_cast<std::size_t>(loc.mSlots[j]);
                    if (slot < nodfor)
                        std::copy(&values[slot * enf_width], &values[slot * enf_width] + enf_width,
                                  target + j * enf_width);
                }
            }
        }
    }
    const auto layout = [&](const std::string& rName, std::size_t Components) {
        NDArray a(DType::Int64, {2});
        a.As<std::int64_t>()[0] = static_cast<std::int64_t>(npc);
        a.As<std::int64_t>()[1] = static_cast<std::int64_t>(Components);
        mesh.AddFieldData("ansys:layout:" + rName, std::move(a));
    };
    for (auto& [name, acc] : tensors) {
        layout(name, 6);
        NDArray mean(DType::Float64, {n_points, 6});
        double* m = mean.As<double>();
        for (std::size_t point = 0; point < n_points; ++point)
            for (std::size_t c = 0; c < 6; ++c)
                m[point * 6 + c] = acc.mCount[point] ? acc.mSum[point * 6 + c] /
                                                           static_cast<double>(acc.mCount[point])
                                                     : std::numeric_limits<double>::quiet_NaN();
        mesh.AddCellData(name, std::move(acc.mCells));
        mesh.AddPointData(name, std::move(mean));
    }
    if (!enf.empty()) {
        layout("ENF", enf_width);
        mesh.AddCellData("ENF", std::move(enf));
    }
    for (auto& [name, per_block] : raw) {
        std::size_t width = 0;
        for (const auto& rows : per_block)
            for (const auto& [row, v] : rows)
                width = std::max(width, v.size());
        std::vector<NDArray> blocks;
        for (std::size_t b = 0; b < n_blocks; ++b) {
            NDArray arr(DType::Float64, {rows_of[b], width});
            double* p = arr.As<double>();
            std::fill(p, p + arr.Size(), std::numeric_limits<double>::quiet_NaN());
            for (const auto& [row, v] : per_block[b])
                std::copy(v.begin(), v.end(), p + row * width);
            blocks.push_back(std::move(arr));
        }
        mesh.AddCellData(name, std::move(blocks));
    }
}

bool rst_is_raw(const std::string& rName) {
    for (const RstRawRecord& r : kRstRawRecords)
        if (rName == r.mName)
            return true;
    return false;
}

// A modal set's other half: the arrays of its mode pair, or of the duplicate
// sector moved onto the base sector's points and cells (zero when neither
// exists: a standing wave), and its harmonic index.
struct RstModal {
    std::int64_t mHarmonic = 0;
    std::map<std::string, NDArray> mPoint;
    std::map<std::string, std::vector<NDArray>> mCell;
};

// The full rotor: the base sector's cells (element numbers up to csEls) and
// their points repeated round the cyclic axis, results rotated with them.
// Coincident nodes on the sector boundaries are not merged. A modal set
// (pModal) is combined with its other half per sector first, as MAPDL's
// /CYCEXPAND does: scale * (x cos(h theta) - x' sin(h theta)).
Mesh rst_expand_cyclic(const RstModel& rModel, const std::vector<std::int64_t>& rEnfDofs,
                       const RstModal* pModal = nullptr) {
    const RstPart& part = *rModel.mParts[0];
    const RstResults& results = part.mResults;
    const Mesh& mesh = rModel.mMesh;
    const auto n = static_cast<std::size_t>(results.mNumSectors);
    double axis[3] = {0.0, 0.0, 1.0}, origin[3] = {0.0, 0.0, 0.0};
    if (results.mCsCord > 1) {
        const auto [axes, o] = part.CoordinateSystem(results.mCsCord);
        const double norm = std::sqrt(axes[6] * axes[6] + axes[7] * axes[7] + axes[8] * axes[8]);
        for (std::size_t d = 0; d < 3; ++d) {
            axis[d] = axes[6 + d] / norm;
            origin[d] = o[d];
        }
    }
    const std::size_t n_blocks = mesh.NumCellBlocks();
    std::vector<std::vector<char>> keep(n_blocks);
    for (std::size_t b = 0; b < n_blocks; ++b)
        keep[b].assign(mesh.Cells(b).NumCells(), 0);
    for (std::size_t pos = 0; pos < rModel.mCells.size(); ++pos) {
        const detail::AnsysCellLocation& loc = rModel.mCells[pos];
        if (loc.mBlock >= 0 && rModel.mModel.mElements[pos].mId <= results.mCsEls)
            keep[static_cast<std::size_t>(loc.mBlock)][static_cast<std::size_t>(loc.mRow)] = 1;
    }
    const std::size_t n_points = mesh.NumPoints();
    std::vector<char> used(n_points, 0);
    for (std::size_t b = 0; b < n_blocks; ++b) {
        const auto view = mesh.Cells(b);
        const std::int64_t* c = view.Conn().template As<std::int64_t>();
        const std::size_t w = view.NodesPerCell();
        for (std::size_t r = 0; r < view.NumCells(); ++r)
            if (keep[b][r])
                for (std::size_t j = 0; j < w; ++j)
                    if (c[r * w + j] >= 0)
                        used[static_cast<std::size_t>(c[r * w + j])] = 1;
    }
    std::vector<std::int64_t> new_point(n_points, -1), old_point;
    for (std::size_t p = 0; p < n_points; ++p)
        if (used[p]) {
            new_point[p] = static_cast<std::int64_t>(old_point.size());
            old_point.push_back(static_cast<std::int64_t>(p));
        }
    const std::size_t n_pts = old_point.size();
    std::vector<std::array<double, 9>> rotations;
    rotations.reserve(n);
    const double pi = std::acos(-1.0);
    for (std::size_t i = 0; i < n; ++i)
        rotations.push_back(
            rst_axis_rotation(axis, 2.0 * pi * static_cast<double>(i) / static_cast<double>(n)));
    // Per sector, the weights of a modal set's two halves.
    std::vector<double> weight(n, 1.0), weight_pair(n, 0.0);
    if (pModal) {
        const std::int64_t h = pModal->mHarmonic;
        const bool single = h == 0 || 2 * std::llabs(h) == static_cast<long long>(n);
        const double scale = single ? 1.0 / std::sqrt(static_cast<double>(n))
                                    : 1.0 / std::sqrt(static_cast<double>(n) / 2.0);
        for (std::size_t i = 0; i < n; ++i) {
            const double phase =
                2.0 * pi * static_cast<double>(h) * static_cast<double>(i) / static_cast<double>(n);
            weight[i] = scale * std::cos(phase);
            weight_pair[i] = -scale * std::sin(phase);
        }
    }
    const auto combine = [&](std::size_t I, double* pData, const double* pPair, std::size_t Count) {
        for (std::size_t k = 0; k < Count; ++k)
            pData[k] = weight[I] * pData[k] + (pPair ? weight_pair[I] * pPair[k] : 0.0);
    };
    const auto rotate = [](const std::array<double, 9>& rQ, const double* pIn, double* pOut) {
        for (std::size_t d = 0; d < 3; ++d)
            pOut[d] = rQ[d * 3] * pIn[0] + rQ[d * 3 + 1] * pIn[1] + rQ[d * 3 + 2] * pIn[2];
    };

    Mesh out;
    {
        const double* src = mesh.Points().template As<double>();
        NDArray points(DType::Float64, {n * n_pts, 3});
        double* dst = points.As<double>();
        for (std::size_t i = 0; i < n; ++i)
            for (std::size_t k = 0; k < n_pts; ++k) {
                const double* p = src + static_cast<std::size_t>(old_point[k]) * 3;
                const double rel[3] = {p[0] - origin[0], p[1] - origin[1], p[2] - origin[2]};
                double* q = dst + (i * n_pts + k) * 3;
                rotate(rotations[i], rel, q);
                for (std::size_t d = 0; d < 3; ++d)
                    q[d] += origin[d];
            }
        out.AssignPoints(std::move(points));
    }
    // Kept blocks and, per kept block, the base mesh's global cell indices.
    std::vector<std::size_t> kept_blocks;
    std::vector<std::vector<std::size_t>> kept_rows;
    std::vector<std::int64_t> new_cell;
    std::int64_t base_cells = 0;
    std::vector<std::int64_t> block_start(n_blocks, 0);
    for (std::size_t b = 0; b < n_blocks; ++b) {
        block_start[b] = base_cells;
        base_cells += static_cast<std::int64_t>(keep[b].size());
    }
    new_cell.assign(static_cast<std::size_t>(base_cells), -1);
    std::vector<std::int64_t> expanded_start;
    std::int64_t expanded = 0;
    for (std::size_t b = 0; b < n_blocks; ++b) {
        std::vector<std::size_t> rows;
        for (std::size_t r = 0; r < keep[b].size(); ++r)
            if (keep[b][r])
                rows.push_back(r);
        if (rows.empty())
            continue;
        for (std::size_t k = 0; k < rows.size(); ++k)
            new_cell[static_cast<std::size_t>(block_start[b]) + rows[k]] =
                static_cast<std::int64_t>(k);
        const auto view = mesh.Cells(b);
        const std::size_t w = view.NodesPerCell();
        const std::int64_t* c = view.Conn().template As<std::int64_t>();
        NDArray conn(DType::Int64, {n * rows.size(), w});
        std::int64_t* dst = conn.As<std::int64_t>();
        for (std::size_t i = 0; i < n; ++i)
            for (std::size_t k = 0; k < rows.size(); ++k)
                for (std::size_t j = 0; j < w; ++j)
                    dst[(i * rows.size() + k) * w + j] =
                        new_point[static_cast<std::size_t>(c[rows[k] * w + j])] +
                        static_cast<std::int64_t>(i * n_pts);
        out.AddCellBlock(view.Type(), std::move(conn));
        kept_blocks.push_back(b);
        kept_rows.push_back(std::move(rows));
        expanded_start.push_back(expanded);
        expanded += static_cast<std::int64_t>(n * kept_rows.back().size());
    }

    // Values rotated with their sector: vectors, tensors, and ENF's UX..UZ and
    // ROTX..ROTZ columns.
    const auto spin = [&](const std::string& rName, std::size_t I, double* pData, std::size_t Count,
                          std::size_t Width, const std::vector<std::int64_t>* pDofs) {
        const auto& q = rotations[I];
        bool stress = false;
        if (Width == 6 && rst_is_tensor(rName, &stress)) {
            for (std::size_t k = 0; k < Count; ++k)
                rst_rotate_tensor(pData + k * 6, q.data(), stress);
        } else if (Width == 3 && rst_is_vector(rName)) {
            for (std::size_t k = 0; k < Count; ++k) {
                double v[3];
                rotate(q, pData + k * 3, v);
                std::copy(v, v + 3, pData + k * 3);
            }
        } else if (pDofs) {
            for (std::int64_t first : {1, 4}) {
                std::size_t idx[3];
                bool all = true;
                for (std::int64_t d = 0; d < 3; ++d) {
                    const auto it = std::find(pDofs->begin(), pDofs->end(), first + d);
                    all = all && it != pDofs->end();
                    if (all)
                        idx[d] = static_cast<std::size_t>(it - pDofs->begin());
                }
                if (!all)
                    continue;
                for (std::size_t k = 0; k < Count; ++k) {
                    double* row = pData + k * Width;
                    const double in[3] = {row[idx[0]], row[idx[1]], row[idx[2]]};
                    double v[3];
                    rotate(q, in, v);
                    for (std::size_t d = 0; d < 3; ++d)
                        row[idx[d]] = v[d];
                }
            }
        }
    };
    for (const std::string& name : mesh.PointDataNames()) {
        const NDArray& src = mesh.PointData(name);
        const std::size_t width = src.Size() / std::max<std::size_t>(n_points, 1);
        std::vector<std::size_t> shape = src.Shape();
        shape[0] = n * n_pts;
        NDArray dst(src.Dtype(), shape);
        const std::size_t item = dtype_size(src.Dtype()) * width;
        const auto* s = reinterpret_cast<const unsigned char*>(src.Data());
        auto* d = reinterpret_cast<unsigned char*>(dst.Data());
        const bool modal = pModal && src.Dtype() == DType::Float64 && !rst_is_raw(name);
        const NDArray* pair = nullptr;
        if (modal)
            if (const auto it = pModal->mPoint.find(name); it != pModal->mPoint.end())
                pair = &it->second;
        for (std::size_t i = 0; i < n; ++i) {
            for (std::size_t k = 0; k < n_pts; ++k) {
                std::memcpy(d + (i * n_pts + k) * item,
                            s + static_cast<std::size_t>(old_point[k]) * item, item);
                if (modal)
                    combine(
                        i, dst.As<double>() + (i * n_pts + k) * width,
                        pair ? pair->As<double>() + static_cast<std::size_t>(old_point[k]) * width
                             : nullptr,
                        width);
            }
            if (src.Dtype() == DType::Float64)
                spin(name, i, dst.As<double>() + i * n_pts * width, n_pts, width, nullptr);
        }
        out.AddPointData(name, std::move(dst));
    }
    for (const std::string& name : mesh.CellDataNames()) {
        std::vector<NDArray> blocks;
        for (std::size_t kb = 0; kb < kept_blocks.size(); ++kb) {
            const std::size_t b = kept_blocks[kb];
            const NDArray& src = mesh.CellData(name, b);
            const std::size_t rows = keep[b].size();
            const std::size_t width = src.Size() / std::max<std::size_t>(rows, 1);
            std::vector<std::size_t> shape = src.Shape();
            shape[0] = n * kept_rows[kb].size();
            NDArray dst(src.Dtype(), shape);
            const std::size_t item = dtype_size(src.Dtype()) * width;
            const auto* s = reinterpret_cast<const unsigned char*>(src.Data());
            auto* d = reinterpret_cast<unsigned char*>(dst.Data());
            const std::size_t count = kept_rows[kb].size();
            const bool modal = pModal && src.Dtype() == DType::Float64 && !rst_is_raw(name);
            const NDArray* pair = nullptr;
            if (modal)
                if (const auto it = pModal->mCell.find(name); it != pModal->mCell.end())
                    pair = &it->second[b];
            for (std::size_t i = 0; i < n; ++i) {
                for (std::size_t k = 0; k < count; ++k) {
                    std::memcpy(d + (i * count + k) * item, s + kept_rows[kb][k] * item, item);
                    if (modal)
                        combine(i, dst.As<double>() + (i * count + k) * width,
                                pair ? pair->As<double>() + kept_rows[kb][k] * width : nullptr,
                                width);
                }
                if (src.Dtype() == DType::Float64) {
                    // Per element node, flattened: width = nodes * components.
                    std::size_t comps = width;
                    if (rst_is_tensor(name, nullptr) && width % 6 == 0)
                        comps = 6;
                    else if (name == "ENF" && !rEnfDofs.empty() && width % rEnfDofs.size() == 0)
                        comps = rEnfDofs.size();
                    spin(name, i, dst.As<double>() + i * count * width, count * (width / comps),
                         comps, name == "ENF" ? &rEnfDofs : nullptr);
                }
            }
            blocks.push_back(std::move(dst));
        }
        out.AddCellData(name, std::move(blocks));
    }
    {
        std::vector<NDArray> sector;
        for (std::size_t kb = 0; kb < kept_blocks.size(); ++kb) {
            const std::size_t count = kept_rows[kb].size();
            NDArray a(DType::Int64, {n * count});
            for (std::size_t i = 0; i < n; ++i)
                std::fill(a.As<std::int64_t>() + i * count, a.As<std::int64_t>() + (i + 1) * count,
                          static_cast<std::int64_t>(i));
            sector.push_back(std::move(a));
        }
        out.AddCellData("ansys:sector", std::move(sector));
    }
    for (const std::string& name : mesh.FieldDataNames())
        out.AddFieldData(name, mesh.FieldData(name));
    {
        NDArray sectors(DType::Int64, {1});
        sectors.As<std::int64_t>()[0] = static_cast<std::int64_t>(n);
        out.AddFieldData("ansys:sectors", std::move(sectors));
    }
    if (pModal) {
        NDArray harmonic(DType::Int64, {1});
        harmonic.As<std::int64_t>()[0] = pModal->mHarmonic;
        out.AddFieldData("ansys:harmonic_index", std::move(harmonic));
    }
    // Block of each base cell among the kept blocks.
    std::vector<std::int64_t> kept_index(n_blocks, -1);
    for (std::size_t kb = 0; kb < kept_blocks.size(); ++kb)
        kept_index[kept_blocks[kb]] = static_cast<std::int64_t>(kb);
    for (std::size_t r = 0; r < mesh.NumRegions(); ++r) {
        const meshioplusplus::Region& region = mesh.Region(r);
        const std::int64_t* e = region.mEntries.template As<std::int64_t>();
        const std::size_t count = region.mEntries.Size();
        std::vector<std::int64_t> entries;
        if (region.mKind == RegionKind::Point) {
            for (std::size_t i = 0; i < n; ++i)
                for (std::size_t k = 0; k < count; ++k)
                    if (e[k] >= 0 && static_cast<std::size_t>(e[k]) < n_points &&
                        new_point[static_cast<std::size_t>(e[k])] >= 0)
                        entries.push_back(new_point[static_cast<std::size_t>(e[k])] +
                                          static_cast<std::int64_t>(i * n_pts));
        } else if (region.mKind == RegionKind::Cell) {
            for (std::size_t k = 0; k < count; ++k) {
                if (e[k] < 0 || e[k] >= base_cells)
                    continue;
                const std::int64_t local = new_cell[static_cast<std::size_t>(e[k])];
                if (local < 0)
                    continue;
                const auto b = static_cast<std::size_t>(
                    std::upper_bound(block_start.begin(), block_start.end(), e[k]) -
                    block_start.begin() - 1);
                const auto kb = static_cast<std::size_t>(kept_index[b]);
                const auto size = static_cast<std::int64_t>(kept_rows[kb].size());
                for (std::size_t i = 0; i < n; ++i)
                    entries.push_back(expanded_start[kb] + static_cast<std::int64_t>(i) * size +
                                      local);
            }
        } else {
            continue;
        }
        NDArray arr(DType::Int64, {entries.size()});
        std::copy(entries.begin(), entries.end(), arr.As<std::int64_t>());
        out.AddRegion(meshioplusplus::Region(region.mName, region.mKind, region.mDim, region.mTag,
                                             std::move(arr)));
    }
    return out;
}

// The other half of modal set Index of a cyclic model: its mode pair (the
// neighbouring set of the same frequency), else the duplicate sector (nodes
// past csNds and elements past csEls, paired with the base sector's in number
// order), else nothing.
RstModal rst_modal(const std::string& rPath, const ReadOptions& rOptions, const RstModel& rModel,
                   std::size_t Index) {
    const RstResults& results = rModel.mParts[0]->mResults;
    RstModal out;
    if (Index < results.mHarmonic.size())
        out.mHarmonic = results.mHarmonic[Index];
    if (rOptions.mPointsOnly)
        return out;
    const std::vector<RstSet>& sets = results.mSets;
    std::size_t pair = sets.size();
    if (sets.size() > 1) {
        const std::size_t before = (Index + sets.size() - 1) % sets.size();
        const std::size_t after = (Index + 1) % sets.size();
        if (rst_close(sets[Index].mTime, sets[before].mTime))
            pair = before;
        else if (rst_close(sets[Index].mTime, sets[after].mTime))
            pair = after;
    }
    const Mesh& mesh = rModel.mMesh;
    if (pair < sets.size()) {
        RstModel other = rst_model(rst_open(rPath, rOptions), rOptions.mLenient);
        std::vector<std::int64_t> dofs;
        rst_solution(other, pair, rOptions);
        rst_reactions(other, pair, rOptions);
        rst_elements(other, pair, rOptions, dofs);
        for (const std::string& name : other.mMesh.PointDataNames())
            out.mPoint.emplace(name, other.mMesh.PointData(name));
        for (const std::string& name : other.mMesh.CellDataNames()) {
            std::vector<NDArray> blocks;
            blocks.reserve(other.mMesh.NumCellBlocks());
            for (std::size_t b = 0; b < other.mMesh.NumCellBlocks(); ++b)
                blocks.push_back(other.mMesh.CellData(name, b));
            out.mCell.emplace(name, std::move(blocks));
        }
        return out;
    }
    // The duplicate sector, paired with the base sector in number order.
    std::vector<std::pair<std::int64_t, std::int64_t>> base_nodes, dup_nodes;
    for (const auto& [number, point] : rModel.mNodeIndex)
        (number <= results.mCsNds ? base_nodes : dup_nodes).emplace_back(number, point);
    if (dup_nodes.empty() || dup_nodes.size() != base_nodes.size())
        return out;
    std::sort(base_nodes.begin(), base_nodes.end());
    std::sort(dup_nodes.begin(), dup_nodes.end());
    std::vector<std::tuple<std::int64_t, std::int64_t, std::int64_t>> base_cells, dup_cells;
    for (std::size_t pos = 0; pos < rModel.mCells.size(); ++pos) {
        const detail::AnsysCellLocation& loc = rModel.mCells[pos];
        if (loc.mBlock < 0)
            continue;
        const std::int64_t id = rModel.mModel.mElements[pos].mId;
        (id <= results.mCsEls ? base_cells : dup_cells).emplace_back(id, loc.mBlock, loc.mRow);
    }
    std::sort(base_cells.begin(), base_cells.end());
    std::sort(dup_cells.begin(), dup_cells.end());
    for (const std::string& name : mesh.PointDataNames()) {
        const NDArray& src = mesh.PointData(name);
        if (src.Dtype() != DType::Float64)
            continue;
        const std::size_t width = src.Size() / std::max<std::size_t>(mesh.NumPoints(), 1);
        NDArray dst(DType::Float64, src.Shape());
        std::fill(dst.As<double>(), dst.As<double>() + dst.Size(), 0.0);
        for (std::size_t k = 0; k < base_nodes.size(); ++k)
            std::copy_n(src.As<double>() + static_cast<std::size_t>(dup_nodes[k].second) * width,
                        width,
                        dst.As<double>() + static_cast<std::size_t>(base_nodes[k].second) * width);
        out.mPoint.emplace(name, std::move(dst));
    }
    if (dup_cells.size() != base_cells.size())
        return out;
    for (const std::string& name : mesh.CellDataNames()) {
        std::vector<NDArray> blocks;
        bool ok = true;
        for (std::size_t b = 0; b < mesh.NumCellBlocks(); ++b) {
            const NDArray& src = mesh.CellData(name, b);
            ok = ok && src.Dtype() == DType::Float64;
            NDArray dst(src.Dtype(), src.Shape());
            std::memset(dst.Data(), 0, dst.Size() * dtype_size(dst.Dtype()));
            blocks.push_back(std::move(dst));
        }
        if (!ok)
            continue;
        for (std::size_t k = 0; k < base_cells.size(); ++k) {
            const auto [bid, bb, br] = base_cells[k];
            const auto [did, db, dr] = dup_cells[k];
            const NDArray& src = mesh.CellData(name, static_cast<std::size_t>(db));
            const std::size_t w = src.Size() / std::max<std::size_t>(src.Shape()[0], 1);
            const std::size_t wb =
                blocks[static_cast<std::size_t>(bb)].Size() /
                std::max<std::size_t>(blocks[static_cast<std::size_t>(bb)].Shape()[0], 1);
            if (w != wb)
                continue;
            std::copy_n(src.As<double>() + static_cast<std::size_t>(dr) * w, w,
                        blocks[static_cast<std::size_t>(bb)].As<double>() +
                            static_cast<std::size_t>(br) * w);
        }
        out.mCell.emplace(name, std::move(blocks));
    }
    return out;
}

Mesh rst_read(const std::string& rPath, const ReadOptions& rOptions, bool Cyclic) {
    std::vector<std::unique_ptr<RstPart>> parts = rst_open(rPath, rOptions);
    const RstResults& main = parts[0]->mResults;
    if (Cyclic) {
        if (main.mNumSectors <= 1)
            rst_fail("not a cyclic-symmetry model; read it as ansys_rst");
        if (main.mKan != 0 && main.mKan != 2)
            rst_fail(
                "only static and modal cyclic-symmetry results can be expanded (this is "
                "analysis type " +
                std::to_string(main.mKan) + "); read the base sector as ansys_rst");
    } else if (main.mNumSectors > 1) {
        log::warn(
            "Ansys .rst: a cyclic-symmetry model ({} sectors); only the base sector is read "
            "(ansys_rst_cyclic expands it)",
            main.mNumSectors);
    }
    RstModel model = rst_model(std::move(parts), rOptions.mLenient);
    const RstResults& results = model.mParts[0]->mResults;
    // Nodes with their own coordinate system: the angles, so a writer can rotate vectors back.
    if (!Cyclic && rOptions.WantsArray("ansys:node_angles") &&
        std::any_of(model.mAngles.begin(), model.mAngles.end(),
                    [](double A) { return A != 0.0; })) {
        NDArray angles(DType::Float64, {model.mAngles.size() / 3, 3});
        std::copy(model.mAngles.begin(), model.mAngles.end(), angles.As<double>());
        model.mMesh.AddPointData("ansys:node_angles", std::move(angles));
    }
    if (!Cyclic && results.mNumSectors > 1) {
        NDArray sectors(DType::Int64, {1});
        sectors.As<std::int64_t>()[0] = results.mNumSectors;
        model.mMesh.AddFieldData("ansys:cyclic_sectors", std::move(sectors));
    }
    std::vector<std::int64_t> enf_dofs;
    const std::size_t n = results.mSets.size();
    if (n == 0) {
        if (rOptions.mTimeStep != 0 && rOptions.mTimeStep != -1)
            rst_fail("time step " + std::to_string(rOptions.mTimeStep) +
                     " is out of range: the file has no result sets");
        return Cyclic ? rst_expand_cyclic(model, enf_dofs) : std::move(model.mMesh);
    }
    const std::size_t index = rOptions.ResolveTimeStep(n);
    const RstSet& set = results.mSets[index];
    const auto scalar = [](DType T, double V) {
        NDArray a(T, {1});
        if (T == DType::Float64)
            a.As<double>()[0] = V;
        else
            a.As<std::int64_t>()[0] = static_cast<std::int64_t>(V);
        return a;
    };
    Mesh& mesh = model.mMesh;
    mesh.AddFieldData("meshio:time", scalar(DType::Float64, set.mTime));
    mesh.AddFieldData("ansys:load_step", scalar(DType::Int64, static_cast<double>(set.mLoadStep)));
    mesh.AddFieldData("ansys:substep", scalar(DType::Int64, static_cast<double>(set.mSubstep)));
    mesh.AddFieldData("ansys:cumulative",
                      scalar(DType::Int64, static_cast<double>(set.mCumulative)));
    if (!Cyclic && index < results.mHarmonic.size() && results.mNumSectors > 1)
        mesh.AddFieldData("ansys:harmonic_index",
                          scalar(DType::Int64, static_cast<double>(results.mHarmonic[index])));
    if (!rOptions.mPointsOnly) {
        rst_solution(model, index, rOptions);
        rst_reactions(model, index, rOptions);
        rst_elements(model, index, rOptions, enf_dofs);
    }
    if (Cyclic && results.mKan == 2) {
        const RstModal modal = rst_modal(rPath, rOptions, model, index);
        return rst_expand_cyclic(model, enf_dofs, &modal);
    }
    return Cyclic ? rst_expand_cyclic(model, enf_dofs) : std::move(model.mMesh);
}

MeshMetadata rst_metadata(const std::string& rPath, const ReadOptions& rOptions, bool Cyclic,
                          const char* pFormat) {
    ReadOptions options = rOptions;
    options.mPointsOnly = true;
    options.mTimeStep = 0;
    options.mLenient = true;  // a summary skips (and warns about) cell-less elements
    MeshMetadata meta = metadata_from_mesh(rst_read(rPath, options, Cyclic));
    meta.mFellBackToFullRead = true;
    meta.mFormat = pFormat;
    const RstFile file(rPath, rOptions);
    for (const RstSet& s : RstResults(file).mSets)
        meta.mTimeValues.push_back(s.mTime);
    return meta;
}

}  // namespace

Mesh read_ansys_rst(const std::string& rPath, const ReadOptions& rOptions) {
    return rst_read(rPath, rOptions, false);
}

Mesh read_ansys_rst_cyclic(const std::string& rPath, const ReadOptions& rOptions) {
    return rst_read(rPath, rOptions, true);
}

MeshMetadata read_ansys_rst_metadata(const std::string& rPath, const ReadOptions& rOptions) {
    return rst_metadata(rPath, rOptions, false, "ansys_rst");
}

MeshMetadata read_ansys_rst_cyclic_metadata(const std::string& rPath, const ReadOptions& rOptions) {
    return rst_metadata(rPath, rOptions, true, "ansys_rst_cyclic");
}

// ---------------------------------------------------------------------------
// The writer: the reader's inverse (little-endian, 64-bit pointers, uncompressed). The
// Python twin (`ansys_rst/_write.py`) writes the same bytes.
// ---------------------------------------------------------------------------
namespace {

[[noreturn]] void rstw_fail(const std::string& rMessage) {
    throw WriteError("Ansys .rst: " + rMessage);
}

std::int32_t rstw_i32(std::int64_t Value) {
    return static_cast<std::int32_t>(static_cast<std::uint32_t>(static_cast<std::uint64_t>(Value)));
}

/// A name as `Count` 4-character words, each read big-endian (the reader's name).
std::vector<std::int64_t> rstw_text_words(const std::string& rText, std::size_t Count) {
    std::string raw = rText.substr(0, 4 * Count);
    raw.resize(4 * Count, ' ');
    std::vector<std::int64_t> out(Count);
    for (std::size_t k = 0; k < Count; ++k) {
        std::uint32_t v = 0;
        for (std::size_t j = 0; j < 4; ++j)
            v = (v << 8) | static_cast<unsigned char>(raw[4 * k + j]);
        out[k] = rstw_i32(v);
    }
    return out;
}

/// The file as int32 words: records of length, flags, data and a trailer.
class RstwWords {
public:
    std::size_t Record(const std::vector<std::int32_t>& rData, unsigned Flags) {
        const std::size_t ptr = mW.size();
        mW.push_back(static_cast<std::int32_t>(rData.size()));
        mW.push_back(rstw_i32(static_cast<std::int64_t>(Flags) << 24));
        mW.insert(mW.end(), rData.begin(), rData.end());
        mW.push_back(static_cast<std::int32_t>(rData.size()));
        return ptr;
    }
    std::size_t Ints(const std::vector<std::int64_t>& rValues, std::size_t Size = 0) {
        std::vector<std::int32_t> data;
        for (const std::int64_t v : rValues)
            data.push_back(rstw_i32(v));
        if (Size > data.size())
            data.resize(Size, 0);
        return Record(data, 0x80);
    }
    std::size_t Doubles(const std::vector<double>& rValues) {
        std::vector<std::int32_t> data(2 * rValues.size());
        if (!rValues.empty())
            std::memcpy(data.data(), rValues.data(), rValues.size() * sizeof(double));
        return Record(data, 0x00);
    }
    void Patch(std::size_t Ptr, std::size_t K, std::int64_t Value) {
        mW[Ptr + 2 + K] = rstw_i32(Value);
    }
    void Patch64(std::size_t Ptr, std::size_t Lo, std::size_t Hi, std::int64_t Value) {
        Patch(Ptr, Lo, Value & 0xFFFFFFFFLL);
        Patch(Ptr, Hi, Value >> 32);
    }
    std::size_t Size() const { return mW.size(); }
    const std::vector<std::int32_t>& Words() const { return mW; }

private:
    std::vector<std::int32_t> mW;
};

struct RstwElement {
    std::size_t mBlock = 0, mRow = 0;
    int mRoutine = 0, mSlot = 0;
    std::vector<std::int64_t> mNodes;  // the element's order, 1-based
    std::vector<int> mCellSlots;       // the element node each cell node became
};

struct RstwSlotInfo {
    int mRoutine = 0;
    std::size_t mNodelm = 0, mNodstr = 0;
};

struct RstwComponent {
    std::string mName;
    bool mNodes = false;
    std::vector<std::int64_t> mIds;
};

class RstwModel {
public:
    explicit RstwModel(const Mesh& rMesh) {
        mNnod = rMesh.NumPoints();
        if (mNnod == 0)
            rstw_fail("the mesh has no points");
        if (rMesh.HasFieldData("ansys:cyclic_sectors") &&
            rMesh.FieldData("ansys:cyclic_sectors").Size() > 0) {
            mSectors = detail::Int64View(rMesh.FieldData("ansys:cyclic_sectors")).Data()[0];
            if (mSectors < 1)
                rstw_fail("'ansys:cyclic_sectors' must be at least 1");
        }
        const NDArray& pts = rMesh.Points();
        const detail::DoubleView view(pts);
        const std::size_t width = pts.Size() / mNnod;
        mPoints.assign(mNnod * 3, 0.0);
        for (std::size_t i = 0; i < mNnod; ++i)
            for (std::size_t k = 0; k < 3 && k < width; ++k)
                mPoints[i * 3 + k] = view.Data()[i * width + k];
        for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
            const auto cb = rMesh.Cells(b);
            const detail::Int64View conn(cb.Conn());
            for (std::size_t i = 0; i < cb.NumCells() * cb.NodesPerCell(); ++i)
                if (conn.Data()[i] < 0 || static_cast<std::size_t>(conn.Data()[i]) >= mNnod)
                    rstw_fail("a '" + std::string(cb.Type()) +
                              "' cell refers to a point the mesh does not have");
        }
        const detail::AnsysElementTypes types =
            detail::ansys_element_types(rMesh, "Ansys .rst writer");
        for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
            const auto cb = rMesh.Cells(b);
            const std::string type(cb.Type());
            mHasResults.push_back(type != "vertex" && type != "line" && type != "line3");
            const std::size_t k = cb.NodesPerCell();
            const detail::Int64View conn(cb.Conn());
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                RstwElement e;
                e.mBlock = b;
                e.mRow = r;
                e.mRoutine = types.mCellEtype[b][r].first;
                e.mSlot = types.mCellEtype[b][r].second;
                const std::vector<int> layout =
                    detail::ansys_cell_layout(type, detail::ansys_category(e.mRoutine));
                std::map<int, int> first;
                for (std::size_t c = 0; c < layout.size(); ++c)
                    first.emplace(layout[c], static_cast<int>(c));
                for (const int j : layout)
                    e.mNodes.push_back(conn.Data()[r * k + static_cast<std::size_t>(j)] + 1);
                for (std::size_t j = 0; j < k; ++j)
                    e.mCellSlots.push_back(first[static_cast<int>(j)]);
                mElements.push_back(std::move(e));
            }
        }
        mNelm = mElements.size();
        if (rMesh.HasPointData("ansys:node_angles")) {
            const NDArray& a = rMesh.PointData("ansys:node_angles");
            if (a.Size() == mNnod * 3) {
                const detail::DoubleView angles(a);
                mAngles.assign(angles.Data(), angles.Data() + a.Size());
                for (double& v : mAngles)
                    if (!std::isfinite(v))
                        v = 0.0;
            } else {
                log::warn("Ansys .rst writer: 'ansys:node_angles' is not (points, 3); dropped");
            }
        }
        for (const RstwElement& e : mElements) {
            RstwSlotInfo& info = mSlots[e.mSlot];
            info.mRoutine = e.mRoutine;
            info.mNodelm = std::max(info.mNodelm, e.mNodes.size());
            info.mNodstr =
                std::max(info.mNodstr, detail::ansys_num_corners(rMesh.Cells(e.mBlock).Type()));
        }
        std::size_t sides = 0;
        for (std::size_t i = 0; i < rMesh.NumRegions(); ++i) {
            const Region& reg = rMesh.Region(i);
            if (reg.mKind == RegionKind::Side) {
                ++sides;
                continue;
            }
            std::set<std::int64_t> ids;
            for (std::size_t q = 0; q < reg.NumEntries(); ++q)
                ids.insert(reg.Entries()[q] + 1);
            mComponents.push_back({reg.mName, reg.mKind == RegionKind::Point,
                                   std::vector<std::int64_t>(ids.begin(), ids.end())});
        }
        if (sides)
            log::warn("Ansys .rst writer: side regions have no component equivalent; dropped");
        auto column = [&](const char* pName, const RstwElement& rE) -> std::int64_t {
            if (!rMesh.HasCellData(pName))
                return 1;
            const NDArray& a = rMesh.CellData(pName, rE.mBlock);
            return a.Size() <= rE.mRow ? 1 : detail::read_int(a, rE.mRow);
        };
        for (const RstwElement& e : mElements) {
            mMat.push_back(column("ansys:mat", e));
            mReal.push_back(column("ansys:real", e));
            mSecnum.push_back(column("ansys:secnum", e));
        }
        for (const std::string& name : rMesh.CellDataNames())
            if (name.size() >= 4 && name.compare(name.size() - 4, 4, kRstTop) == 0)
                mLayered = true;
        mSignature = std::to_string(mNnod) + "|" + std::to_string(mLayered);
        for (const RstwElement& e : mElements) {
            mSignature += "|" + std::to_string(e.mRoutine) + "," + std::to_string(e.mSlot);
            for (const std::int64_t n : e.mNodes)
                mSignature += "," + std::to_string(n);
        }
        for (const RstwComponent& c : mComponents) {
            mSignature += "#" + c.mName + (c.mNodes ? "n" : "e");
            for (const std::int64_t v : c.mIds)
                mSignature += "," + std::to_string(v);
        }
    }

    std::size_t mNnod = 0, mNelm = 0;
    std::int64_t mSectors = 1;  // a cyclic-symmetry sector: the model's sector count
    std::vector<double> mPoints;
    std::vector<double> mAngles;  // THXY, THYZ, THZX per node (degrees), or empty
    std::vector<RstwElement> mElements;
    std::vector<bool> mHasResults;
    std::map<int, RstwSlotInfo> mSlots;
    std::vector<RstwComponent> mComponents;
    std::vector<std::int64_t> mMat, mReal, mSecnum;
    bool mLayered = false;
    std::string mSignature;
};

struct RstwTensor {
    std::string mName;        // "S", "S@top" ...
    std::size_t mTensor = 0;  // index in kRstTensors
    bool mTop = false;
};

// AvailData bit k is item k (resucm.inc).
constexpr int kRstwBitNsl = 27, kRstwBitRf = 30;

struct RstwSet {
    double mTime = 0.0;
    std::array<std::int64_t, 3> mStep{1, 1, 1};
    std::vector<std::int64_t> mDofs;
    std::vector<double> mNodal;  // nnod x dofs
    struct Reaction {
        std::size_t mPoint;
        std::int64_t mCode;
        double mValue;
    };
    std::vector<Reaction> mReactions;
    std::vector<RstwTensor> mTensors;
    std::vector<const RstRawRecord*> mRaw;  ///< raw element records present in the mesh
    bool mEnf = false;                      ///< element nodal forces, one value per DOF
    std::int64_t mMask = 0;
    std::optional<std::int64_t> mHarmonic;  ///< a cyclic modal set's harmonic index
};

RstwSet rstw_set(const Mesh& rMesh, const RstwModel& rModel, double Time,
                 std::array<std::int64_t, 3> Step) {
    RstwSet s;
    s.mTime = Time;
    s.mStep = Step;
    if (rMesh.HasFieldData("ansys:harmonic_index") &&
        rMesh.FieldData("ansys:harmonic_index").Size() > 0)
        s.mHarmonic = detail::Int64View(rMesh.FieldData("ansys:harmonic_index")).Data()[0];
    const std::size_t n = rModel.mNnod;
    std::map<std::int64_t, std::vector<double>> columns;
    auto values_of = [&](const std::string& rName) {
        const NDArray& a = rMesh.PointData(rName);
        const detail::DoubleView view(a);
        return std::vector<double>(view.Data(), view.Data() + a.Size());
    };
    auto is_triple = [&](const std::string& rName) {
        const NDArray& a = rMesh.PointData(rName);
        return a.Shape().size() == 2 && a.Shape()[0] == n && a.Shape()[1] == 3;
    };
    static const std::pair<const char*, std::int64_t> kVectorDofs[] = {
        {"U", 1}, {"ROT", 4}, {"A", 7}, {"V", 10}};
    for (const auto& [name, first] : kVectorDofs) {
        if (!rMesh.HasPointData(name))
            continue;
        if (!is_triple(name)) {
            log::warn("Ansys .rst writer: point data '{}' is not (points, 3); dropped", name);
            continue;
        }
        std::vector<double> a = values_of(name);
        // The mesh holds global vectors; the file holds them in the nodes' own axes.
        if (!rModel.mAngles.empty())
            for (std::size_t i = 0; i < n; ++i)
                if (std::isfinite(a[i * 3]) && std::isfinite(a[i * 3 + 1]) &&
                    std::isfinite(a[i * 3 + 2]))
                    rst_unrotate(&a[i * 3], &rModel.mAngles[i * 3]);
        for (std::int64_t d = 0; d < 3; ++d) {
            std::vector<double> col(n);
            for (std::size_t i = 0; i < n; ++i)
                col[i] = a[i * 3 + static_cast<std::size_t>(d)];
            columns[first + d] = std::move(col);
        }
    }
    for (std::int64_t code = 16; code <= 26; ++code) {
        const char* name = rst_scalar_name(code);
        if (!name || !rMesh.HasPointData(name))
            continue;
        const std::vector<double> a = values_of(name);
        if (a.size() == n)
            columns[code] = a;
        else
            log::warn("Ansys .rst writer: point data '{}' is not (points,); dropped", name);
    }
    static const std::pair<const char*, std::int64_t> kReactionVectors[] = {{"RF", 1}, {"RMOM", 4}};
    for (const auto& [name, first] : kReactionVectors) {
        if (!rMesh.HasPointData(name))
            continue;
        if (!is_triple(name)) {
            log::warn("Ansys .rst writer: point data '{}' is not (points, 3); dropped", name);
            continue;
        }
        std::vector<double> a = values_of(name);
        if (!rModel.mAngles.empty())
            for (std::size_t p = 0; p < n; ++p)
                if (std::isfinite(a[p * 3]) && std::isfinite(a[p * 3 + 1]) &&
                    std::isfinite(a[p * 3 + 2]))
                    rst_unrotate(&a[p * 3], &rModel.mAngles[p * 3]);
        for (std::int64_t d = 0; d < 3; ++d)
            for (std::size_t p = 0; p < n; ++p)
                if (std::isfinite(a[p * 3 + static_cast<std::size_t>(d)]))
                    s.mReactions.push_back({p, first + d, a[p * 3 + static_cast<std::size_t>(d)]});
    }
    std::vector<std::int64_t> scalar_codes;
    for (std::int64_t code = 7; code <= 26; ++code)
        if (code <= 12 || rst_scalar_name(code))
            scalar_codes.push_back(code);
    for (const std::int64_t code : scalar_codes) {
        const std::string name = "RF_" + rst_dof_label(code);
        if (!rMesh.HasPointData(name))
            continue;
        const std::vector<double> a = values_of(name);
        if (a.size() != n)
            continue;
        for (std::size_t p = 0; p < n; ++p)
            if (std::isfinite(a[p]))
                s.mReactions.push_back({p, code, a[p]});
    }
    std::set<std::int64_t> used;
    for (const auto& [code, col] : columns)
        used.insert(code);
    for (const auto& r : s.mReactions)
        used.insert(r.mCode);
    s.mDofs.assign(used.begin(), used.end());
    s.mNodal.assign(n * s.mDofs.size(), kRstUndefined);
    for (std::size_t k = 0; k < s.mDofs.size(); ++k) {
        const auto it = columns.find(s.mDofs[k]);
        if (it == columns.end())
            continue;
        for (std::size_t i = 0; i < n; ++i)
            s.mNodal[i * s.mDofs.size() + k] =
                std::isfinite(it->second[i]) ? it->second[i] : kRstUndefined;
    }
    static const std::int64_t kBits[] = {3, 6, 7, 8, 9};  // S, EPEL, EPPL, EPCR, EPTH
    for (std::size_t t = 0; t < std::size(kRstTensors); ++t)
        for (const bool top : {false, true}) {
            const std::string name = std::string(kRstTensors[t].mName) + (top ? kRstTop : "");
            if (rMesh.HasCellData(name)) {
                s.mTensors.push_back({name, t, top});
                s.mMask |= std::int64_t{1} << kBits[t];
            }
        }
    for (const RstRawRecord& r : kRstRawRecords)
        if (rMesh.HasCellData(r.mName)) {
            s.mRaw.push_back(&r);
            s.mMask |= std::int64_t{1} << (r.mEntry + 1);
        }
    if (rMesh.HasCellData("ENF")) {
        const bool layout = rMesh.HasFieldData("ansys:layout:ENF") &&
                            rMesh.FieldData("ansys:layout:ENF").Size() >= 2 &&
                            static_cast<std::size_t>(detail::read_int(
                                rMesh.FieldData("ansys:layout:ENF"), 1)) == s.mDofs.size() &&
                            !s.mDofs.empty();
        if (layout) {
            s.mEnf = true;
            s.mMask |= std::int64_t{1} << (kRstEnf + 1);
        } else {
            log::warn("Ansys .rst writer: ENF needs its layout over the set's DOFs; dropped");
        }
    }
    if (!columns.empty() || !s.mReactions.empty())
        s.mMask |= std::int64_t{1} << kRstwBitNsl;
    if (!s.mReactions.empty())
        s.mMask |= std::int64_t{1} << kRstwBitRf;
    return s;
}

std::size_t rstw_element_solution(RstwWords& rF, const Mesh& rMesh, const RstwModel& rModel,
                                  const RstwSet& rSet, std::size_t Base) {
    const std::size_t esl = rF.Ints(std::vector<std::int64_t>(2 * rModel.mNelm, 0));
    rF.Patch64(Base, 118, 119, static_cast<std::int64_t>(esl - Base));
    const std::size_t numdof = rSet.mDofs.size();
    for (std::size_t k = 0; k < rModel.mElements.size(); ++k) {
        const RstwElement& e = rModel.mElements[k];
        const RstwSlotInfo& info = rModel.mSlots.at(e.mSlot);
        std::vector<std::pair<std::size_t, std::vector<double>>> pending;
        // raw records: the values up to the last one the element has
        for (const RstRawRecord* raw : rSet.mRaw) {
            if (e.mBlock >= rMesh.CellDataNumBlocks(raw->mName))
                continue;
            const NDArray& a = rMesh.CellData(raw->mName, e.mBlock);
            const std::size_t count = rMesh.Cells(e.mBlock).NumCells();
            if (a.Shape().size() != 2 || count <= e.mRow)
                continue;
            const std::size_t width = a.Shape()[1];
            const detail::DoubleView view(a);
            std::size_t last = 0;
            bool any = false;
            for (std::size_t c = 0; c < width; ++c)
                if (std::isfinite(view.Data()[e.mRow * width + c])) {
                    last = c;
                    any = true;
                }
            if (!any)
                continue;
            std::vector<double> row(last + 1);
            for (std::size_t c = 0; c <= last; ++c) {
                const double v = view.Data()[e.mRow * width + c];
                row[c] = std::isfinite(v) ? v : kRstUndefined;
            }
            pending.emplace_back(raw->mEntry, std::move(row));
        }
        if (rModel.mHasResults[e.mBlock]) {
            // per tensor: surfaces[top] -> (npc, 6) rows
            struct Surfaces {
                std::size_t mTensor = 0;
                std::map<bool, std::vector<double>> mRows;
            };
            std::vector<Surfaces> entries;
            for (const RstwTensor& t : rSet.mTensors) {
                const NDArray& a = rMesh.CellData(t.mName, e.mBlock);
                const std::size_t count = rMesh.Cells(e.mBlock).NumCells();
                if (a.Shape().size() != 2 || count <= e.mRow)
                    continue;
                const std::size_t width = a.Shape()[1];
                const std::size_t npc = width / 6;
                if (npc == 0 || width % 6)
                    continue;
                const detail::DoubleView view(a);
                std::vector<double> row(view.Data() + e.mRow * width,
                                        view.Data() + (e.mRow + 1) * width);
                auto it = std::find_if(entries.begin(), entries.end(),
                                       [&](const Surfaces& s) { return s.mTensor == t.mTensor; });
                if (it == entries.end()) {
                    entries.push_back({t.mTensor, {}});
                    it = entries.end() - 1;
                }
                it->mRows[t.mTop] = std::move(row);
            }
            const std::size_t nodstr = info.mNodstr;
            const std::size_t layers =
                (e.mRoutine == 181 || e.mRoutine == 281) && rModel.mLayered ? 2 : 1;
            // The element's rotation (EUL), one set or one per node: the mesh holds global
            // tensors and the file the element's own, so each is turned back.
            std::vector<double> rotation;
            if (rMesh.HasCellData("EUL") && e.mBlock < rMesh.CellDataNumBlocks("EUL")) {
                const NDArray& a = rMesh.CellData("EUL", e.mBlock);
                if (a.Shape().size() == 2 && rMesh.Cells(e.mBlock).NumCells() > e.mRow) {
                    const detail::DoubleView view(a);
                    const std::size_t width = a.Shape()[1];
                    for (std::size_t c = 0; c < width; ++c) {
                        if (!std::isfinite(view.Data()[e.mRow * width + c]))
                            break;
                        rotation.push_back(view.Data()[e.mRow * width + c]);
                    }
                    rotation.resize(rotation.size() - rotation.size() % 3);
                }
            }
            for (const Surfaces& surfaces : entries) {
                const std::size_t items = kRstTensors[surfaces.mTensor].mItems;
                std::vector<double> values(nodstr * layers * items, kRstUndefined);
                for (std::size_t row = 0; row < nodstr * layers; ++row)
                    for (std::size_t c = 6; c < items; ++c)
                        values[row * items + c] = 0.0;
                bool any = false;
                for (const auto& [top, data] : surfaces.mRows) {
                    if (top && layers == 1)
                        continue;
                    const std::size_t layer = top && layers == 2 ? 1 : 0;
                    const std::size_t npc = data.size() / 6;
                    for (std::size_t j = 0; j < e.mCellSlots.size(); ++j) {
                        const std::size_t slot = static_cast<std::size_t>(e.mCellSlots[j]);
                        if (j >= npc || slot >= nodstr)
                            continue;
                        bool finite = true;
                        for (std::size_t c = 0; c < 6; ++c)
                            finite = finite && std::isfinite(data[j * 6 + c]);
                        if (!finite)
                            continue;
                        for (std::size_t c = 0; c < 6; ++c)
                            values[(layer * nodstr + slot) * items + c] = data[j * 6 + c];
                        if (rotation.size() >= 3) {
                            const std::size_t at = layer * nodstr + slot;
                            const std::size_t per_node = rotation.size() / 3;
                            const double* angles =
                                &rotation[3 * (per_node == 1 ? 0 : at % per_node)];
                            if (angles[0] != 0.0 || angles[1] != 0.0 || angles[2] != 0.0) {
                                const auto q = rst_euler_to_global(angles);
                                const double qt[9] = {q[0], q[3], q[6], q[1], q[4],
                                                      q[7], q[2], q[5], q[8]};
                                rst_rotate_tensor(&values[at * items], qt,
                                                  kRstTensors[surfaces.mTensor].mStress);
                            }
                        }
                        any = true;
                    }
                }
                if (any)
                    pending.emplace_back(kRstTensors[surfaces.mTensor].mEntry, std::move(values));
            }
            if (rSet.mEnf && info.mNodelm && numdof && e.mBlock < rMesh.CellDataNumBlocks("ENF")) {
                const NDArray& a = rMesh.CellData("ENF", e.mBlock);
                const std::size_t count = rMesh.Cells(e.mBlock).NumCells();
                if (a.Shape().size() == 2 && count > e.mRow && a.Shape()[1] % numdof == 0) {
                    const std::size_t npc = a.Shape()[1] / numdof;
                    const detail::DoubleView view(a);
                    std::vector<double> forces(info.mNodelm * numdof, 0.0);
                    bool any = false;
                    for (std::size_t j = 0; j < e.mCellSlots.size(); ++j) {
                        const std::size_t slot = static_cast<std::size_t>(e.mCellSlots[j]);
                        if (j >= npc || slot >= info.mNodelm)
                            continue;
                        bool finite = true;
                        for (std::size_t c = 0; c < numdof; ++c)
                            finite =
                                finite &&
                                std::isfinite(view.Data()[e.mRow * a.Shape()[1] + j * numdof + c]);
                        if (!finite)
                            continue;
                        for (std::size_t c = 0; c < numdof; ++c)
                            forces[slot * numdof + c] =
                                view.Data()[e.mRow * a.Shape()[1] + j * numdof + c];
                        any = true;
                    }
                    if (any)
                        pending.emplace_back(kRstEnf, std::move(forces));
                }
            }
        }
        if (pending.empty())
            continue;
        const std::size_t table = rF.Ints(std::vector<std::int64_t>(25, 0));
        for (const auto& [entry, values] : pending) {
            const std::size_t ptr = rF.Doubles(values);
            rF.Patch(table, entry, static_cast<std::int64_t>(ptr - table));
        }
        rF.Patch(esl, 2 * k, static_cast<std::int64_t>(table - esl));
    }
    return esl;
}

std::size_t rstw_set_records(RstwWords& rF, const Mesh& rMesh, const RstwModel& rModel,
                             const RstwSet& rSet) {
    const std::size_t numdof = rSet.mDofs.size();
    const std::size_t base = rF.Ints(std::vector<std::int64_t>(150, 0));
    rF.Patch(base, 1, static_cast<std::int64_t>(rModel.mNelm));
    rF.Patch(base, 2, static_cast<std::int64_t>(rModel.mNnod));
    rF.Patch(base, 3, 0);
    rF.Patch(base, 19, static_cast<std::int64_t>(numdof));
    for (std::size_t k = 0; k < numdof; ++k)
        rF.Patch(base, 20 + k, rSet.mDofs[k]);
    rF.Patch(base, 146, rSet.mMask);
    if (numdof) {
        const std::size_t nsl = rF.Doubles(rSet.mNodal);
        rF.Patch64(base, 104, 105, static_cast<std::int64_t>(nsl - base));
    }
    if (!rSet.mReactions.empty()) {
        std::map<std::int64_t, std::size_t> order;
        for (std::size_t k = 0; k < numdof; ++k)
            order[rSet.mDofs[k]] = k;
        std::vector<std::int64_t> table;
        std::vector<double> values;
        for (const auto& r : rSet.mReactions) {
            const std::int64_t index =
                static_cast<std::int64_t>(r.mPoint * numdof + order[r.mCode] + 1);
            table.push_back(index & 0xFFFFFFFFLL);
            table.push_back(index >> 32);
            values.push_back(r.mValue);
        }
        const std::size_t rf = rF.Ints(table);
        rF.Doubles(values);
        rF.Patch(base, 7, static_cast<std::int64_t>(rSet.mReactions.size()));
        rF.Patch64(base, 106, 107, static_cast<std::int64_t>(rf - base));
    }
    if (!rSet.mTensors.empty() || !rSet.mRaw.empty() || rSet.mEnf)
        rstw_element_solution(rF, rMesh, rModel, rSet, base);
    return base;
}

/// The whole file. `rMeshes` holds each set's mesh, for its element results.
std::vector<std::int32_t> rstw_file(const RstwModel& rModel, const std::vector<RstwSet>& rSets,
                                    const std::vector<const Mesh*>& rMeshes) {
    RstwWords f;
    const std::int64_t nnod = static_cast<std::int64_t>(rModel.mNnod);
    const std::int64_t nelm = static_cast<std::int64_t>(rModel.mNelm);
    const std::int64_t nsets = static_cast<std::int64_t>(rSets.size());
    const std::int64_t resmax = std::max<std::int64_t>(nsets, 1);
    std::vector<std::int64_t> std_header(100, 0);
    std_header[0] = 12;
    std_header[1] = -1;
    std_header[2] = 120000;
    std_header[3] = 20000101;
    std_header[4] = -1;
    std_header[9] = rstw_text_words("15.0", 1)[0];
    std_header[10] = 20140101;
    auto put = [&](std::size_t At, const std::vector<std::int64_t>& rWords) {
        for (std::size_t k = 0; k < rWords.size(); ++k)
            std_header[At + k] = rWords[k];
    };
    put(11, rstw_text_words("LINUX x64", 3));
    put(14, rstw_text_words("file", 2));
    put(16, rstw_text_words("FULL", 2));
    std_header[22] = 0;
    std_header[25] = 16384;
    put(30, rstw_text_words("file", 8));
    f.Ints(std_header);
    const std::size_t header = f.Ints({12, nnod, nnod, resmax, 0, nelm, nelm, 0, nsets}, 80);
    std::int64_t avail = 0;
    std::size_t numdof_max = 0;
    for (const RstwSet& s : rSets) {
        avail |= s.mMask;
        numdof_max = std::max(numdof_max, s.mDofs.size());
    }
    f.Patch(header, 35, avail);
    f.Patch(header, 39, 1);
    f.Patch(header, 20, rModel.mSectors);
    if (rModel.mSectors > 1) {  // the mesh is the base sector, with no duplicate sector
        f.Patch(header, 18, nelm);
        f.Patch(header, 31, nnod);
    }
    f.Patch(header, 48, nnod);
    std::vector<std::int64_t> numbers(rModel.mNnod);
    for (std::size_t i = 0; i < numbers.size(); ++i)
        numbers[i] = static_cast<std::int64_t>(i + 1);
    f.Patch64(header, 14, 45, static_cast<std::int64_t>(f.Ints(numbers)));
    numbers.resize(rModel.mNelm);
    for (std::size_t i = 0; i < numbers.size(); ++i)
        numbers[i] = static_cast<std::int64_t>(i + 1);
    f.Patch64(header, 13, 44, static_cast<std::int64_t>(f.Ints(numbers)));
    f.Patch(header, 4, static_cast<std::int64_t>(numdof_max));

    const std::int64_t maxety = rModel.mSlots.empty() ? 0 : rModel.mSlots.rbegin()->first;
    const std::size_t geometry = f.Ints({0, maxety, 0, nnod, nelm}, 80);
    f.Patch64(header, 15, 46, static_cast<std::int64_t>(geometry));
    f.Patch(geometry, 42, nnod);
    f.Patch(geometry, 45, nnod);
    const std::size_t ety = f.Ints(std::vector<std::int64_t>(std::max<std::int64_t>(maxety, 1), 0));
    f.Patch64(geometry, 20, 21, static_cast<std::int64_t>(ety));
    for (const auto& [slot, info] : rModel.mSlots) {
        std::vector<std::int64_t> record(200, 0);
        record[0] = slot;
        record[1] = info.mRoutine;
        if (info.mRoutine == 181 || info.mRoutine == 281)
            record[9] = rModel.mLayered ? 0 : 1;
        record[60] = static_cast<std::int64_t>(info.mNodelm);
        record[62] = static_cast<std::int64_t>(info.mNodelm);
        record[93] = static_cast<std::int64_t>(info.mNodstr);
        const std::size_t ptr = f.Ints(record);
        f.Patch(ety, static_cast<std::size_t>(slot - 1), static_cast<std::int64_t>(ptr - ety));
    }
    std::size_t first_node = 0;
    for (std::size_t k = 0; k < rModel.mNnod; ++k) {
        const std::size_t ptr = f.Doubles(
            {static_cast<double>(k + 1), rModel.mPoints[3 * k], rModel.mPoints[3 * k + 1],
             rModel.mPoints[3 * k + 2], rModel.mAngles.empty() ? 0.0 : rModel.mAngles[3 * k],
             rModel.mAngles.empty() ? 0.0 : rModel.mAngles[3 * k + 1],
             rModel.mAngles.empty() ? 0.0 : rModel.mAngles[3 * k + 2]});
        if (k == 0)
            first_node = ptr;
    }
    f.Patch64(geometry, 26, 27, static_cast<std::int64_t>(first_node));
    const std::size_t eid = f.Ints(std::vector<std::int64_t>(2 * rModel.mNelm, 0));
    f.Patch64(geometry, 28, 29, static_cast<std::int64_t>(eid));
    for (std::size_t k = 0; k < rModel.mElements.size(); ++k) {
        const RstwElement& e = rModel.mElements[k];
        std::vector<std::int64_t> record = {rModel.mMat[k],
                                            e.mSlot,
                                            rModel.mReal[k],
                                            rModel.mSecnum[k],
                                            0,
                                            1,
                                            0,
                                            0,
                                            static_cast<std::int64_t>(k + 1),
                                            0};
        record.insert(record.end(), e.mNodes.begin(), e.mNodes.end());
        const std::size_t ptr = f.Ints(record);
        f.Patch(eid, 2 * k, static_cast<std::int64_t>(ptr - eid));
    }
    f.Patch(geometry, 48, static_cast<std::int64_t>(rModel.mComponents.size()));
    if (!rModel.mComponents.empty()) {
        std::size_t first = 0;
        bool have = false;
        for (const RstwComponent& c : rModel.mComponents) {
            std::vector<std::int64_t> packed;
            std::size_t k = 0;
            while (k < c.mIds.size()) {
                std::size_t j = k;
                while (j + 1 < c.mIds.size() && c.mIds[j + 1] == c.mIds[j] + 1)
                    ++j;
                packed.push_back(c.mIds[k]);
                if (j > k)
                    packed.push_back(-c.mIds[j]);
                k = j + 1;
            }
            std::vector<std::int64_t> record = {c.mNodes ? 1 : 2};
            const auto name = rstw_text_words(c.mName, 8);
            record.insert(record.end(), name.begin(), name.end());
            record.insert(record.end(), packed.begin(), packed.end());
            const std::size_t ptr = f.Ints(record);
            if (!have) {
                first = ptr;
                have = true;
            }
        }
        f.Patch64(geometry, 50, 51, static_cast<std::int64_t>(first));
    }

    std::vector<std::int64_t> bases;
    for (std::size_t i = 0; i < rSets.size(); ++i)
        bases.push_back(
            static_cast<std::int64_t>(rstw_set_records(f, *rMeshes[i], rModel, rSets[i])));
    std::vector<std::int64_t> dsi;
    for (const std::int64_t b : bases)
        dsi.push_back(b & 0xFFFFFFFFLL);
    dsi.resize(static_cast<std::size_t>(resmax), 0);
    for (const std::int64_t b : bases)
        dsi.push_back(b >> 32);
    dsi.resize(static_cast<std::size_t>(2 * resmax), 0);
    const std::size_t dsi_ptr = f.Ints(dsi);
    std::vector<double> times;
    for (const RstwSet& s : rSets)
        times.push_back(s.mTime);
    times.resize(static_cast<std::size_t>(resmax), 0.0);
    const std::size_t tim = f.Doubles(times);
    std::vector<std::int64_t> lsp;
    for (const RstwSet& s : rSets)
        lsp.insert(lsp.end(), s.mStep.begin(), s.mStep.end());
    lsp.resize(static_cast<std::size_t>(3 * resmax), 0);
    const std::size_t lsp_ptr = f.Ints(lsp);
    f.Patch64(header, 10, 40, static_cast<std::int64_t>(dsi_ptr));
    f.Patch64(header, 11, 41, static_cast<std::int64_t>(tim));
    f.Patch64(header, 12, 42, static_cast<std::int64_t>(lsp_ptr));
    if (std::any_of(rSets.begin(), rSets.end(), [](const RstwSet& S) { return S.mHarmonic; })) {
        // A modal cyclic-symmetry file: the harmonic index of every set, analysis type 2.
        std::vector<std::int64_t> harmonic;
        for (const RstwSet& s : rSets)
            harmonic.push_back(s.mHarmonic.value_or(0));
        harmonic.resize(static_cast<std::size_t>(resmax), 0);
        f.Patch64(header, 16, 43, static_cast<std::int64_t>(f.Ints(harmonic)));
        f.Patch(header, 7, 2);
    }
    f.Patch(header, 9, static_cast<std::int64_t>(f.Size()));
    f.Patch(header, 22, static_cast<std::int64_t>(f.Size()));
    return f.Words();
}

double rstw_time_of(const Mesh& rMesh) {
    if (!rMesh.HasFieldData(kSequenceTimeKey))
        return 1.0;
    const NDArray& a = rMesh.FieldData(kSequenceTimeKey);
    return a.Size() == 0 ? 1.0 : detail::DoubleView(a).Data()[0];
}

std::array<std::int64_t, 3> rstw_step_of(const Mesh& rMesh, std::size_t Index) {
    auto get = [&](const char* pName, std::int64_t Default) {
        if (!rMesh.HasFieldData(pName))
            return Default;
        const NDArray& a = rMesh.FieldData(pName);
        return a.Size() == 0 ? Default : detail::Int64View(a).Data()[0];
    };
    return {get("ansys:load_step", 1), get("ansys:substep", static_cast<std::int64_t>(Index + 1)),
            get("ansys:cumulative", static_cast<std::int64_t>(Index + 1))};
}

void rstw_save(const std::string& rPath, const std::vector<std::int32_t>& rWords) {
    auto out = detail::make_classic_ofstream(rPath, std::ios::binary);
    if (!out)
        throw WriteError("Could not open file for writing: " + rPath);
    out.write(reinterpret_cast<const char*>(rWords.data()),
              static_cast<std::streamsize>(rWords.size() * sizeof(std::int32_t)));
    out.close();
    if (!out)
        rstw_fail("failed writing " + rPath);
}

}  // namespace

void write_ansys_rst(const std::string& rPath, const Mesh& rMesh) {
    const RstwModel model(rMesh);
    const RstwSet set = rstw_set(rMesh, model, rstw_time_of(rMesh), rstw_step_of(rMesh, 0));
    rstw_save(rPath, rstw_file(model, {set}, {&rMesh}));
}

struct AnsysRstSeriesWriter::Impl {
    std::string mPath;
    std::unique_ptr<RstwModel> mModel;
    std::vector<RstwSet> mSets;
    std::vector<std::unique_ptr<Mesh>> mMeshes;  // each set's element results come from its mesh
    bool mDone = false;
};

AnsysRstSeriesWriter::AnsysRstSeriesWriter(const std::string& rPath)
    : mpImpl(std::make_unique<Impl>()) {
    mpImpl->mPath = rPath;
    auto probe = detail::make_classic_ofstream(rPath, std::ios::binary);
    if (!probe)
        throw WriteError("Could not open file for writing: " + rPath);
}

AnsysRstSeriesWriter::~AnsysRstSeriesWriter() = default;
AnsysRstSeriesWriter::AnsysRstSeriesWriter(AnsysRstSeriesWriter&&) noexcept = default;
AnsysRstSeriesWriter& AnsysRstSeriesWriter::operator=(AnsysRstSeriesWriter&&) noexcept = default;

void AnsysRstSeriesWriter::Write(double Time, const Mesh& rMesh) {
    if (!mpImpl)
        rstw_fail("series: the writer was moved from");
    Impl& s = *mpImpl;
    auto model = std::make_unique<RstwModel>(rMesh);
    if (!s.mModel)
        s.mModel = std::move(model);
    else if (model->mSignature != s.mModel->mSignature)
        rstw_fail("series: step " + std::to_string(s.mSets.size()) +
                  "'s points, cells or components differ from the first step's; a results "
                  "file holds one model -- write one file per step with '{step}'");
    s.mSets.push_back(rstw_set(rMesh, *s.mModel, Time, rstw_step_of(rMesh, s.mSets.size())));
    // The sets' tensors are read when the file is assembled: keep a copy of what they need.
    s.mMeshes.push_back(std::make_unique<Mesh>(detail::clone_mesh(rMesh)));
}

std::size_t AnsysRstSeriesWriter::NumSteps() const noexcept {
    return mpImpl ? mpImpl->mSets.size() : 0;
}

void AnsysRstSeriesWriter::Finalize() {
    if (!mpImpl || mpImpl->mDone)
        return;
    Impl& s = *mpImpl;
    if (s.mSets.empty())
        rstw_fail("series: no step was written");
    s.mDone = true;
    std::vector<const Mesh*> meshes;
    for (const auto& m : s.mMeshes)
        meshes.push_back(m.get());
    rstw_save(s.mPath, rstw_file(*s.mModel, s.mSets, meshes));
}

}  // namespace meshioplusplus
