#include <unordered_map>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

namespace fs = std::filesystem;

constexpr int kRadMaxIncludeDepth = 8;

struct RadLine {
    std::string mText;
    std::string mWhere;  // "file:line"
};

std::string_view rad_trim_view(std::string_view s) {
    const std::size_t b = s.find_first_not_of(" \t\r");
    if (b == std::string_view::npos)
        return {};
    const std::size_t e = s.find_last_not_of(" \t\r");
    return s.substr(b, e - b + 1);
}

std::string rad_trim(std::string_view s) {
    return std::string(rad_trim_view(s));
}

std::string rad_upper(std::string s) {
    for (char& c : s)
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    return s;
}

// The deck's lines with `#include` files inlined and comments dropped, up to
// `/END` (or `#enddata` in an include).
void rad_collect(const fs::path& rPath, int Depth, std::vector<RadLine>& rOut, bool& rEnded) {
    if (Depth > kRadMaxIncludeDepth)
        throw ReadError("Radioss: #include nested deeper than " +
                        std::to_string(kRadMaxIncludeDepth));
    const detail::FileSource text_source =
        detail::open_source(rPath.string(), "Radioss: cannot open " + rPath.string());
    const std::string_view text = text_source.View();
    const std::string label = rPath.filename().string();
    std::size_t pos = 0, number = 0;
    while (pos < text.size() && !rEnded) {
        std::size_t eol = text.find('\n', pos);
        if (eol == std::string::npos)
            eol = text.size();
        std::string line(text.substr(pos, eol - pos));
        pos = eol + 1;
        ++number;
        if (!line.empty() && line.back() == '\r')
            line.pop_back();
        const std::string lower = rad_upper(line.substr(0, 9));
        if (lower.rfind("#INCLUDE", 0) == 0) {
            std::string name = rad_trim(std::string_view(line).substr(8));
            if (name.size() >= 2 && (name.front() == '"' || name.front() == '\'') &&
                name.back() == name.front())
                name = name.substr(1, name.size() - 2);
            std::replace(name.begin(), name.end(), '\\', '/');
            const fs::path inc =
                fs::path(name).is_absolute() ? fs::path(name) : rPath.parent_path() / name;
            std::error_code ec;
            if (!fs::is_regular_file(inc, ec)) {
                log::warn("Radioss: include file '{}' not found; skipped", name);
                continue;
            }
            bool sub_ended = false;
            rad_collect(inc, Depth + 1, rOut, sub_ended);
            continue;
        }
        if (Depth > 0 && rad_upper(rad_trim(line)).rfind("#ENDDATA", 0) == 0)
            return;
        // Blank lines stay: a blank /PART or group title is still its title line.
        if (!line.empty() && (line[0] == '#' || line[0] == '$'))
            continue;
        if (rad_upper(rad_trim(line)) == "/END") {
            if (Depth == 0)
                rEnded = true;
            if (Depth == 0)
                return;
            continue;
        }
        rOut.push_back({std::move(line), label + ":" + std::to_string(number)});
    }
}

// Fixed fields of `Width` columns, or comma-separated values.
std::vector<std::string_view> rad_fields(std::string_view rLine, int Width, std::size_t Count) {
    std::vector<std::string_view> out;
    if (rLine.find(',') != std::string::npos) {
        std::size_t start = 0;
        while (true) {
            const std::size_t k = rLine.find(',', start);
            out.push_back(rad_trim_view(
                rLine.substr(start, k == std::string::npos ? std::string::npos : k - start)));
            if (k == std::string::npos)
                break;
            start = k + 1;
        }
        return out;
    }
    const std::size_t w = static_cast<std::size_t>(Width);
    for (std::size_t f = 0; f < Count; ++f) {
        const std::size_t at = f * w;
        out.push_back(at < rLine.size() ? rad_trim_view(rLine.substr(at, w)) : std::string_view());
    }
    return out;
}

std::int64_t rad_int(std::string_view rText, const RadLine& rLine) {
    return detail::card_to_int_view(rText, " (" + rLine.mWhere + ")", "Radioss");
}

double rad_real(std::string_view rText, const RadLine& rLine) {
    return detail::card_to_real_view(rText, " (" + rLine.mWhere + ")", "Radioss");
}

// Element keywords: their group family, node count, lines per element and the
// meshio++ type they read as (before degenerate-brick and triangle checks).
struct RadElementKind {
    const char* mKeyword;
    const char* mFamily;  // the /GR<family> keyword and /GRxxx/<subtype> that list them
    std::size_t mNodes;
    const char* mType;
};

const RadElementKind* rad_element_kind(const std::string& rKeyword) {
    static const RadElementKind kinds[] = {
        {"BRICK", "BRIC", 8, "hexahedron"},     {"PENTA6", "BRIC", 6, "wedge"},
        {"TETRA4", "BRIC", 4, "tetra"},         {"TETRA10", "BRIC", 10, "tetra10"},
        {"BRIC20", "BRIC", 20, "hexahedron20"}, {"SHELL", "SHEL", 4, "quad"},
        {"SH3N", "SH3N", 3, "triangle"},        {"QUAD", "QUAD", 4, "quad"},
        {"TRIA", "TRIA", 3, "triangle"},        {"BEAM", "BEAM", 2, "line"},
        {"TRUSS", "TRUS", 2, "line"},           {"SPRING", "SPRI", 2, "line"},
    };
    for (const RadElementKind& k : kinds)
        if (rKeyword == k.mKeyword)
            return &k;
    return nullptr;
}

// The /GRxxx keyword -> its element family (GRNOD -> "NODE").
const char* rad_group_family(const std::string& rKeyword) {
    static const std::pair<const char*, const char*> groups[] = {
        {"GRNOD", "NODE"},  {"GRBRIC", "BRIC"}, {"GRSHEL", "SHEL"},
        {"GRSH3N", "SH3N"}, {"GRQUAD", "QUAD"}, {"GRTRIA", "TRIA"},
        {"GRBEAM", "BEAM"}, {"GRTRUS", "TRUS"}, {"GRSPRI", "SPRI"},
    };
    for (const auto& [k, f] : groups)
        if (rKeyword == k)
            return f;
    return nullptr;
}

struct RadElement {
    std::string mFamily;
    std::int64_t mId, mPart;
    std::string mType;
    std::vector<std::int64_t> mNodes;  // node ids, meshio++ order
    std::string mWhere;
    bool mTetra = false;  // a /TETRA4 or /TETRA10, reoriented when inverted
};

struct RadPart {
    std::string mTitle;
    std::int64_t mProperty = 0, mMaterial = 0, mSubset = 0;
};

struct RadGroup {
    std::string mKeyword, mSubtype, mTitle;
    std::int64_t mId;
    std::vector<std::int64_t> mIds;
};

struct RadSurface {
    std::int64_t mId = 0;
    std::string mTitle;
    std::vector<std::array<std::int64_t, 4>> mSegments;
    // `/SURF/<mKind>[/<mMode>]/id`: SEG (the segments above), PART, SUBSET, MAT,
    // PROP, GRBRIC, GRSHEL, GRSH3N, GRTRIA or SURF, with EXT, ALL or FREE.
    std::string mKind = "SEG", mMode;
    std::vector<std::int64_t> mIds;
};

// `/BOX/RECTA`, `/CYLIN`, `/SPHER` (corners, axis ends or centre, from nodes or
// coordinates) and `/BOX/BOX` (other boxes, a negative id subtracted).
struct RadBox {
    std::string mKind;
    std::int64_t mSkew = 0;
    std::int64_t mNode1 = 0, mNode2 = 0;
    std::array<double, 3> mP1{}, mP2{};
    double mDiameter = 0.0;
    std::vector<std::int64_t> mChildren;
};

// `/SKEW/FIX`: a fixed frame, its origin and the X and Y axes as given.
struct RadSkew {
    std::array<double, 3> mOrigin{}, mX{}, mY{};
};

// The unit axes of a fixed skew (X, Z = X x Y, Y = Z x X), as the rows of a
// rotation into the skew frame; false when X and Y are parallel or zero.
bool rad_skew_axes(const RadSkew& rSkew, std::array<std::array<double, 3>, 3>& rAxes) {
    const auto cross = [](const std::array<double, 3>& a, const std::array<double, 3>& b) {
        return std::array<double, 3>{a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2],
                                     a[0] * b[1] - a[1] * b[0]};
    };
    const auto unit = [](std::array<double, 3> a) {
        const double n = std::sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]);
        if (n > 0.0)
            for (double& x : a)
                x /= n;
        return std::make_pair(a, n > 0.0);
    };
    const auto [x, okx] = unit(rSkew.mX);
    const auto [z, okz] = unit(cross(x, rSkew.mY));
    if (!okx || !okz)
        return false;
    rAxes = {x, cross(z, x), z};
    return true;
}

struct RadSubset {
    std::string mTitle;
    std::vector<std::int64_t> mChildren;
};

// A /BEGIN length unit in metres: an SI prefix and "m" ("mm", "mum", "km"), a
// few imperial names, or a number; 0 when unknown.
double rad_length_unit(const std::string& rUnit) {
    if (rUnit.empty())
        return 0.0;
    static const std::pair<const char*, double> named[] = {
        {"in", 0.0254}, {"ft", 0.3048}, {"yd", 0.9144}, {"mi", 1609.344}};
    for (const auto& [name, metres] : named)
        if (rUnit == name)
            return metres;
    if (rUnit.back() == 'm') {
        static const std::pair<const char*, double> prefixes[] = {
            {"", 1.0},   {"y", 1e-24}, {"z", 1e-21}, {"a", 1e-18}, {"f", 1e-15}, {"p", 1e-12},
            {"n", 1e-9}, {"mu", 1e-6}, {"m", 1e-3},  {"c", 1e-2},  {"d", 1e-1},  {"da", 1e1},
            {"h", 1e2},  {"k", 1e3},   {"M", 1e6},   {"G", 1e9},   {"T", 1e12},  {"P", 1e15},
            {"E", 1e18}, {"Z", 1e21},  {"Y", 1e24}};
        const std::string prefix = rUnit.substr(0, rUnit.size() - 1);
        for (const auto& [name, factor] : prefixes)
            if (prefix == name)
                return factor;
    }
    try {
        return detail::card_to_real(rUnit, "", "Radioss");
    } catch (const ReadError&) {
        return 0.0;
    }
}

// A fixed-width slice of a line (the whole comma field when the line has commas).
std::string rad_slice(const std::string& rLine, std::size_t At, std::size_t Width,
                      std::size_t CommaField) {
    if (rLine.find(',') != std::string::npos) {
        const auto f = rad_fields(rLine, 1, 0);
        return CommaField < f.size() ? std::string(f[CommaField]) : std::string();
    }
    return At < rLine.size() ? rad_trim(std::string_view(rLine).substr(At, Width)) : std::string();
}

NDArray rad_ids(const std::vector<std::int64_t>& rIds, std::size_t Stride = 1) {
    NDArray a(DType::Int64, Stride == 1 ? std::vector<std::size_t>{rIds.size()}
                                        : std::vector<std::size_t>{rIds.size() / Stride, Stride});
    std::copy(rIds.begin(), rIds.end(), a.As<std::int64_t>());
    return a;
}

// The input version on a `#RADIOSS STARTER` line (`41` in
// `#RADIOSS STARTER      41BAR2V41B`), 0 if none.
int rad_header_version(const std::string& rHead) {
    const std::string up = rad_upper(rHead);
    const std::size_t at = up.find("#RADIOSS STARTER");
    if (at == std::string::npos)
        return 0;
    std::size_t k = at + 16;
    const std::size_t eol = up.find('\n', k);
    while (k < up.size() && k < eol && (up[k] == ' ' || up[k] == '\t'))
        ++k;
    int v = 0;
    std::size_t digits = 0;
    for (; k < up.size() && k < eol && up[k] >= '0' && up[k] <= '9' && digits < 4; ++k, ++digits)
        v = v * 10 + (up[k] - '0');
    return v;
}

// An engine deck (`<run>_0001.rad`): every keyword and the numbers of its
// lines, as `radioss:engine:<keyword>` field data (`/RUN/<name>/1` holds the
// end time, `/ANIM/DT` start and interval, `/TFILE` the history interval; an
// output request such as `/ANIM/ELEM/SIGX` is an empty array).
std::vector<std::pair<std::string, std::vector<double>>> rad_engine_fields(
    const std::string& rPath) {
    std::vector<RadLine> lines;
    bool ended = false;
    rad_collect(fs::path(rPath), 0, lines, ended);
    std::vector<std::pair<std::string, std::vector<double>>> out;
    for (const RadLine& ln : lines) {
        const std::string t = rad_trim(ln.mText);
        if (t.empty())
            continue;
        if (t[0] == '/') {
            out.emplace_back("radioss:engine:" + t.substr(1), std::vector<double>{});
            continue;
        }
        if (out.empty())
            continue;
        for (const std::string_view tok : detail::split_blanks(t)) {
            double v = 0.0;
            if (detail::parse_double_token(tok, v))
                out.back().second.push_back(v);
        }
    }
    return out;
}

void rad_add_engine_fields(Mesh& rMesh, const std::string& rPath) {
    for (const auto& [name, values] : rad_engine_fields(rPath)) {
        std::vector<double> all = values;
        if (rMesh.HasFieldData(name)) {  // a repeated keyword: its numbers appended
            const NDArray& prev = rMesh.FieldData(name);
            std::vector<double> joined(prev.Size());
            for (std::size_t k = 0; k < joined.size(); ++k)
                joined[k] = detail::read_double(prev, k);
            joined.insert(joined.end(), all.begin(), all.end());
            all = std::move(joined);
        }
        NDArray a(DType::Float64, {all.size()});
        std::copy(all.begin(), all.end(), a.As<double>());
        rMesh.AddFieldData(name, std::move(a));
    }
}

// An engine deck read on its own: no mesh, its run controls.
Mesh rad_engine_mesh(const std::string& rPath) {
    Mesh mesh;
    mesh.AssignPoints(NDArray(DType::Float64, {0, 3}));
    rad_add_engine_fields(mesh, rPath);
    return mesh;
}

}  // namespace

Mesh read_radioss(const std::string& rPath) {
    std::vector<RadLine> lines;
    bool ended = false;
    int header_version = 0;
    {
        auto in = detail::make_classic_ifstream(rPath, std::ios::binary);
        if (!in)
            throw ReadError("Radioss: cannot open " + rPath);
        std::string head(512, '\0');
        in.read(head.data(), static_cast<std::streamsize>(head.size()));
        head.resize(static_cast<std::size_t>(in.gcount()));
        if (rad_upper(head).find("#RADIOSS ENGINE") != std::string::npos)
            return rad_engine_mesh(rPath);
        header_version = rad_header_version(head);
    }
    rad_collect(fs::path(rPath), 0, lines, ended);

    int version = 2019;
    int iw = 10, rw = 20;
    // Before input version 5.1 (4.1, 4.4) there is no /BEGIN: the version is
    // on the #RADIOSS STARTER line, fields are 8 and 16 columns wide, and a
    // title is the keyword's last part rather than a line of its own.
    bool titles_in_path = header_version > 0 && header_version < 51;
    if (titles_in_path) {
        version = header_version;
        iw = 8;
        rw = 16;
    }
    std::vector<std::int64_t> node_ids;
    std::vector<double> coords;
    std::vector<RadElement> elements;
    std::map<std::int64_t, RadPart> parts;
    std::vector<std::int64_t> part_order;
    std::vector<RadGroup> groups;
    std::vector<RadSurface> surfaces;
    std::map<std::int64_t, RadSubset> subsets;
    std::map<std::int64_t, RadBox> boxes;
    std::map<std::int64_t, RadSkew> skews;
    std::vector<std::pair<std::string, std::vector<double>>> analytic;  // /SURF/PLANE, /ELLIPS
    std::map<std::int64_t, std::array<double, 3>> ellipsoid_skew;       // surf -> skew, n, -
    double length_scale = 1.0;
    double work_length = 0.0;  // the work length unit in metres, 0 if /BEGIN names none
    // /UNIT/<id>: the local length units in metres, read first (a keyword can
    // name a unit defined further down).
    std::map<std::int64_t, double> unit_length;
    for (std::size_t k = 0; k + 2 < lines.size(); ++k) {
        const std::string t = rad_upper(rad_trim(lines[k].mText));
        if (t.rfind("/UNIT/", 0) != 0)
            continue;
        const std::string id = rad_trim(std::string_view(t).substr(6));
        if (id.empty() || id.find_first_not_of("0123456789") != std::string::npos)
            continue;
        const auto f = rad_fields(lines[k + 2].mText, 20, 3);
        const double len = f.size() > 1 ? rad_length_unit(std::string(f[1])) : 0.0;
        if (len > 0.0)
            unit_length[std::stoll(id)] = len;
        else
            log::warn("Radioss: /UNIT/{} has no length unit meshio++ knows; ignored", id);
    }
    std::set<std::int64_t> warned_units;
    std::set<std::string> skipped_keywords;
    std::size_t zero_springs = 0, linear_bric20 = 0;

    std::size_t i = 0;
    const std::size_t n = lines.size();
    auto block_end = [&](std::size_t From) {
        std::size_t k = From;
        while (k < n && (lines[k].mText.empty() || lines[k].mText[0] != '/'))
            ++k;
        return k;
    };
    while (i < n) {
        const RadLine& head = lines[i];
        if (head.mText.empty() || head.mText[0] != '/') {
            ++i;
            continue;
        }
        std::vector<std::string> path, raw_path;
        {
            std::string kw = rad_trim(head.mText);
            std::size_t start = 1;
            while (start <= kw.size()) {
                const std::size_t k = kw.find('/', start);
                raw_path.push_back(rad_trim(std::string_view(kw).substr(
                    start, k == std::string::npos ? std::string::npos : k - start)));
                path.push_back(rad_upper(raw_path.back()));
                if (k == std::string::npos)
                    break;
                start = k + 1;
            }
        }
        const std::string& key = path.empty() ? std::string() : path[0];
        const std::size_t body = i + 1;
        const std::size_t end = block_end(body);
        // The keyword's id: its first integer field (`/BOX/RECTA/3/1` is box 3 in
        // unit system 1; `/SURF/PART/EXT/12` is surface 12).
        auto last_id = [&](const RadLine& rLine) -> std::int64_t {
            for (std::size_t k = 1; k < path.size(); ++k)
                if (!path[k].empty() &&
                    path[k].find_first_not_of("+-0123456789") == std::string::npos)
                    return rad_int(path[k], rLine);
            return path.size() >= 2 ? rad_int(path.back(), rLine) : 0;
        };
        // The unit system a keyword names: the integer after its option id
        // (`/BOX/RECTA/3/1`), or its only integer when it has none (`/NODE/1`).
        auto unit_of = [&](bool OptionId) -> std::int64_t {
            std::vector<std::int64_t> ints;
            for (std::size_t k = 1; k < path.size(); ++k)
                if (!path[k].empty() &&
                    path[k].find_first_not_of("+-0123456789") == std::string::npos)
                    ints.push_back(rad_int(path[k], head));
            const std::size_t at = OptionId ? 1 : 0;
            return ints.size() > at ? ints[at] : 0;
        };
        // Lengths of this keyword into the work units: its /UNIT's, else /BEGIN's.
        auto scale_of = [&](std::int64_t Unit) {
            if (Unit == 0)
                return length_scale;
            const auto it = unit_length.find(Unit);
            if (it == unit_length.end() || work_length <= 0.0) {
                if (warned_units.insert(Unit).second)
                    log::warn(
                        "Radioss: unit system {} is {}; its lengths are read in the input "
                        "units",
                        Unit,
                        it == unit_length.end() ? "not defined" : "used without /BEGIN units");
                return length_scale;
            }
            return it->second / work_length;
        };
        // A keyword's title: its own line from input version 5.1 on; before,
        // the keyword's last part (`/PART/1/CUIVRE`), the data then starting on
        // the next line.
        auto title_of = [&](std::size_t& rK) -> std::string {
            if (titles_in_path) {
                const std::string& last = raw_path.back();
                return raw_path.size() >= 3 &&
                               last.find_first_not_of("+-0123456789") != std::string::npos
                           ? last
                           : std::string();
            }
            return rK < end ? rad_trim(lines[rK++].mText) : std::string();
        };

        if (key == "BEGIN") {
            // run name; Invers Irun; two unit lines. A deck with /BEGIN has its
            // titles on lines of their own, whatever its input version.
            titles_in_path = false;
            if (body + 1 < end) {
                const auto f = rad_fields(lines[body + 1].mText, 10, 2);
                if (!f.empty() && !f[0].empty())
                    version = static_cast<int>(rad_int(f[0], lines[body + 1]));
            }
            iw = version >= 51 ? 10 : 8;
            rw = version >= 51 ? 20 : 16;
            // Input and work units (mass, length, time; 20 columns each): the
            // solver works in the work units, so lengths are converted.
            if (body + 2 < end) {
                const auto in = rad_fields(lines[body + 2].mText, 20, 3);
                const auto work = body + 3 < end ? rad_fields(lines[body + 3].mText, 20, 3)
                                                 : std::vector<std::string_view>{};
                const std::string li(in.size() > 1 ? in[1] : std::string_view());
                const std::string lw(work.size() > 1 && !work[1].empty() ? work[1]
                                                                         : std::string_view(li));
                const double fi = rad_length_unit(li), fw = rad_length_unit(lw);
                work_length = fw;
                if (!li.empty() && (fi <= 0.0 || fw <= 0.0))
                    log::warn(
                        "Radioss: unknown length unit '{}' in /BEGIN; lengths are read "
                        "as written",
                        fi <= 0.0 ? li : lw);
                else if (!li.empty())
                    length_scale = fi / fw;
            }
        } else if (key == "BOX" && path.size() >= 3) {
            RadBox b;
            b.mKind = path[1];
            std::size_t k = body;
            title_of(k);
            const double box_scale = scale_of(unit_of(true));
            auto real3 = [&](std::size_t Line) {
                std::array<double, 3> p{};
                if (Line >= end)
                    return p;
                const auto f = rad_fields(lines[Line].mText, rw, 3);
                for (std::size_t d = 0; d < 3; ++d)
                    p[d] = d < f.size() && !f[d].empty() ? rad_real(f[d], lines[Line]) * box_scale
                                                         : 0.0;
                return p;
            };
            auto int_at = [&](std::size_t Line, std::size_t Field) -> std::int64_t {
                if (Line >= end)
                    return 0;
                const std::string t =
                    rad_slice(lines[Line].mText, Field * static_cast<std::size_t>(iw),
                              static_cast<std::size_t>(iw), Field);
                return t.empty() ? 0 : rad_int(t, lines[Line]);
            };
            auto diameter = [&](std::size_t Line) {
                if (Line >= end)
                    return 0.0;
                const std::string t =
                    rad_slice(lines[Line].mText, 3 * static_cast<std::size_t>(iw),
                              static_cast<std::size_t>(rw), b.mKind == "SPHER" ? 2 : 3);
                return t.empty() ? 0.0 : rad_real(t, lines[Line]) * box_scale;
            };
            if (b.mKind == "RECTA") {
                b.mNode1 = int_at(k, 0);
                b.mNode2 = int_at(k, 1);
                b.mSkew = int_at(k, 2);
                b.mP1 = real3(k + 1);
                b.mP2 = real3(k + 2);
            } else if (b.mKind == "CYLIN") {
                b.mNode1 = int_at(k, 0);
                b.mNode2 = int_at(k, 1);
                b.mDiameter = diameter(k);
                b.mP1 = real3(k + 1);
                b.mP2 = real3(k + 2);
            } else if (b.mKind == "SPHER") {
                b.mNode1 = int_at(k, 0);
                b.mDiameter = diameter(k);
                b.mP1 = real3(k + 1);
            } else if (b.mKind == "BOX") {
                for (; k < end; ++k)
                    for (const auto f : rad_fields(lines[k].mText, iw, 10))
                        if (!f.empty())
                            b.mChildren.push_back(rad_int(f, lines[k]));
            } else {
                skipped_keywords.insert("/BOX/" + b.mKind);
            }
            boxes[last_id(head)] = std::move(b);
        } else if (key == "SKEW" && path.size() >= 3 && path[1] == "FIX") {
            // origin (from 5.1), X axis, Y axis
            RadSkew sk;
            std::size_t k = body;
            title_of(k);
            const double sk_scale = scale_of(unit_of(true));
            auto vec = [&](std::size_t Line, double Scale) {
                std::array<double, 3> v{};
                if (Line >= end)
                    return v;
                const auto f = rad_fields(lines[Line].mText, rw, 3);
                for (std::size_t d = 0; d < 3; ++d)
                    v[d] =
                        d < f.size() && !f[d].empty() ? rad_real(f[d], lines[Line]) * Scale : 0.0;
                return v;
            };
            if (!titles_in_path)  // 4.x skews have no origin line
                sk.mOrigin = vec(k++, sk_scale);
            sk.mX = vec(k, 1.0);
            sk.mY = vec(k + 1, 1.0);
            skews[last_id(head)] = sk;
        } else if (key == "SURF" && path.size() >= 3 &&
                   (path[1] == "PLANE" || path[1] == "ELLIPS")) {
            // Analytical surfaces: no segments, their definition as field data.
            const std::int64_t id = last_id(head);
            std::size_t k = body;
            title_of(k);
            const double sc = scale_of(unit_of(true));
            auto reals = [&](std::size_t Line, std::size_t Count) {
                std::vector<double> v(Count, 0.0);
                if (Line >= end)
                    return v;
                const auto f = rad_fields(lines[Line].mText, rw, Count);
                for (std::size_t d = 0; d < Count; ++d)
                    v[d] = d < f.size() && !f[d].empty() ? rad_real(f[d], lines[Line]) * sc : 0.0;
                return v;
            };
            if (path[1] == "PLANE") {
                std::vector<double> v = reals(k, 3);
                const std::vector<double> m1 = reals(k + 1, 3);
                v.insert(v.end(), m1.begin(), m1.end());
                analytic.emplace_back("radioss:surf_plane:" + std::to_string(id), std::move(v));
            } else {
                const auto f =
                    k < end ? rad_fields(lines[k].mText, iw, 2) : std::vector<std::string_view>{};
                const std::int64_t skew = !f.empty() && !f[0].empty() ? rad_int(f[0], lines[k]) : 0;
                const std::int64_t degree =
                    f.size() > 1 && !f[1].empty() ? rad_int(f[1], lines[k]) : 2;
                std::vector<double> v = {static_cast<double>(degree < 2 ? 2 : degree)};
                const std::vector<double> centre = reals(k + 1, 3), axes = reals(k + 2, 3);
                v.insert(v.end(), centre.begin(), centre.end());
                v.insert(v.end(), axes.begin(), axes.end());
                ellipsoid_skew[id] = {static_cast<double>(skew), 0.0, 0.0};
                analytic.emplace_back("radioss:surf_ellips:" + std::to_string(id), std::move(v));
            }
        } else if (key == "NODE") {
            const double node_scale = scale_of(unit_of(false));
            for (std::size_t k = body; k < end; ++k) {
                const RadLine& ln = lines[k];
                std::vector<std::string_view> f;
                if (ln.mText.find(',') != std::string::npos) {
                    f = rad_fields(ln.mText, iw, 4);
                } else {
                    f.push_back(rad_trim_view(std::string_view(ln.mText).substr(
                        0, std::min<std::size_t>(ln.mText.size(), static_cast<std::size_t>(iw)))));
                    for (std::size_t d = 0; d < 3; ++d) {
                        const std::size_t at =
                            static_cast<std::size_t>(iw + rw * static_cast<int>(d));
                        f.push_back(at < ln.mText.size()
                                        ? rad_trim_view(std::string_view(ln.mText).substr(
                                              at, static_cast<std::size_t>(rw)))
                                        : std::string_view());
                    }
                }
                if (f.empty() || f[0].empty())
                    continue;
                node_ids.push_back(rad_int(f[0], ln));
                for (std::size_t d = 1; d <= 3; ++d)
                    coords.push_back(d < f.size() && !f[d].empty() ? rad_real(f[d], ln) * node_scale
                                                                   : 0.0);
            }
        } else if (const RadElementKind* kind = rad_element_kind(key)) {
            const std::int64_t part = last_id(head);
            // Every element's integers, gathered from its line(s).
            const std::size_t per_record = key == "TETRA10" ? 11 : kind->mNodes + 1;
            std::vector<std::int64_t> values;
            std::string where;
            auto flush = [&]() {
                RadElement el{kind->mFamily, values[0], part, kind->mType, {}, where};
                std::vector<std::int64_t> nodes(
                    values.begin() + 1,
                    values.begin() + 1 + static_cast<std::ptrdiff_t>(kind->mNodes));
                if (key == "BRICK") {
                    std::array<std::int64_t, 8> a;
                    std::copy(nodes.begin(), nodes.end(), a.begin());
                    detail::CollapsedBrick c = detail::collapse_brick(a);
                    el.mType = c.mType;
                    nodes = std::move(c.mNodes);
                } else if (key == "SHELL" && (nodes[3] == nodes[2] || nodes[3] == 0)) {
                    el.mType = "triangle";
                    nodes.resize(3);
                } else if (key == "BRIC20") {
                    if (std::find(nodes.begin() + 8, nodes.end(), 0) != nodes.end()) {
                        ++linear_bric20;
                        el.mType = "hexahedron";
                        nodes.resize(8);
                    } else {
                        const detail::NodeOrder* order =
                            detail::node_order("radioss", "hexahedron20");
                        std::vector<std::int64_t> ordered(20);
                        for (std::size_t j = 0; j < 20; ++j)
                            ordered[j] =
                                nodes[order ? static_cast<std::size_t>(order->mToMeshio[j]) : j];
                        nodes = std::move(ordered);
                    }
                } else if (key == "SPRING" && nodes[1] == 0) {
                    ++zero_springs;
                    values.clear();
                    return;
                }
                el.mNodes = std::move(nodes);
                el.mTetra = key == "TETRA4" || key == "TETRA10";
                elements.push_back(std::move(el));
                values.clear();
            };
            for (std::size_t k = body; k < end; ++k) {
                const RadLine& ln = lines[k];
                if (rad_trim(ln.mText).empty())
                    continue;
                // Integer fields of the line: BRIC20 and TETRA10 records span
                // several lines; the others are one line each.
                std::size_t take = 10;
                if (key == "TETRA10")
                    take = values.empty() ? 1 : 10;
                else if (key == "BRIC20")
                    take = values.empty() ? 9 : (values.size() == 9 ? 8 : 4);
                else
                    take = per_record;
                const auto f = rad_fields(ln.mText, iw, take);
                if (values.empty())
                    where = ln.mWhere;
                for (std::size_t j = 0; j < take && values.size() < per_record; ++j)
                    values.push_back(j < f.size() && !f[j].empty() ? rad_int(f[j], ln) : 0);
                if (values.size() >= per_record || (key != "TETRA10" && key != "BRIC20"))
                    flush();
            }
            if (!values.empty())
                throw ReadError("Radioss: /" + key + " element " + std::to_string(values[0]) +
                                " is cut short (" + where + ")");
        } else if (key == "PART") {
            const std::int64_t id = last_id(head);
            RadPart part;
            std::size_t k = body;
            part.mTitle = title_of(k);
            if (k < end) {
                const auto f = rad_fields(lines[k].mText, iw, 3);
                part.mProperty = !f.empty() && !f[0].empty() ? rad_int(f[0], lines[k]) : 0;
                part.mMaterial = f.size() > 1 && !f[1].empty() ? rad_int(f[1], lines[k]) : 0;
                part.mSubset = f.size() > 2 && !f[2].empty() ? rad_int(f[2], lines[k]) : 0;
            }
            if (parts.emplace(id, part).second)
                part_order.push_back(id);
        } else if (rad_group_family(key) && path.size() >= 3) {
            RadGroup g{key, path[1], {}, last_id(head), {}};
            std::size_t k = body;
            g.mTitle = title_of(k);
            for (; k < end; ++k)
                for (const auto f : rad_fields(lines[k].mText, iw, 10))
                    if (!f.empty())
                        g.mIds.push_back(rad_int(f, lines[k]));
            groups.push_back(std::move(g));
        } else if (key == "SURF" && path.size() >= 3 && path[1] == "SEG") {
            RadSurface s;
            s.mId = last_id(head);
            std::size_t k = body;
            s.mTitle = title_of(k);
            for (; k < end; ++k) {
                const auto f = rad_fields(lines[k].mText, iw, 5);
                std::array<std::int64_t, 4> seg{0, 0, 0, 0};
                for (std::size_t j = 0; j < 4; ++j)
                    seg[j] =
                        j + 1 < f.size() && !f[j + 1].empty() ? rad_int(f[j + 1], lines[k]) : 0;
                if (seg[0] || seg[1] || seg[2])
                    s.mSegments.push_back(seg);
            }
            surfaces.push_back(std::move(s));
        } else if (key == "SURF" && path.size() >= 3 &&
                   (path[1] == "PART" || path[1] == "SUBSET" || path[1] == "MAT" ||
                    path[1] == "PROP" || path[1] == "GRBRIC" || path[1] == "GRSHEL" ||
                    path[1] == "GRSH3N" || path[1] == "GRTRIA" || path[1] == "SURF" ||
                    path[1] == "BOX" || path[1] == "BOX2")) {
            RadSurface s;
            s.mId = last_id(head);
            s.mKind = path[1];
            if (path.size() >= 4 && (path[2] == "EXT" || path[2] == "ALL" || path[2] == "FREE"))
                s.mMode = path[2];
            std::size_t k = body;
            s.mTitle = title_of(k);
            for (; k < end; ++k)
                for (const auto f : rad_fields(lines[k].mText, iw, 10))
                    if (!f.empty())
                        s.mIds.push_back(rad_int(f, lines[k]));
            surfaces.push_back(std::move(s));
        } else if (key == "SURF") {
            skipped_keywords.insert("/SURF/" + (path.size() > 1 ? path[1] : std::string()));
        } else if (key == "SUBSET") {
            RadSubset s;
            std::size_t k = body;
            s.mTitle = title_of(k);
            for (; k < end; ++k)
                for (const auto f : rad_fields(lines[k].mText, iw, 10))
                    if (!f.empty())
                        s.mChildren.push_back(rad_int(f, lines[k]));
            subsets[last_id(head)] = std::move(s);
        } else if (key.rfind("GR", 0) == 0 || key == "TSHELL" || key == "TSH3N" ||
                   key == "SHEL16" || key == "SPHCEL" || key == "RIVET" || key == "XELEM") {
            skipped_keywords.insert("/" + key);
        }
        i = end;
    }
    if (!skipped_keywords.empty()) {
        std::string list;
        for (const std::string& k : skipped_keywords)
            list += (list.empty() ? "" : ", ") + k;
        log::warn("Radioss: mesh keywords not read: {}", list);
    }
    if (zero_springs)
        log::warn("Radioss: {} /SPRING element(s) with a single node skipped", zero_springs);
    if (linear_bric20)
        log::warn(
            "Radioss: {} /BRIC20 element(s) with missing mid-edge nodes read as "
            "hexahedra",
            linear_bric20);

    // --- points -------------------------------------------------------------------
    Mesh mesh;
    std::unordered_map<std::int64_t, std::int64_t> node_index;
    node_index.reserve(node_ids.size());
    for (std::size_t p = 0; p < node_ids.size(); ++p)
        if (!node_index.emplace(node_ids[p], static_cast<std::int64_t>(p)).second)
            throw ReadError("Radioss: node " + std::to_string(node_ids[p]) + " is defined twice");
    NDArray points(DType::Float64, {node_ids.size(), 3});
    std::copy(coords.begin(), coords.end(), points.As<double>());
    mesh.AssignPoints(std::move(points));
    mesh.AddFieldData("radioss:version", [&] {
        NDArray a(DType::Int64, {});
        a.As<std::int64_t>()[0] = version;
        return a;
    }());
    if (length_scale != 1.0)
        mesh.AddFieldData("radioss:length_scale", [&] {
            NDArray a(DType::Float64, {});
            a.As<double>()[0] = length_scale;
            return a;
        }());

    // --- cells: one block per type, in order of first appearance --------------------
    std::vector<std::string> block_types;
    std::map<std::string, std::vector<std::size_t>> by_type;
    for (std::size_t e = 0; e < elements.size(); ++e) {
        auto [it, fresh] = by_type.emplace(elements[e].mType, std::vector<std::size_t>{});
        if (fresh)
            block_types.push_back(elements[e].mType);
        it->second.push_back(e);
    }
    std::map<std::string, std::unordered_map<std::int64_t, std::int64_t>>
        owner;  // family -> id -> cell
    std::map<std::int64_t, std::vector<std::int64_t>> part_cells;
    std::vector<std::int64_t> cell_part;
    std::vector<int> cell_dim;
    std::vector<NDArray> part_blocks, prop_blocks, mat_blocks;
    // Tetrahedra come in either winding (every /TETRA4 of OpenRadioss's INT_25 QA
    // deck is inverted, gmsh writes them positive): an inverted one is mirrored.
    std::size_t reoriented = 0;
    for (RadElement& el : elements) {
        if (!el.mTetra)
            continue;
        std::array<std::array<double, 3>, 4> p{};
        bool known = true;
        for (std::size_t c = 0; c < 4 && known; ++c) {
            const auto it = node_index.find(el.mNodes[c]);
            known = it != node_index.end();
            if (known)
                for (std::size_t d = 0; d < 3; ++d)
                    p[c][d] = coords[3 * static_cast<std::size_t>(it->second) + d];
        }
        if (!known)
            continue;
        double a[3], b[3], c[3];
        for (std::size_t d = 0; d < 3; ++d) {
            a[d] = p[1][d] - p[0][d];
            b[d] = p[2][d] - p[0][d];
            c[d] = p[3][d] - p[0][d];
        }
        const double det = a[0] * (b[1] * c[2] - b[2] * c[1]) - a[1] * (b[0] * c[2] - b[2] * c[0]) +
                           a[2] * (b[0] * c[1] - b[1] * c[0]);
        if (det >= 0.0)
            continue;
        std::swap(el.mNodes[1], el.mNodes[2]);
        if (el.mNodes.size() == 10) {  // edges 0-1 <-> 0-2 and 1-3 <-> 2-3
            std::swap(el.mNodes[4], el.mNodes[6]);
            std::swap(el.mNodes[8], el.mNodes[9]);
        }
        ++reoriented;
    }
    if (reoriented)
        log::warn("Radioss: {} inverted tetrahedra reoriented", reoriented);

    for (const std::string& type : block_types) {
        const std::vector<std::size_t>& members = by_type[type];
        const std::size_t k =
            static_cast<std::size_t>(cell_type_num_nodes(cell_type_from_name(type)));
        const int dim = cell_type_dimension(cell_type_from_name(type));
        NDArray conn(DType::Int64, {members.size(), k});
        NDArray pa(DType::Int64, {members.size()}), pr(DType::Int64, {members.size()}),
            ma(DType::Int64, {members.size()});
        for (std::size_t r = 0; r < members.size(); ++r) {
            const RadElement& el = elements[members[r]];
            for (std::size_t j = 0; j < k; ++j) {
                const auto it = node_index.find(el.mNodes[j]);
                if (it == node_index.end())
                    throw ReadError("Radioss: element " + std::to_string(el.mId) +
                                    " names undefined node " + std::to_string(el.mNodes[j]) + " (" +
                                    el.mWhere + ")");
                conn.As<std::int64_t>()[r * k + j] = it->second;
            }
            const std::int64_t cell = static_cast<std::int64_t>(cell_part.size());
            if (!owner[el.mFamily].emplace(el.mId, cell).second)
                throw ReadError("Radioss: element " + std::to_string(el.mId) +
                                " is defined twice (" + el.mWhere + ")");
            const auto p = parts.find(el.mPart);
            pa.As<std::int64_t>()[r] = el.mPart;
            pr.As<std::int64_t>()[r] = p == parts.end() ? 0 : p->second.mProperty;
            ma.As<std::int64_t>()[r] = p == parts.end() ? 0 : p->second.mMaterial;
            part_cells[el.mPart].push_back(cell);
            cell_part.push_back(el.mPart);
            cell_dim.push_back(dim);
        }
        mesh.AddCellBlock(type, std::move(conn));
        part_blocks.push_back(std::move(pa));
        prop_blocks.push_back(std::move(pr));
        mat_blocks.push_back(std::move(ma));
    }
    if (!block_types.empty()) {
        mesh.AddCellData("radioss:part", std::move(part_blocks));
        mesh.AddCellData("radioss:property", std::move(prop_blocks));
        mesh.AddCellData("radioss:material", std::move(mat_blocks));
    }

    // --- regions ------------------------------------------------------------------
    std::set<std::tuple<int, std::string, std::int64_t>> seen;
    auto add_region = [&](std::string name, RegionKind kind, std::int64_t tag,
                          const std::string& rKeyword, std::vector<std::int64_t> entries) {
        int dim = -1;
        if (kind == RegionKind::Cell)
            for (std::int64_t c : entries)
                dim = std::max(dim, cell_dim[static_cast<std::size_t>(c)]);
        else if (kind == RegionKind::Side)
            for (std::size_t k = 0; k < entries.size(); k += 2)
                dim = std::max(dim, cell_dim[static_cast<std::size_t>(entries[k])] - 1);
        const int kid = static_cast<int>(kind);
        if (seen.count({kid, name, tag}))
            name += " [" + rKeyword + "]";
        seen.emplace(kid, name, tag);
        mesh.AddRegion(
            Region(name, kind, dim, tag, rad_ids(entries, kind == RegionKind::Side ? 2 : 1)));
    };
    // Parts named in elements but never defined still get a region.
    for (const auto& [pid, cells] : part_cells)
        if (!parts.count(pid)) {
            parts.emplace(pid, RadPart{});
            part_order.push_back(pid);
        }
    for (std::int64_t pid : part_order) {
        const RadPart& p = parts[pid];
        const auto it = part_cells.find(pid);
        add_region(p.mTitle.empty() ? "Part " + std::to_string(pid) : p.mTitle, RegionKind::Cell,
                   pid, "PART", it == part_cells.end() ? std::vector<std::int64_t>{} : it->second);
    }
    // A subset and every subset under it.
    auto subset_closure = [&](std::int64_t Root) {
        std::set<std::int64_t> ids;
        std::vector<std::int64_t> stack{Root};
        while (!stack.empty()) {
            const std::int64_t c = stack.back();
            stack.pop_back();
            if (!ids.insert(c).second)
                continue;
            const auto it = subsets.find(c);
            if (it != subsets.end())
                stack.insert(stack.end(), it->second.mChildren.begin(), it->second.mChildren.end());
        }
        return ids;
    };
    for (const auto& [sid, s] : subsets) {
        const std::set<std::int64_t> ids = subset_closure(sid);
        std::vector<std::int64_t> cells;
        for (std::int64_t pid : part_order)
            if (ids.count(parts[pid].mSubset)) {
                const auto it = part_cells.find(pid);
                if (it != part_cells.end())
                    cells.insert(cells.end(), it->second.begin(), it->second.end());
            }
        add_region(s.mTitle.empty() ? "Subset " + std::to_string(sid) : s.mTitle, RegionKind::Cell,
                   sid, "SUBSET", std::move(cells));
    }

    // Groups: resolved recursively (a group can list other groups).
    std::map<std::pair<std::string, std::int64_t>, std::size_t> group_of;
    for (std::size_t g = 0; g < groups.size(); ++g)
        group_of[{groups[g].mKeyword, groups[g].mId}] = g;
    std::set<std::string> skipped_subtypes;
    std::size_t dropped = 0;
    // A PART subtype stands for the parts' nodes in a GRNOD, and for the parts'
    // cells of the group's own family in an element group.
    std::vector<std::string> cell_family(cell_part.size());
    for (const auto& [family, map] : owner)
        for (const auto& [id, cell] : map)
            cell_family[static_cast<std::size_t>(cell)] = family;
    std::vector<std::vector<std::int64_t>> cell_conn;
    for (std::size_t b = 0; b < mesh.NumCellBlocks(); ++b) {
        const auto cb = mesh.Cells(b);
        const NDArray& conn = cb.Conn();
        const std::size_t k = cb.NodesPerCell();
        for (std::size_t r = 0; r < cb.NumCells(); ++r)
            cell_conn.emplace_back(conn.As<std::int64_t>() + r * k,
                                   conn.As<std::int64_t>() + (r + 1) * k);
    }
    // Box membership of a point (skewed boxes are not supported: empty).
    auto point_of = [&](std::int64_t Node, const std::array<double, 3>& rFallback) {
        const auto it = Node ? node_index.find(Node) : node_index.end();
        if (it == node_index.end())
            return rFallback;
        const std::size_t p = static_cast<std::size_t>(it->second);
        return std::array<double, 3>{coords[3 * p], coords[3 * p + 1], coords[3 * p + 2]};
    };
    std::set<std::int64_t> skewed_boxes, missing_boxes;
    std::function<bool(std::int64_t, const double*, int)> in_box;
    in_box = [&](std::int64_t Id, const double* pX, int Depth) -> bool {
        const auto it = boxes.find(Id);
        if (it == boxes.end() || Depth > 16) {
            missing_boxes.insert(Id);
            return false;
        }
        const RadBox& b = it->second;
        if (b.mKind == "BOX") {
            bool in = false;
            for (std::int64_t c : b.mChildren)
                if (c > 0 && in_box(c, pX, Depth + 1))
                    in = true;
            for (std::int64_t c : b.mChildren)
                if (c < 0 && in_box(-c, pX, Depth + 1))
                    in = false;
            return in;
        }
        const std::array<double, 3> p1 = point_of(b.mNode1, b.mP1);
        if (b.mSkew && b.mKind == "RECTA") {
            // Edges along the skew's axes: compare in the skew frame.
            const auto sk = skews.find(b.mSkew);
            std::array<std::array<double, 3>, 3> axes;
            if (sk == skews.end() || !rad_skew_axes(sk->second, axes)) {
                skewed_boxes.insert(Id);
                return false;
            }
            const std::array<double, 3> p2 = point_of(b.mNode2, b.mP2);
            for (const auto& a : axes) {
                const double x = a[0] * pX[0] + a[1] * pX[1] + a[2] * pX[2];
                const double u = a[0] * p1[0] + a[1] * p1[1] + a[2] * p1[2];
                const double v = a[0] * p2[0] + a[1] * p2[1] + a[2] * p2[2];
                if (x < std::min(u, v) || x > std::max(u, v))
                    return false;
            }
            return true;
        }
        if (b.mKind == "SPHER") {
            double d2 = 0.0;
            for (std::size_t d = 0; d < 3; ++d)
                d2 += (pX[d] - p1[d]) * (pX[d] - p1[d]);
            return d2 <= 0.25 * b.mDiameter * b.mDiameter;
        }
        const std::array<double, 3> p2 = point_of(b.mNode2, b.mP2);
        if (b.mKind == "RECTA") {
            for (std::size_t d = 0; d < 3; ++d)
                if (pX[d] < std::min(p1[d], p2[d]) || pX[d] > std::max(p1[d], p2[d]))
                    return false;
            return true;
        }
        if (b.mKind == "CYLIN") {
            double a[3], q[3], aa = 0.0, qa = 0.0;
            for (std::size_t d = 0; d < 3; ++d) {
                a[d] = p2[d] - p1[d];
                q[d] = pX[d] - p1[d];
                aa += a[d] * a[d];
                qa += q[d] * a[d];
            }
            if (aa == 0.0 || qa < 0.0 || qa > aa)
                return false;
            double r2 = 0.0;
            for (std::size_t d = 0; d < 3; ++d) {
                const double off = q[d] - qa / aa * a[d];
                r2 += off * off;
            }
            return r2 <= 0.25 * b.mDiameter * b.mDiameter;
        }
        return false;
    };
    std::function<std::set<std::int64_t>(std::size_t, std::set<std::size_t>&)> resolve;
    resolve = [&](std::size_t g, std::set<std::size_t>& rVisiting) -> std::set<std::int64_t> {
        std::set<std::int64_t> out;
        if (!rVisiting.insert(g).second)
            return out;
        const RadGroup& grp = groups[g];
        const std::string family = rad_group_family(grp.mKeyword);
        const bool nodes = family == "NODE";
        // GENE: `first last` id ranges; GEN_INCR: `first last step`.
        if (grp.mSubtype == "GENE" || grp.mSubtype == "GEN_INCR") {
            const std::size_t w = grp.mSubtype == "GENE" ? 2 : 3;
            auto take = [&](std::int64_t Id, std::int64_t Entity) {
                for (std::size_t k = 0; k + w <= grp.mIds.size(); k += w) {
                    const std::int64_t first = grp.mIds[k], last = grp.mIds[k + 1];
                    const std::int64_t step = w == 3 ? grp.mIds[k + 2] : 1;
                    if (Id >= first && Id <= last && step > 0 && (Id - first) % step == 0) {
                        out.insert(Entity);
                        return;
                    }
                }
            };
            if (nodes)
                for (const auto& [id, p] : node_index)
                    take(id, p);
            else
                for (const auto& [id, cell] : owner[family])
                    take(id, cell);
            rVisiting.erase(g);
            return out;
        }
        std::set<std::int64_t> removed;
        for (std::int64_t raw : grp.mIds) {
            const std::int64_t id = raw < 0 ? -raw : raw;
            std::set<std::int64_t> hits;
            if (grp.mSubtype == family) {
                if (nodes) {
                    const auto it = node_index.find(id);
                    if (it != node_index.end())
                        hits.insert(it->second);
                    else
                        ++dropped;
                } else {
                    const auto& map = owner[family];
                    const auto it = map.find(id);
                    if (it != map.end())
                        hits.insert(it->second);
                    else
                        ++dropped;
                }
            } else if (grp.mSubtype == "PART" || grp.mSubtype == "SUBSET") {
                // The parts' nodes for GRNOD, else their cells of the group's family.
                std::vector<std::int64_t> pids{id};
                if (grp.mSubtype == "SUBSET") {
                    pids.clear();
                    for (std::int64_t pid : part_order)
                        if (subset_closure(id).count(parts[pid].mSubset))
                            pids.push_back(pid);
                }
                for (std::int64_t pid : pids) {
                    const auto it = part_cells.find(pid);
                    if (it == part_cells.end())
                        continue;
                    for (std::int64_t c : it->second) {
                        if (nodes)
                            hits.insert(cell_conn[static_cast<std::size_t>(c)].begin(),
                                        cell_conn[static_cast<std::size_t>(c)].end());
                        else if (cell_family[static_cast<std::size_t>(c)] == family)
                            hits.insert(c);
                    }
                }
            } else if (grp.mSubtype == "BOX" || grp.mSubtype == "BOX2") {
                // Nodes inside; elements with all (BOX) or any (BOX2) node inside.
                const bool any = grp.mSubtype == "BOX2";
                if (nodes) {
                    for (std::size_t p = 0; p < node_ids.size(); ++p)
                        if (in_box(id, &coords[3 * p], 0))
                            hits.insert(static_cast<std::int64_t>(p));
                } else {
                    for (const auto& [eid, cell] : owner[family]) {
                        const auto& conn = cell_conn[static_cast<std::size_t>(cell)];
                        std::size_t inside = 0;
                        for (std::int64_t p : conn)
                            inside +=
                                in_box(id, &coords[3 * static_cast<std::size_t>(p)], 0) ? 1 : 0;
                        if (any ? inside > 0 : inside == conn.size())
                            hits.insert(cell);
                    }
                }
            } else if (nodes && grp.mSubtype == "SURF") {
                for (const RadSurface& surf : surfaces)
                    if (surf.mId == id)
                        for (const auto& seg : surf.mSegments)
                            for (std::int64_t v : seg) {
                                const auto it = node_index.find(v);
                                if (v && it != node_index.end())
                                    hits.insert(it->second);
                            }
            } else if (nodes && rad_group_family(grp.mSubtype) &&
                       std::string(rad_group_family(grp.mSubtype)) != "NODE") {
                // A GRNOD of element groups: those elements' nodes.
                const auto it = group_of.find({grp.mSubtype, id});
                if (it != group_of.end())
                    for (std::int64_t c : resolve(it->second, rVisiting))
                        hits.insert(cell_conn[static_cast<std::size_t>(c)].begin(),
                                    cell_conn[static_cast<std::size_t>(c)].end());
            } else if (grp.mSubtype == grp.mKeyword) {
                const auto it = group_of.find({grp.mKeyword, id});
                if (it != group_of.end()) {
                    const std::set<std::int64_t> sub = resolve(it->second, rVisiting);
                    hits.insert(sub.begin(), sub.end());
                }
            } else {
                skipped_subtypes.insert("/" + grp.mKeyword + "/" + grp.mSubtype);
                break;
            }
            (raw < 0 ? removed : out).insert(hits.begin(), hits.end());
        }
        for (std::int64_t r : removed)
            out.erase(r);
        rVisiting.erase(g);
        return out;
    };
    for (std::size_t g = 0; g < groups.size(); ++g) {
        std::set<std::size_t> visiting;
        const RadGroup& grp = groups[g];
        const std::string family = rad_group_family(grp.mKeyword);
        const std::set<std::int64_t> ids = resolve(g, visiting);
        std::vector<std::int64_t> entries(ids.begin(), ids.end());
        add_region(grp.mTitle.empty() ? grp.mKeyword + "_" + std::to_string(grp.mId) : grp.mTitle,
                   family == "NODE" ? RegionKind::Point : RegionKind::Cell, grp.mId, grp.mKeyword,
                   std::move(entries));
    }
    for (const std::string& t : skipped_subtypes)
        log::warn(
            "Radioss: {} groups are not resolved (only entity ids, parts and other groups "
            "are); their regions are left empty or partial",
            t);

    // Surfaces -> side regions; a shell segment is the shell's own face.
    if (!surfaces.empty()) {
        detail::FacetIndexOptions options;
        options.mSurfaceSelf = true;
        const detail::FacetIndex facets(mesh, options);
        // Solid faces: (cell, face) with their sorted corners.
        auto solid_faces = [&](std::int64_t Cell) {
            std::vector<std::pair<std::int64_t, std::vector<std::int64_t>>> out;
            CellType type{};
            std::vector<std::int64_t> fnodes;
            for (std::int64_t f = 0; detail::facet_nodes(mesh, Cell, f, type, fnodes); ++f) {
                const std::size_t corners = cell_type_name(type).rfind("triangle", 0) == 0 ? 3 : 4;
                fnodes.resize(std::min(corners, fnodes.size()));
                std::sort(fnodes.begin(), fnodes.end());
                out.emplace_back(f, fnodes);
            }
            return out;
        };
        std::map<std::vector<std::int64_t>, std::size_t> model_faces;  // for FREE
        bool counted = false;
        const std::map<std::string, std::string> group_keyword = {
            {"GRBRIC", "GRBRIC"}, {"GRSHEL", "GRSHEL"}, {"GRSH3N", "GRSH3N"}, {"GRTRIA", "GRTRIA"}};
        std::map<std::int64_t, std::size_t> surface_of;
        for (std::size_t k = 0; k < surfaces.size(); ++k)
            surface_of.emplace(surfaces[k].mId, k);
        std::map<std::size_t, std::set<std::pair<std::int64_t, std::int64_t>>> done;
        std::function<std::set<std::pair<std::int64_t, std::int64_t>>(std::size_t, int)> side_set;
        side_set = [&](std::size_t Index, int Depth) {
            const auto memo = done.find(Index);
            if (memo != done.end())
                return memo->second;
            std::set<std::pair<std::int64_t, std::int64_t>> out;
            const RadSurface& s = surfaces[Index];
            if (s.mKind == "SURF") {
                std::set<std::pair<std::int64_t, std::int64_t>> minus;
                for (std::int64_t raw : s.mIds) {
                    const auto it = surface_of.find(raw < 0 ? -raw : raw);
                    if (it == surface_of.end() || Depth > 16) {
                        ++dropped;
                        continue;
                    }
                    const auto sub = side_set(it->second, Depth + 1);
                    (raw < 0 ? minus : out).insert(sub.begin(), sub.end());
                }
                for (const auto& e : minus)
                    out.erase(e);
            } else if (s.mKind == "BOX" || s.mKind == "BOX2") {
                // Shell faces with all (BOX) or any (BOX2) node in the box;
                // with EXT the model's external solid faces, with ALL every
                // solid face, likewise.
                const bool any = s.mKind == "BOX2";
                const std::int64_t box = s.mIds.empty() ? 0 : s.mIds[0];
                auto inside = [&](const std::vector<std::int64_t>& rPts) {
                    std::size_t n = 0;
                    for (std::int64_t p : rPts)
                        n += in_box(box, &coords[3 * static_cast<std::size_t>(p)], 0) ? 1 : 0;
                    return any ? n > 0 : n == rPts.size();
                };
                if (s.mMode == "EXT" && !counted) {
                    for (std::size_t c = 0; c < cell_dim.size(); ++c)
                        if (cell_dim[c] == 3)
                            for (const auto& [f, key] : solid_faces(static_cast<std::int64_t>(c)))
                                ++model_faces[key];
                    counted = true;
                }
                for (std::size_t c = 0; c < cell_conn.size(); ++c) {
                    const std::string& fam = cell_family[c];
                    if (fam == "SHEL" || fam == "SH3N" || fam == "TRIA") {
                        if (inside(cell_conn[c]))
                            out.emplace(static_cast<std::int64_t>(c), 0);
                    } else if (cell_dim[c] == 3 && !s.mMode.empty()) {
                        for (const auto& [f, key] : solid_faces(static_cast<std::int64_t>(c)))
                            if ((s.mMode == "ALL" || model_faces[key] == 1) && inside(key))
                                out.emplace(static_cast<std::int64_t>(c), f);
                    }
                }
            } else if (s.mKind == "SEG") {
                for (const auto& seg : s.mSegments) {
                    std::array<std::int64_t, 4> idx{};
                    bool defined = true;
                    // 2 nodes in a 2-D analysis, 3 for a triangle (n4 blank or n3).
                    const std::size_t count =
                        seg[2] == 0 ? 2 : ((seg[3] == 0 || seg[3] == seg[2]) ? 3 : 4);
                    for (std::size_t k = 0; k < count; ++k) {
                        const auto it = node_index.find(seg[k]);
                        defined = defined && it != node_index.end();
                        idx[k] = defined ? it->second : -1;
                    }
                    const detail::FacetHit* hit =
                        defined ? facets.Find(idx.data(), count) : nullptr;
                    if (!hit) {
                        ++dropped;
                        continue;
                    }
                    out.emplace(hit->mFirst.mCell, hit->mFirst.mFacet);
                }
            } else {
                // The cells the surface draws from.
                std::set<std::int64_t> cells;
                if (group_keyword.count(s.mKind)) {
                    for (std::int64_t raw : s.mIds) {
                        const auto it = group_of.find({s.mKind, raw < 0 ? -raw : raw});
                        if (it == group_of.end()) {
                            ++dropped;
                            continue;
                        }
                        std::set<std::size_t> visiting;
                        for (std::int64_t c : resolve(it->second, visiting))
                            cells.insert(c);
                    }
                } else {
                    for (std::int64_t raw : s.mIds) {
                        const std::int64_t id = raw < 0 ? -raw : raw;
                        const std::set<std::int64_t> sub =
                            s.mKind == "SUBSET" ? subset_closure(id) : std::set<std::int64_t>{};
                        for (std::size_t c = 0; c < cell_part.size(); ++c) {
                            const RadPart& part = parts[cell_part[c]];
                            const bool pick = s.mKind == "PART"     ? cell_part[c] == id
                                              : s.mKind == "SUBSET" ? sub.count(part.mSubset) > 0
                                              : s.mKind == "MAT"    ? part.mMaterial == id
                                                                    : part.mProperty == id;
                            if (pick)
                                cells.insert(static_cast<std::int64_t>(c));
                        }
                    }
                }
                // Shells: their own face. Solids: with EXT the faces no other
                // chosen solid shares, with FREE those no solid of the model
                // shares, with ALL every face (GRBRIC without a mode: EXT).
                const std::string mode = s.mKind == "GRBRIC" && s.mMode.empty() ? "EXT" : s.mMode;
                std::map<std::vector<std::int64_t>, std::size_t> chosen;
                std::vector<std::pair<
                    std::int64_t, std::vector<std::pair<std::int64_t, std::vector<std::int64_t>>>>>
                    solids;
                for (std::int64_t c : cells) {
                    const std::string& fam = cell_family[static_cast<std::size_t>(c)];
                    if (fam == "SHEL" || fam == "SH3N" || fam == "TRIA")
                        out.emplace(c, 0);
                    else if (cell_dim[static_cast<std::size_t>(c)] == 3 && !mode.empty()) {
                        solids.emplace_back(c, solid_faces(c));
                        for (const auto& [f, key] : solids.back().second)
                            ++chosen[key];
                    }
                }
                if (mode == "FREE" && !counted) {
                    for (std::size_t c = 0; c < cell_dim.size(); ++c)
                        if (cell_dim[c] == 3)
                            for (const auto& [f, key] : solid_faces(static_cast<std::int64_t>(c)))
                                ++model_faces[key];
                    counted = true;
                }
                for (const auto& [c, faces] : solids)
                    for (const auto& [f, key] : faces) {
                        const std::size_t shared =
                            mode == "FREE" ? model_faces[key] : (mode == "EXT" ? chosen[key] : 1);
                        if (shared == 1)
                            out.emplace(c, f);
                    }
            }
            done[Index] = out;
            return out;
        };
        for (std::size_t index = 0; index < surfaces.size(); ++index) {
            const RadSurface& s = surfaces[index];
            std::vector<std::int64_t> entries;
            for (const auto& [c, f] : side_set(index, 0)) {
                entries.push_back(c);
                entries.push_back(f);
            }
            add_region(s.mTitle.empty() ? "SURF_" + std::to_string(s.mId) : s.mTitle,
                       RegionKind::Side, s.mId, "SURF", std::move(entries));
        }
    }
    for (std::int64_t id : skewed_boxes)
        log::warn("Radioss: /BOX {} names a skew that is not a /SKEW/FIX; it contains nothing", id);
    for (auto& [name, values] : analytic) {
        // An ellipsoid's orientation: its skew's axes (the identity without one).
        const std::int64_t id = std::stoll(name.substr(name.rfind(':') + 1));
        const auto es = name.rfind("radioss:surf_ellips:", 0) == 0 ? ellipsoid_skew.find(id)
                                                                   : ellipsoid_skew.end();
        if (es != ellipsoid_skew.end()) {
            std::array<std::array<double, 3>, 3> axes = {
                std::array<double, 3>{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
            const auto skew = static_cast<std::int64_t>(es->second[0]);
            if (skew) {
                const auto sk = skews.find(skew);
                if (sk == skews.end() || !rad_skew_axes(sk->second, axes))
                    log::warn("Radioss: /SURF/ELLIPS {} names a skew that is not a /SKEW/FIX", id);
            }
            for (const auto& a : axes)
                values.insert(values.end(), a.begin(), a.end());
        }
        NDArray a(DType::Float64, {values.size()});
        std::copy(values.begin(), values.end(), a.As<double>());
        mesh.AddFieldData(name, std::move(a));
    }
    for (std::int64_t id : missing_boxes)
        log::warn("Radioss: /BOX {} is not defined; it contains nothing", id);
    if (dropped)
        log::warn(
            "Radioss: {} group or surface entries name undefined ids or no cell facet and "
            "were dropped",
            dropped);
    // A starter deck `<run>_0000.rad`: its engine deck `<run>_0001.rad`'s controls.
    {
        const fs::path starter(rPath);
        const std::string stem = starter.stem().string();
        if (stem.size() > 5 && stem.compare(stem.size() - 5, 5, "_0000") == 0) {
            const fs::path engine =
                starter.parent_path() /
                (stem.substr(0, stem.size() - 5) + "_0001" + starter.extension().string());
            std::error_code ec;
            if (fs::is_regular_file(engine, ec))
                rad_add_engine_fields(mesh, engine.string());
        }
    }
    return mesh;
}

// ---------------------------------------------------------------------------
// Writing. The Python twin is radioss/_radioss.py's `write`; both give the
// same bytes.
// ---------------------------------------------------------------------------

namespace {

constexpr int kRadWriteVersion = 2022;
constexpr std::size_t kRadTitleWidth = 100;

/// The starter card that writes a meshio++ type ("" when none does). A
/// pyramid and a wedge are degenerate /BRICKs (`1 2 3 4 5 5 5 5`,
/// `1 3 6 4 2 2 5 5`), which the reader collapses back and which need no
/// formulation of their own, unlike /PENTA6.
const char* radw_card(std::string_view Type) {
    static const std::map<std::string, const char*, std::less<>> m = {
        {"hexahedron", "BRICK"}, {"pyramid", "BRICK"},   {"wedge", "BRICK"},
        {"tetra", "TETRA4"},     {"tetra10", "TETRA10"}, {"hexahedron20", "BRIC20"},
        {"quad", "SHELL"},       {"triangle", "SH3N"},   {"line", "TRUSS"}};
    const auto it = m.find(Type);
    return it == m.end() ? "" : it->second;
}

/// A card's group family (the reader's `/GR<family>` naming).
std::string radw_family(const std::string& rCard) {
    if (rCard == "SHELL")
        return "SHEL";
    if (rCard == "SH3N")
        return "SH3N";
    if (rCard == "TRUSS")
        return "TRUS";
    return "BRIC";
}

std::string radw_group_keyword(const std::string& rFamily) {
    return "GR" + rFamily;
}

/// The stub property type a card's part needs.
std::string radw_stub_kind(const std::string& rCard) {
    if (rCard == "SHELL" || rCard == "SH3N")
        return "SHELL";
    if (rCard == "TRUSS")
        return "TRUSS";
    return "SOLID";
}

/// The stub property cards `rCards` can share, (type, Isolid); false when
/// they need different types. /BRIC20 needs Isolid 16, the other solids the
/// default 0; a part mixing /BRIC20 and /BRICK gets 0, which the starter turns
/// to 16 for the /BRIC20 with a warning.
bool radw_stub_share(const std::set<std::string>& rCards, std::pair<std::string, int>& rNeed) {
    std::set<std::string> kinds;
    bool brick = false;
    bool bric20 = false;
    for (const std::string& card : rCards) {
        kinds.insert(radw_stub_kind(card));
        brick = brick || card == "BRICK";
        bric20 = bric20 || card == "BRIC20";
    }
    if (kinds.size() != 1)
        return false;
    rNeed = {*kinds.begin(), bric20 && !brick ? 16 : 0};
    return true;
}

void radw_i10(std::string& rOut, std::int64_t Value) {
    const std::string t = std::to_string(Value);
    if (t.size() < 10)
        rOut.append(10 - t.size(), ' ');
    rOut += t;
}

/// A real in an F20 field: exact when its shortest spelling fits, else the 20
/// columns' worth of digits.
void radw_f20(std::string& rOut, double Value) {
    std::string t = detail::format_real_short(Value);
    if (t.size() > 20)
        t = detail::format_real_fit(Value, 20);
    if (t.size() < 20)
        rOut.append(20 - t.size(), ' ');
    rOut += t;
}

/// A title line: one line, at most 100 characters, never read as a comment or
/// a keyword (a leading `#`, `$` or `/` gets a space in front).
std::string radw_title(const std::string& rName) {
    std::string t = rName;
    for (char& c : t)
        if (c == '\r' || c == '\n')
            c = ' ';
    const std::size_t b = t.find_first_not_of(" \t\v\f");
    if (b == std::string::npos)
        return {};
    t = t.substr(b, t.find_last_not_of(" \t\v\f") - b + 1);
    if (t[0] == '#' || t[0] == '$' || t[0] == '/')
        t = " " + t;
    return t.substr(0, kRadTitleWidth);
}

void radw_ids_lines(std::vector<std::string>& rOut, const std::vector<std::int64_t>& rIds) {
    for (std::size_t k = 0; k < rIds.size(); k += 10) {
        std::string line;
        for (std::size_t j = k; j < std::min(k + 10, rIds.size()); ++j)
            radw_i10(line, rIds[j]);
        rOut.push_back(std::move(line));
    }
}

/// One id namespace: a tag when positive and free, else the next free id.
struct RadwIds {
    std::set<std::int64_t> mUsed;
    std::int64_t mNext = 1;
    std::int64_t Take(std::int64_t Tag = 0) {
        if (Tag > 0 && mUsed.insert(Tag).second)
            return Tag;
        while (mUsed.count(mNext))
            ++mNext;
        mUsed.insert(mNext);
        return mNext;
    }
};

struct RadwCell {
    std::size_t mBlock = 0;
    std::size_t mRow = 0;
    std::string mCard;  // empty: not written
};

struct RadwPart {
    std::int64_t mId;
    std::string mTitle;
    std::int64_t mProp;
    std::int64_t mMat;
};

/// A region's entries, flattened: (cell, facet) pairs for a side region.
std::vector<std::int64_t> radw_entries(const Region& rRegion) {
    const std::size_t n = rRegion.NumEntries() * rRegion.Stride();
    return n ? std::vector<std::int64_t>(rRegion.Entries(), rRegion.Entries() + n)
             : std::vector<std::int64_t>();
}

}  // namespace

void write_radioss(const std::string& rPath, const Mesh& rMesh, bool Stubs) {
    const NDArray& points = rMesh.Points();
    const detail::DoubleView point_values(points);
    const std::size_t pdim = rMesh.PointDim();
    // One view per block of connectivity, made on first use: cards and sides
    // look cells up by (block, row).
    std::vector<std::optional<detail::Int64View>> conn_views(rMesh.NumCellBlocks());
    const auto conn_at = [&](std::size_t Block, std::size_t Index) {
        if (!conn_views[Block])
            conn_views[Block].emplace(rMesh.Cells(Block).Conn());
        return (*conn_views[Block])[Index];
    };
    if (pdim > 3)
        throw WriteError("Radioss writer: points must have 1 to 3 coordinates");
    const std::size_t npts = rMesh.NumPoints();
    if (npts == 0)
        throw WriteError("Radioss writer: a starter deck needs nodes; the mesh has none");

    // Cells: which are written, as what, with which element id.
    std::vector<RadwCell> info;
    std::set<std::string> dropped_types;
    for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
        const auto cb = rMesh.Cells(b);
        std::string card = radw_card(cb.Type());
        if (card.empty() || cb.IsRagged()) {
            dropped_types.insert(std::string(cb.Type()));
            card.clear();
        }
        for (std::size_t r = 0; r < cb.NumCells(); ++r)
            info.push_back({b, r, card});
    }
    for (const std::string& t : dropped_types) {
        log::warn("Radioss writer: '{}' cells have no starter element card; dropped", t);
        detail::provenance_note("cells-dropped",
                                "Radioss has no element card for '" + t + "' cells");
    }
    const std::size_t ncells = info.size();
    const auto written = [&](std::int64_t c) {
        return c >= 0 && static_cast<std::size_t>(c) < ncells &&
               !info[static_cast<std::size_t>(c)].mCard.empty();
    };
    const auto family = [&](std::size_t c) { return radw_family(info[c].mCard); };

    std::vector<bool> used_regions(rMesh.NumRegions(), false);
    const auto cell_array_ok = [&](const std::string& rName) {
        return rMesh.HasCellData(rName) && rMesh.CellDataNumBlocks(rName) == rMesh.NumCellBlocks();
    };

    // Parts: radioss:part when the mesh carries it, else cell regions of one
    // family, else one part per block.
    RadwIds part_ids;
    std::vector<std::int64_t> cell_part(ncells, 0);
    std::vector<RadwPart> parts;
    if (cell_array_ok("radioss:part")) {
        // Part ids come from the data; an id of 0 or less gets a new one.
        std::vector<std::int64_t> raw(ncells, 0);
        std::vector<std::optional<detail::Int64View>> part_views(rMesh.NumCellBlocks());
        for (std::size_t c = 0; c < ncells; ++c) {
            auto& view = part_views[info[c].mBlock];
            if (!view)
                view.emplace(rMesh.CellData("radioss:part", info[c].mBlock));
            raw[c] = (*view)[info[c].mRow];
            if (!info[c].mCard.empty() && raw[c] > 0)
                part_ids.mUsed.insert(raw[c]);
        }
        std::map<std::int64_t, std::int64_t> renumbered;
        for (std::size_t c = 0; c < ncells; ++c) {
            if (info[c].mCard.empty())
                continue;
            std::int64_t pid = raw[c];
            if (pid <= 0) {
                auto it = renumbered.find(pid);
                if (it == renumbered.end())
                    it = renumbered.emplace(pid, part_ids.Take()).first;
                pid = it->second;
            }
            cell_part[c] = pid;
        }
        if (!renumbered.empty())
            log::warn("Radioss writer: cells with a part id of 0 or less put in new parts");
        const bool has_prop = cell_array_ok("radioss:property");
        const bool has_mat = cell_array_ok("radioss:material");
        std::vector<std::int64_t> order;
        std::map<std::int64_t, std::vector<std::int64_t>> members;
        std::map<std::int64_t, std::size_t> first;
        for (std::size_t c = 0; c < ncells; ++c) {
            if (info[c].mCard.empty())
                continue;
            const std::int64_t pid = cell_part[c];
            if (!members.count(pid)) {
                order.push_back(pid);
                first[pid] = c;
            }
            members[pid].push_back(static_cast<std::int64_t>(c));
        }
        for (const std::int64_t pid : order) {
            std::string title;
            for (std::size_t k = 0; k < rMesh.NumRegions(); ++k) {
                const Region& reg = rMesh.Region(k);
                if (used_regions[k] || reg.mKind != RegionKind::Cell || reg.mTag != pid)
                    continue;
                std::vector<std::int64_t> e = radw_entries(reg);
                std::sort(e.begin(), e.end());
                if (e == members[pid]) {
                    title = reg.mName;
                    used_regions[k] = true;
                    break;
                }
            }
            const RadwCell& f = info[first[pid]];
            const std::int64_t prop =
                has_prop ? detail::read_int(rMesh.CellData("radioss:property", f.mBlock), f.mRow)
                         : pid;
            const std::int64_t mat =
                has_mat ? detail::read_int(rMesh.CellData("radioss:material", f.mBlock), f.mRow)
                        : 1;
            parts.push_back({pid, title, prop, mat});
        }
    } else {
        std::vector<bool> claimed(ncells, false);
        for (std::size_t k = 0; k < rMesh.NumRegions(); ++k) {
            const Region& reg = rMesh.Region(k);
            if (reg.mKind != RegionKind::Cell)
                continue;
            std::vector<std::int64_t> cells = radw_entries(reg);
            std::sort(cells.begin(), cells.end());
            cells.erase(std::unique(cells.begin(), cells.end()), cells.end());
            if (cells.empty())
                continue;
            // One stub property must be able to serve a part.
            bool ok = true;
            std::set<std::string> region_cards;
            for (const std::int64_t c : cells) {
                if (!written(c) || claimed[static_cast<std::size_t>(c)]) {
                    ok = false;
                    break;
                }
                region_cards.insert(info[static_cast<std::size_t>(c)].mCard);
            }
            std::pair<std::string, int> shared;
            if (!ok || !radw_stub_share(region_cards, shared))
                continue;
            const std::int64_t pid = part_ids.Take(reg.mTag);
            for (const std::int64_t c : cells) {
                claimed[static_cast<std::size_t>(c)] = true;
                cell_part[static_cast<std::size_t>(c)] = pid;
            }
            used_regions[k] = true;
            parts.push_back({pid, reg.mName, pid, 1});
        }
        std::size_t g = 0;
        for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
            const auto cb = rMesh.Cells(b);
            std::int64_t pid = 0;
            for (std::size_t r = 0; r < cb.NumCells(); ++r, ++g) {
                if (info[g].mCard.empty() || claimed[g])
                    continue;
                if (pid == 0) {
                    pid = part_ids.Take();
                    parts.push_back({pid, std::string(cb.Type()), pid, 1});
                }
                cell_part[g] = pid;
            }
        }
    }

    // Subsets: a remaining cell region that is exactly a union of whole parts,
    // smallest first, so a subset nested in another is its child.
    std::map<std::int64_t, std::set<std::int64_t>> part_cells;
    for (std::size_t c = 0; c < ncells; ++c)
        if (!info[c].mCard.empty())
            part_cells[cell_part[c]].insert(static_cast<std::int64_t>(c));
    std::map<std::int64_t, std::int64_t> part_subset;
    std::map<std::int64_t, std::set<std::int64_t>> subset_parts;
    RadwIds subset_ids;
    struct RadwSubset {
        std::int64_t mId;
        std::string mTitle;
        std::vector<std::int64_t> mChildren;
    };
    std::vector<RadwSubset> subsets;
    std::vector<std::tuple<std::size_t, std::size_t, std::set<std::int64_t>>> candidates;
    for (std::size_t k = 0; k < rMesh.NumRegions(); ++k) {
        const Region& reg = rMesh.Region(k);
        if (used_regions[k] || reg.mKind != RegionKind::Cell)
            continue;
        const std::vector<std::int64_t> e = radw_entries(reg);
        std::set<std::int64_t> cells(e.begin(), e.end());
        if (cells.empty() || !std::all_of(cells.begin(), cells.end(), written))
            continue;
        candidates.emplace_back(cells.size(), k, std::move(cells));
    }
    std::sort(candidates.begin(), candidates.end(), [](const auto& rA, const auto& rB) {
        return std::tie(std::get<0>(rA), std::get<1>(rA)) <
               std::tie(std::get<0>(rB), std::get<1>(rB));
    });
    for (const auto& [size, k, cells] : candidates) {
        std::vector<std::int64_t> inside;
        std::set<std::int64_t> covered;
        for (const RadwPart& p : parts) {
            const auto it = part_cells.find(p.mId);
            if (it == part_cells.end() || it->second.empty())
                continue;
            if (std::includes(cells.begin(), cells.end(), it->second.begin(), it->second.end())) {
                inside.push_back(p.mId);
                covered.insert(it->second.begin(), it->second.end());
            }
        }
        if (covered != cells)
            continue;
        const std::set<std::int64_t> inside_set(inside.begin(), inside.end());
        std::set<std::int64_t> children;
        for (const std::int64_t p : inside)
            if (part_subset.count(p))
                children.insert(part_subset[p]);
        bool nested = true;
        for (const std::int64_t s : children)
            if (!std::includes(inside_set.begin(), inside_set.end(), subset_parts[s].begin(),
                               subset_parts[s].end()))
                nested = false;
        if (!nested)
            continue;
        const Region& reg = rMesh.Region(k);
        const std::int64_t sid = subset_ids.Take(reg.mTag);
        for (const std::int64_t p : inside)
            part_subset.emplace(p, sid);
        subset_parts[sid] = inside_set;
        subsets.push_back(
            {sid, reg.mName, std::vector<std::int64_t>(children.begin(), children.end())});
        used_regions[k] = true;
    }

    // Element ids, in the order the cards write them.
    std::vector<std::int64_t> elem_id(ncells, 0);
    struct RadwCard {
        std::string mCard;
        std::int64_t mPart;
        std::vector<std::size_t> mCells;
    };
    std::vector<RadwCard> cards;
    std::int64_t next_elem = 1;
    {
        std::size_t g = 0;
        for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
            const std::size_t n = rMesh.Cells(b).NumCells();
            bool open = false;
            for (std::size_t r = 0; r < n; ++r, ++g) {
                if (info[g].mCard.empty())
                    continue;
                if (!open || cards.back().mPart != cell_part[g]) {
                    cards.push_back({info[g].mCard, cell_part[g], {}});
                    open = true;
                }
                cards.back().mCells.push_back(g);
                elem_id[g] = next_elem++;
            }
        }
    }

    // Groups, then surfaces.
    struct RadwGroup {
        std::string mKeyword;
        std::string mSubtype;
        std::int64_t mId;
        std::string mTitle;
        std::vector<std::int64_t> mIds;
    };
    std::map<std::string, RadwIds> group_ids;
    std::vector<RadwGroup> groups;
    struct RadwSurface {
        std::int64_t mId;
        std::string mTitle;
        std::vector<std::array<std::int64_t, 4>> mSegs;
    };
    RadwIds surf_ids;
    std::vector<RadwSurface> surfaces;
    std::size_t dropped_sides = 0;
    for (std::size_t k = 0; k < rMesh.NumRegions(); ++k) {
        if (used_regions[k])
            continue;
        const Region& reg = rMesh.Region(k);
        const std::vector<std::int64_t> e = radw_entries(reg);
        if (reg.mKind == RegionKind::Point) {
            std::set<std::int64_t> ids;
            for (const std::int64_t p : e)
                if (p >= 0 && static_cast<std::size_t>(p) < npts)
                    ids.insert(p + 1);
            const std::int64_t gid = group_ids["GRNOD"].Take(reg.mTag);
            groups.push_back({"GRNOD", "NODE", gid, reg.mName,
                              std::vector<std::int64_t>(ids.begin(), ids.end())});
        } else if (reg.mKind == RegionKind::Cell) {
            std::vector<std::pair<std::string, std::vector<std::int64_t>>> by_family;
            const std::set<std::int64_t> cells(e.begin(), e.end());
            for (const std::int64_t c : cells) {
                if (!written(c))
                    continue;
                const std::string fam = family(static_cast<std::size_t>(c));
                auto it = std::find_if(by_family.begin(), by_family.end(),
                                       [&](const auto& rF) { return rF.first == fam; });
                if (it == by_family.end()) {
                    by_family.emplace_back(fam, std::vector<std::int64_t>{});
                    it = by_family.end() - 1;
                }
                it->second.push_back(elem_id[static_cast<std::size_t>(c)]);
            }
            if (by_family.empty())
                by_family.emplace_back("BRIC", std::vector<std::int64_t>{});
            for (auto& [fam, ids] : by_family) {
                const std::string keyword = radw_group_keyword(fam);
                const std::int64_t gid = group_ids[keyword].Take(reg.mTag);
                groups.push_back({keyword, fam, gid, reg.mName, std::move(ids)});
            }
        } else {
            RadwSurface surf;
            for (std::size_t j = 0; j + 1 < e.size(); j += 2) {
                const std::int64_t c = e[j];
                if (!written(c)) {
                    ++dropped_sides;
                    continue;
                }
                const RadwCell& ci = info[static_cast<std::size_t>(c)];
                const std::string fam = family(static_cast<std::size_t>(c));
                std::vector<std::int64_t> nodes;
                if (fam == "SHEL" || fam == "SH3N") {
                    const auto cb = rMesh.Cells(ci.mBlock);
                    const std::size_t k2 = cb.NodesPerCell();
                    for (std::size_t q = 0; q < k2; ++q)
                        nodes.push_back(conn_at(ci.mBlock, ci.mRow * k2 + q));
                } else if (fam == "BRIC") {
                    CellType ftype{};
                    std::vector<std::int64_t> fnodes;
                    if (!detail::facet_nodes(rMesh, c, e[j + 1], ftype, fnodes)) {
                        ++dropped_sides;
                        continue;
                    }
                    const bool tri = cell_type_name(ftype).rfind("triangle", 0) == 0;
                    nodes.assign(fnodes.begin(), fnodes.begin() + (tri ? 3 : 4));
                } else {
                    ++dropped_sides;
                    continue;
                }
                std::array<std::int64_t, 4> seg{};
                for (std::size_t q = 0; q < nodes.size() && q < 4; ++q)
                    seg[q] = nodes[q] + 1;
                if (nodes.size() == 3)
                    seg[3] = seg[2];
                surf.mSegs.push_back(seg);
            }
            surf.mId = surf_ids.Take(reg.mTag);
            surf.mTitle = reg.mName;
            surfaces.push_back(std::move(surf));
        }
    }
    if (dropped_sides) {
        log::warn("Radioss writer: {} side region entries on cells with no face segment dropped",
                  dropped_sides);
        detail::provenance_note("regions-dropped",
                                "a /SURF/SEG segment is a solid face or a shell");
    }

    // Data: only the part, property, material and deck field data are written.
    std::vector<std::pair<std::int64_t, std::vector<double>>> planes;
    std::size_t dropped_data = rMesh.PointDataNames().size();
    for (const std::string& name : rMesh.CellDataNames())
        if (name != "radioss:part" && name != "radioss:property" && name != "radioss:material")
            ++dropped_data;
    const std::string plane_prefix = "radioss:surf_plane:";
    for (const std::string& name : rMesh.FieldDataNames()) {
        if (name == "radioss:version" || name == "radioss:length_scale")
            continue;
        if (name.rfind(plane_prefix, 0) == 0) {
            const NDArray& v = rMesh.FieldData(name);
            const std::string ident = name.substr(plane_prefix.size());
            const bool digits =
                !ident.empty() && std::all_of(ident.begin(), ident.end(),
                                              [](char ch) { return ch >= '0' && ch <= '9'; });
            if (v.Size() == 6 && digits) {
                std::vector<double> values(6);
                for (std::size_t q = 0; q < 6; ++q)
                    values[q] = detail::read_double(v, q);
                planes.emplace_back(std::stoll(ident), std::move(values));
                continue;
            }
        }
        ++dropped_data;
    }
    if (dropped_data) {
        log::warn(
            "Radioss writer: a starter deck holds no data arrays; point, cell and field data "
            "other than the radioss: parts and analytical surfaces dropped");
        detail::provenance_note("data-dropped", "a Radioss starter deck holds no data arrays");
    }

    std::int64_t version = kRadWriteVersion;
    if (rMesh.HasFieldData("radioss:version")) {
        const std::int64_t v = detail::read_int(rMesh.FieldData("radioss:version"), 0);
        if (v >= 2017 && v <= 2026)
            version = v;
    }

    std::string run = fs::path(rPath).stem().string();
    if (run.size() >= 5 && run.compare(run.size() - 5, 5, "_0000") == 0)
        run.resize(run.size() - 5);
    std::vector<std::string> out = {"#RADIOSS STARTER"};
    for (const std::string& line : detail::provenance_lines(detail::SlotTier::Block))
        out.push_back("# " + line);
    // The same input and work units, so the starter converts nothing and the
    // reader reads the coordinates as written.
    std::string units;
    for (const char* u : {"kg", "m", "s"})
        units += std::string(20 - std::string(u).size(), ' ') + u;
    std::string begin_line;
    radw_i10(begin_line, version);
    radw_i10(begin_line, 0);
    out.push_back("/BEGIN");
    out.push_back(radw_title(run.empty() ? "meshio" : run).substr(0, 80));
    out.push_back(begin_line);
    out.push_back(units);
    out.push_back(units);

    if (Stubs) {
        // One stub property per property id, as its parts' cards need it
        // (radw_stub_need). A part whose property already serves a part that
        // needs another stub gets a property of its own; material 0 becomes 1.
        RadwIds prop_ids;
        for (const RadwPart& p : parts)
            if (p.mProp > 0)
                prop_ids.mUsed.insert(p.mProp);
        std::map<std::int64_t, std::pair<std::string, int>> props;
        std::vector<std::int64_t> mats;
        for (RadwPart& p : parts) {
            std::set<std::string> part_cards;
            for (const std::int64_t c : part_cells[p.mId])
                part_cards.insert(info[static_cast<std::size_t>(c)].mCard);
            std::pair<std::string, int> need;
            if (!radw_stub_share(part_cards, need))
                throw WriteError("Radioss writer: part " + std::to_string(p.mId) +
                                 " holds solid, shell or truss elements together, which no one "
                                 "stub property serves");
            if (p.mProp <= 0)
                p.mProp = prop_ids.Take(p.mId);
            const auto it = props.emplace(p.mProp, need).first;
            if (it->second != need) {
                p.mProp = prop_ids.Take();
                props[p.mProp] = need;
            }
            if (p.mMat <= 0)
                p.mMat = 1;
            if (std::find(mats.begin(), mats.end(), p.mMat) == mats.end())
                mats.push_back(p.mMat);
        }
        std::sort(mats.begin(), mats.end());
        for (const std::int64_t mid : mats) {
            std::string a, b;
            radw_f20(a, 1.0);
            radw_f20(a, 0.0);
            radw_f20(b, 1.0);
            radw_f20(b, 0.3);
            out.push_back("/MAT/LAW1/" + std::to_string(mid));
            out.push_back("meshio++ stub material " + std::to_string(mid));
            out.push_back(a);
            out.push_back(b);
        }
        for (const auto& [pr, need] : props) {
            out.push_back("/PROP/" + need.first + "/" + std::to_string(pr));
            out.push_back("meshio++ stub property " + std::to_string(pr));
            if (need.first == "SOLID") {
                std::string l1, l2, l3;
                radw_i10(l1, need.second);
                radw_i10(l1, 0);
                l1.append(10, ' ');
                radw_i10(l1, 0);
                l1.append(10, ' ');
                for (int q = 0; q < 3; ++q)
                    radw_i10(l1, 0);
                radw_f20(l1, 0.0);
                for (int q = 0; q < 5; ++q)
                    radw_f20(l2, 0.0);
                radw_f20(l3, 0.0);
                radw_i10(l3, 0);
                radw_i10(l3, 0);
                out.push_back(l1);
                out.push_back(l2);
                out.push_back(l3);
            } else if (need.first == "SHELL") {
                std::string l1, l2, l3;
                for (int q = 0; q < 3; ++q)
                    radw_i10(l1, 0);
                for (int q = 0; q < 5; ++q)
                    radw_f20(l2, 0.0);
                radw_i10(l3, 1);
                radw_i10(l3, 0);
                radw_f20(l3, 1.0);
                out.push_back(l1);
                out.push_back(l2);
                out.push_back(l3);
            } else {
                std::string l1;
                radw_f20(l1, 1.0);
                radw_f20(l1, 0.0);
                out.push_back(l1);
            }
        }
    }

    for (const RadwPart& p : parts) {
        std::string line;
        radw_i10(line, p.mProp);
        radw_i10(line, p.mMat);
        const auto it = part_subset.find(p.mId);
        radw_i10(line, it == part_subset.end() ? 0 : it->second);
        out.push_back("/PART/" + std::to_string(p.mId));
        out.push_back(radw_title(p.mTitle));
        out.push_back(line);
    }
    for (const RadwSubset& s : subsets) {
        out.push_back("/SUBSET/" + std::to_string(s.mId));
        out.push_back(radw_title(s.mTitle));
        radw_ids_lines(out, s.mChildren);
    }

    out.push_back("/NODE");
    for (std::size_t p = 0; p < npts; ++p) {
        std::string line;
        radw_i10(line, static_cast<std::int64_t>(p + 1));
        for (std::size_t d = 0; d < 3; ++d)
            radw_f20(line, d < pdim ? point_values[p * pdim + d] : 0.0);
        out.push_back(std::move(line));
    }

    const detail::NodeOrder* bric20 = detail::node_order("radioss", "hexahedron20");
    for (const RadwCard& card : cards) {
        out.push_back("/" + card.mCard + "/" + std::to_string(card.mPart));
        for (const std::size_t c : card.mCells) {
            const auto cb = rMesh.Cells(info[c].mBlock);
            const std::size_t k = cb.NodesPerCell();
            std::vector<std::int64_t> nodes(k);
            for (std::size_t q = 0; q < k; ++q)
                nodes[q] = conn_at(info[c].mBlock, info[c].mRow * k + q) + 1;
            if (card.mCard == "BRICK") {
                const auto brick = detail::expand_brick(cb.Type(), nodes.data());
                nodes.assign(brick.begin(), brick.end());
            }
            std::string line;
            radw_i10(line, elem_id[c]);
            if (card.mCard == "TETRA10") {
                out.push_back(std::move(line));
                line.clear();
                for (const std::int64_t v : nodes)
                    radw_i10(line, v);
                out.push_back(std::move(line));
            } else if (card.mCard == "BRIC20") {
                std::vector<std::int64_t> file(20);
                for (std::size_t j = 0; j < 20; ++j)
                    file[j] = nodes[static_cast<std::size_t>(bric20->mFromMeshio[j])];
                for (std::size_t j = 0; j < 8; ++j)
                    radw_i10(line, file[j]);
                out.push_back(std::move(line));
                std::string l2, l3;
                for (std::size_t j = 8; j < 16; ++j)
                    radw_i10(l2, file[j]);
                for (std::size_t j = 16; j < 20; ++j)
                    radw_i10(l3, file[j]);
                out.push_back(std::move(l2));
                out.push_back(std::move(l3));
            } else {
                for (const std::int64_t v : nodes)
                    radw_i10(line, v);
                out.push_back(std::move(line));
            }
        }
    }

    for (const RadwGroup& g : groups) {
        out.push_back("/" + g.mKeyword + "/" + g.mSubtype + "/" + std::to_string(g.mId));
        out.push_back(radw_title(g.mTitle));
        radw_ids_lines(out, g.mIds);
    }
    for (const RadwSurface& s : surfaces) {
        out.push_back("/SURF/SEG/" + std::to_string(s.mId));
        out.push_back(radw_title(s.mTitle));
        for (std::size_t k = 0; k < s.mSegs.size(); ++k) {
            std::string line;
            radw_i10(line, static_cast<std::int64_t>(k + 1));
            for (const std::int64_t v : s.mSegs[k])
                radw_i10(line, v);
            out.push_back(std::move(line));
        }
    }
    std::sort(planes.begin(), planes.end());
    for (const auto& [sid, v] : planes) {
        std::string a, b;
        for (std::size_t q = 0; q < 3; ++q)
            radw_f20(a, v[q]);
        for (std::size_t q = 3; q < 6; ++q)
            radw_f20(b, v[q]);
        out.push_back("/SURF/PLANE/" + std::to_string(surf_ids.Take(sid)));
        out.push_back("PLANE_" + std::to_string(sid));
        out.push_back(std::move(a));
        out.push_back(std::move(b));
    }
    out.push_back("/END");

    auto os = detail::make_classic_ofstream(rPath, std::ios::binary);
    if (!os)
        throw WriteError("Radioss writer: cannot open " + rPath + " for writing");
    std::string text;
    for (const std::string& line : out) {
        text += line;
        text += '\n';
    }
    os.write(text.data(), static_cast<std::streamsize>(text.size()));
    if (!os)
        throw WriteError("Radioss writer: failed writing " + rPath);
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/formats/radioss.cpp =====
// ===== begin src/cpp/src/formats/radioss_anim.cpp =====
#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <ios>
#include <iterator>
#include <limits>
#include <memory>
#include <map>
#include <set>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr std::int32_t kAnimMagic = 0x542C;
/// Region names of the time-history items: the file's label behind this prefix.
constexpr const char* kAnimThPrefix = "radioss_th:";

// Big-endian reads with a bounds check.
class AnimCursor {
public:
    AnimCursor(std::string_view rData, const std::string& rPath) : mData(rData), mPath(rPath) {}

    std::size_t Remaining() const { return mData.size() - mPos; }

    const char* Take(std::size_t N) {
        if (N > mData.size() - mPos)  // not mPos + N: that wraps for a huge N
            throw ReadError("Radioss animation: '" + mPath + "' is truncated (needs " +
                            std::to_string(N) + " more bytes at offset " + std::to_string(mPos) +
                            " of " + std::to_string(mData.size()) + ")");
        const char* p = mData.data() + mPos;
        mPos += N;
        return p;
    }

    std::vector<std::int64_t> Ints(std::int64_t N) {
        if (N < 0)
            throw ReadError("Radioss animation: '" + mPath + "' has a negative count");
        if (static_cast<std::uint64_t>(N) > (mData.size() - mPos) / 4)
            Take(mData.size() - mPos + 1);  // reports the truncation
        const unsigned char* p =
            reinterpret_cast<const unsigned char*>(Take(4 * static_cast<std::size_t>(N)));
        std::vector<std::int64_t> out(static_cast<std::size_t>(N));
        for (std::size_t k = 0; k < out.size(); ++k) {
            const std::uint32_t v =
                (std::uint32_t(p[4 * k]) << 24) | (std::uint32_t(p[4 * k + 1]) << 16) |
                (std::uint32_t(p[4 * k + 2]) << 8) | std::uint32_t(p[4 * k + 3]);
            out[k] = static_cast<std::int32_t>(v);
        }
        return out;
    }

    std::int64_t Int() { return Ints(1)[0]; }

    std::vector<double> Floats(std::int64_t N) {
        if (N < 0)
            throw ReadError("Radioss animation: '" + mPath + "' has a negative count");
        if (static_cast<std::uint64_t>(N) > (mData.size() - mPos) / 4)
            Take(mData.size() - mPos + 1);  // reports the truncation
        const unsigned char* p =
            reinterpret_cast<const unsigned char*>(Take(4 * static_cast<std::size_t>(N)));
        std::vector<double> out(static_cast<std::size_t>(N));
        for (std::size_t k = 0; k < out.size(); ++k) {
            const std::uint32_t v =
                (std::uint32_t(p[4 * k]) << 24) | (std::uint32_t(p[4 * k + 1]) << 16) |
                (std::uint32_t(p[4 * k + 2]) << 8) | std::uint32_t(p[4 * k + 3]);
            float f;
            std::memcpy(&f, &v, 4);
            out[k] = static_cast<double>(f);
        }
        return out;
    }

    std::vector<bool> Flags(std::int64_t N) {
        const char* p = Take(static_cast<std::size_t>(N < 0 ? 0 : N));
        std::vector<bool> out(static_cast<std::size_t>(N < 0 ? 0 : N));
        for (std::size_t k = 0; k < out.size(); ++k)
            out[k] = p[k] != 0;
        return out;
    }

    std::string Text(std::size_t N) {
        std::string s(Take(N), N);
        const std::size_t nul = s.find('\0');
        if (nul != std::string::npos)
            s.resize(nul);
        const std::size_t b = s.find_first_not_of(" \t\r\n");
        if (b == std::string::npos)
            return {};
        const std::size_t e = s.find_last_not_of(" \t\r\n");
        return s.substr(b, e - b + 1);
    }

    std::vector<std::string> Texts(std::int64_t Count, std::size_t N) {
        std::vector<std::string> out;
        if (Count > 0 && N > 0)  // bounded by the bytes left, as Take() checks
            out.reserve(std::min<std::size_t>(static_cast<std::size_t>(Count), Remaining() / N));
        for (std::int64_t k = 0; k < Count; ++k)
            out.push_back(Text(N));
        return out;
    }

private:
    std::string_view mData;
    const std::string& mPath;
    std::size_t mPos = 0;
};

// One element family (1-D, 2-D, 3-D or SPH) of the file.
struct AnimFamily {
    std::string mKey;
    std::size_t mNodesPer = 0;
    std::vector<std::int64_t> mConn;  // mNodesPer per element
    std::vector<bool> mAlive;
    std::vector<std::int64_t> mPartEnds;
    std::vector<std::string> mPartTexts;
    std::vector<std::pair<std::string, std::vector<double>>> mScalars;
    // name, width (3, 6 or 9), values (width per element)
    std::vector<std::tuple<std::string, std::size_t, std::vector<double>>> mTensors;
    std::vector<double> mMass;
    std::vector<std::int64_t> mIds;
    std::vector<std::vector<std::int64_t>> mHierarchy;  // subset, material, property per part
    bool mHasMass = false, mHasIds = false, mHasHierarchy = false;

    std::size_t Size() const { return mNodesPer ? mConn.size() / mNodesPer : 0; }
};

// The shared tail of the 3-D, 1-D and SPH sections, after their counts and
// connectivity: alive flags, parts, scalars, tensors, then (1-D) the skews,
// masses, ids and the part hierarchy.
void anim_section(AnimCursor& rC, const std::vector<std::int64_t>& rFlags, AnimFamily& rF,
                  std::int64_t NumParts, std::int64_t NumScalars, std::size_t TensorWidth,
                  std::int64_t NumTensors, bool Skews) {
    const std::int64_t n = static_cast<std::int64_t>(rF.Size());
    rF.mAlive = rC.Flags(n);
    rF.mPartEnds = rC.Ints(NumParts);
    rF.mPartTexts = rC.Texts(NumParts, 50);
    if (NumScalars) {
        const std::vector<std::string> names = rC.Texts(NumScalars, 81);
        const std::vector<double> values = rC.Floats(NumScalars * n);
        for (std::size_t k = 0; k < names.size(); ++k)
            rF.mScalars.emplace_back(
                names[k],
                std::vector<double>(values.begin() + static_cast<std::ptrdiff_t>(k) * n,
                                    values.begin() + static_cast<std::ptrdiff_t>(k + 1) * n));
    }
    if (NumTensors) {
        const std::vector<std::string> names = rC.Texts(NumTensors, 81);
        const std::int64_t w = static_cast<std::int64_t>(TensorWidth);
        const std::vector<double> values = rC.Floats(n * w * NumTensors);
        for (std::size_t k = 0; k < names.size(); ++k)
            rF.mTensors.emplace_back(
                names[k], TensorWidth,
                std::vector<double>(values.begin() + static_cast<std::ptrdiff_t>(k) * n * w,
                                    values.begin() + static_cast<std::ptrdiff_t>(k + 1) * n * w));
    }
    if (Skews)
        rC.Ints(n);
    if (rFlags[0] == 1) {
        rF.mMass = rC.Floats(n);
        rF.mHasMass = true;
    }
    if (rFlags[1] == 1) {
        rF.mIds = rC.Ints(n);
        rF.mHasIds = true;
    }
    if (rFlags[4]) {
        for (int k = 0; k < 3; ++k)
            rF.mHierarchy.push_back(rC.Ints(NumParts));
        rF.mHasHierarchy = true;
    }
}

// Per element, part k runs up to (not including) `rEnds[k]`.
template <class Fn>
void anim_for_parts(const AnimFamily& rF, Fn&& rFn) {
    std::int64_t start = 0;
    for (std::size_t k = 0; k < rF.mPartEnds.size(); ++k) {
        const std::int64_t end = std::max(start, rF.mPartEnds[k]);
        rFn(k, start, std::min<std::int64_t>(end, static_cast<std::int64_t>(rF.Size())));
        start = end;
    }
}

}  // namespace

bool is_radioss_anim_filename(const std::string& rPath) {
    const std::string name = std::filesystem::path(rPath).filename().string();
    std::size_t k = name.size();
    while (k > 0 && name[k - 1] >= '0' && name[k - 1] <= '9')
        --k;
    return name.size() - k >= 3 && k >= 2 && name[k - 1] == 'A';
}

Mesh read_radioss_anim(const std::string& rPath) {
    const detail::FileSource data_source =
        detail::open_source(rPath, "Radioss animation: cannot open " + rPath);
    const std::string_view data = data_source.View();
    AnimCursor c(data, rPath);
    const std::int64_t magic = c.Int();
    if (magic != kAnimMagic) {
        std::string hex;
        for (std::uint32_t v = static_cast<std::uint32_t>(magic); v || hex.empty(); v >>= 4)
            hex.insert(hex.begin(), "0123456789abcdef"[v & 0xf]);
        throw ReadError("Radioss animation: '" + rPath + "' has magic 0x" + hex +
                        "; only the current layout (0x542c) is read");
    }
    const double time = c.Floats(1)[0];
    c.Texts(3, 81);  // "Time=", "ModAnim", "Radioss Run="
    const std::vector<std::int64_t> flags = c.Ints(10);
    const std::vector<std::int64_t> counts = c.Ints(8);
    const std::int64_t nn = counts[0], nf = counts[1], np2 = counts[2], nfun = counts[3],
                       nefun = counts[4], nvec = counts[5], nten = counts[6], nskew = counts[7];
    // Every count sizes records of at least one byte per entry, so none can
    // exceed the file; this also keeps the products below inside int64.
    for (const std::int64_t n : counts)
        detail::checked_count(n, data.size(), "Radioss animation", "header");
    c.Take(static_cast<std::size_t>(2 * 6 * std::max<std::int64_t>(nskew, 0)));
    const std::vector<double> coords = c.Floats(3 * nn);

    std::vector<AnimFamily> families;
    AnimFamily two;
    two.mKey = "2d";
    two.mNodesPer = 4;
    two.mConn = c.Ints(4 * nf);
    two.mAlive = c.Flags(nf);
    if (np2) {
        two.mPartEnds = c.Ints(np2);
        two.mPartTexts = c.Texts(np2, 50);
    }
    c.Take(static_cast<std::size_t>(2 * 3 * nn));  // nodal normals
    std::vector<std::pair<std::string, std::vector<double>>> point_scalars;
    if (nfun + nefun) {
        const std::vector<std::string> names = c.Texts(nfun + nefun, 81);
        const std::vector<double> values = c.Floats(nn * nfun);
        for (std::int64_t k = 0; k < nfun; ++k)
            point_scalars.emplace_back(
                names[static_cast<std::size_t>(k)],
                std::vector<double>(values.begin() + k * nn, values.begin() + (k + 1) * nn));
        const std::vector<double> evalues = c.Floats(nf * nefun);
        for (std::int64_t k = 0; k < nefun; ++k)
            two.mScalars.emplace_back(
                names[static_cast<std::size_t>(nfun + k)],
                std::vector<double>(evalues.begin() + k * nf, evalues.begin() + (k + 1) * nf));
    }
    const std::vector<std::string> vnames = c.Texts(nvec, 81);
    const std::vector<double> vvalues = c.Floats(3 * nn * nvec);
    if (nten) {
        const std::vector<std::string> names = c.Texts(nten, 81);
        const std::vector<double> values = c.Floats(nf * 3 * nten);
        for (std::int64_t k = 0; k < nten; ++k)
            two.mTensors.emplace_back(names[static_cast<std::size_t>(k)], 3,
                                      std::vector<double>(values.begin() + k * nf * 3,
                                                          values.begin() + (k + 1) * nf * 3));
    }
    std::vector<double> point_mass;
    if (flags[0] == 1) {
        two.mMass = c.Floats(nf);
        two.mHasMass = true;
        point_mass = c.Floats(nn);
    }
    std::vector<std::int64_t> node_ids;
    if (flags[1]) {
        node_ids = c.Ints(nn);
        two.mIds = c.Ints(nf);
        two.mHasIds = true;
    }
    if (flags[4]) {
        for (int k = 0; k < 3; ++k)
            two.mHierarchy.push_back(c.Ints(np2));
        two.mHasHierarchy = true;
    }

    AnimFamily three, one, sph;
    bool has3 = false, has1 = false, has_sph = false;
    if (flags[2]) {
        const std::vector<std::int64_t> h = c.Ints(4);  // elements, parts, scalars, tensors
        three.mKey = "3d";
        three.mNodesPer = 8;
        three.mConn = c.Ints(8 * h[0]);
        anim_section(c, flags, three, h[1], h[2], 6, h[3], false);
        has3 = true;
    }
    if (flags[3]) {
        const std::vector<std::int64_t> h = c.Ints(5);  // elements, parts, scalars, torsors, skews
        one.mKey = "1d";
        one.mNodesPer = 2;
        one.mConn = c.Ints(2 * h[0]);
        anim_section(c, flags, one, h[1], h[2], 9, h[3], h[4] != 0);
        has1 = true;
    }
    if (flags[4]) {
        const std::int64_t nsub = c.Int();
        for (std::int64_t k = 0; k < nsub; ++k) {
            c.Text(50);
            c.Int();          // parent
            c.Ints(c.Int());  // child subsets
            for (int d = 0; d < 3; ++d)
                c.Ints(c.Int());  // 2-D, 3-D and 1-D parts
        }
        const std::int64_t nmat = c.Int(), nprop = c.Int();
        c.Texts(nmat, 50);
        c.Ints(nmat);
        c.Texts(nprop, 50);
        c.Ints(nprop);
    }
    // Time-history items: per category (nodes, 2-D, 3-D, 1-D elements) the 0-based index of a
    // node or of an element of that family, each with a label.
    std::array<std::vector<std::pair<std::int64_t, std::string>>, 4> th_items;
    if (flags[5]) {
        const std::vector<std::int64_t> th = c.Ints(4);
        for (std::size_t slot = 0; slot < 4; ++slot) {
            const std::vector<std::int64_t> ids = c.Ints(th[slot]);
            const std::vector<std::string> texts = c.Texts(th[slot], 50);
            for (std::size_t k = 0; k < ids.size(); ++k)
                th_items[slot].emplace_back(ids[k], texts[k]);
        }
    }
    if (flags[7]) {
        const std::vector<std::int64_t> h = c.Ints(4);  // elements, parts, scalars, tensors
        sph.mKey = "sph";
        sph.mNodesPer = 1;
        if (h[0]) {
            sph.mConn = c.Ints(h[0]);
            sph.mAlive = c.Flags(h[0]);
        }
        if (h[1]) {
            sph.mPartEnds = c.Ints(h[1]);
            sph.mPartTexts = c.Texts(h[1], 50);
        }
        if (h[2]) {
            const std::vector<std::string> names = c.Texts(h[2], 81);
            const std::vector<double> values = c.Floats(h[2] * h[0]);
            for (std::int64_t k = 0; k < h[2]; ++k)
                sph.mScalars.emplace_back(names[static_cast<std::size_t>(k)],
                                          std::vector<double>(values.begin() + k * h[0],
                                                              values.begin() + (k + 1) * h[0]));
        }
        if (h[3]) {
            const std::vector<std::string> names = c.Texts(h[3], 81);
            const std::vector<double> values = c.Floats(h[0] * h[3] * 6);
            for (std::int64_t k = 0; k < h[3]; ++k)
                sph.mTensors.emplace_back(names[static_cast<std::size_t>(k)], 6,
                                          std::vector<double>(values.begin() + k * h[0] * 6,
                                                              values.begin() + (k + 1) * h[0] * 6));
        }
        if (flags[0] == 1) {
            sph.mMass = c.Floats(h[0]);
            sph.mHasMass = true;
        }
        if (flags[1] == 1) {
            sph.mIds = c.Ints(h[0]);
            sph.mHasIds = true;
        }
        if (flags[4]) {
            for (int k = 0; k < 3; ++k)
                sph.mHierarchy.push_back(c.Ints(h[1]));
            sph.mHasHierarchy = true;
        }
        has_sph = true;
    }
    // The families in file order: 1-D, 2-D, 3-D, SPH.
    if (has1 && one.Size())
        families.push_back(std::move(one));
    if (two.Size())
        families.push_back(std::move(two));
    if (has3 && three.Size())
        families.push_back(std::move(three));
    if (has_sph && sph.Size())
        families.push_back(std::move(sph));

    // Cells: each element's type and nodes, then one block per type.
    struct AnimCell {
        std::size_t mFamily, mElement;
        std::vector<std::int64_t> mNodes;
    };
    std::vector<std::string> block_types;
    std::map<std::string, std::vector<AnimCell>> members;
    std::size_t skipped = 0;
    for (std::size_t fi = 0; fi < families.size(); ++fi) {
        const AnimFamily& fam = families[fi];
        for (std::size_t e = 0; e < fam.Size(); ++e) {
            std::vector<std::int64_t> row(
                fam.mConn.begin() + static_cast<std::ptrdiff_t>(e * fam.mNodesPer),
                fam.mConn.begin() + static_cast<std::ptrdiff_t>((e + 1) * fam.mNodesPer));
            for (std::int64_t v : row)
                if (v < 0 || v >= nn)
                    throw ReadError("Radioss animation: '" + rPath + "' names a node out of range");
            std::string type;
            if (fam.mKey == "1d") {
                type = "line";
            } else if (fam.mKey == "sph") {
                type = "vertex";
            } else if (fam.mKey == "2d") {
                std::vector<std::int64_t> distinct;
                for (std::int64_t v : row)
                    if (std::find(distinct.begin(), distinct.end(), v) == distinct.end())
                        distinct.push_back(v);
                row = distinct;
                type = row.size() == 4 ? "quad" : (row.size() == 3 ? "triangle" : "");
            } else {
                std::array<std::int64_t, 8> a{};
                std::copy(row.begin(), row.end(), a.begin());
                detail::CollapsedBrick b = detail::collapse_brick(a);
                type = b.mType;
                row = std::move(b.mNodes);
            }
            if (type.empty()) {
                ++skipped;
                continue;
            }
            auto [it, fresh] = members.emplace(type, std::vector<AnimCell>{});
            if (fresh)
                block_types.push_back(type);
            it->second.push_back({fi, e, std::move(row)});
        }
    }
    if (skipped)
        log::warn("Radioss animation: {} degenerate facet(s) skipped", skipped);

    Mesh mesh;
    NDArray points(DType::Float64, {static_cast<std::size_t>(nn), 3});
    std::copy(coords.begin(), coords.end(), points.As<double>());
    mesh.AssignPoints(std::move(points));
    std::map<std::pair<std::size_t, std::size_t>, std::int64_t> cell_of;
    std::vector<int> cell_dim;
    for (const std::string& type : block_types) {
        const std::vector<AnimCell>& list = members[type];
        const std::size_t k = list.front().mNodes.size();
        NDArray conn(DType::Int64, {list.size(), k});
        for (std::size_t r = 0; r < list.size(); ++r) {
            std::copy(list[r].mNodes.begin(), list[r].mNodes.end(),
                      conn.As<std::int64_t>() + r * k);
            cell_of[{list[r].mFamily, list[r].mElement}] =
                static_cast<std::int64_t>(cell_dim.size());
            cell_dim.push_back(type == "vertex"                         ? 0
                               : type == "line"                         ? 1
                               : (type == "triangle" || type == "quad") ? 2
                                                                        : 3);
        }
        mesh.AddCellBlock(type, std::move(conn));
    }
    mesh.AddFieldData("meshio:time", [&] {
        NDArray a(DType::Float64, {1});
        a.As<double>()[0] = time;
        return a;
    }());

    auto vec = [](const std::vector<double>& rV, std::vector<std::size_t> Shape) {
        NDArray a(DType::Float64, std::move(Shape));
        std::copy(rV.begin(), rV.end(), a.As<double>());
        return a;
    };
    const std::size_t n_points = static_cast<std::size_t>(nn);
    for (const auto& [name, values] : point_scalars)
        mesh.AddPointData(name, vec(values, {n_points}));
    for (std::size_t k = 0; k < vnames.size(); ++k)
        mesh.AddPointData(
            vnames[k],
            vec(std::vector<double>(
                    vvalues.begin() + static_cast<std::ptrdiff_t>(k * 3 * n_points),
                    vvalues.begin() + static_cast<std::ptrdiff_t>((k + 1) * 3 * n_points)),
                {n_points, 3}));
    if (flags[1]) {
        NDArray a(DType::Int64, {n_points});
        std::copy(node_ids.begin(), node_ids.end(), a.As<std::int64_t>());
        mesh.AddPointData("radioss:node_id", std::move(a));
    }
    if (flags[0] == 1)
        mesh.AddPointData("radioss:mass", vec(point_mass, {n_points}));
    // The time-history items become regions named after their label: a point region for the
    // nodes, cell regions for the elements (a label can name elements of several families).
    const auto add_th_regions = [&]() {
        const auto label = [](const std::string& rText) {
            const std::size_t b = rText.find_first_not_of(" \t");
            return std::string(kAnimThPrefix) +
                   (b == std::string::npos
                        ? std::string()
                        : rText.substr(b, rText.find_last_not_of(" \t") - b + 1));
        };
        std::map<std::string, std::set<std::int64_t>> nodes, cells;
        std::vector<std::string> node_order, cell_order;
        for (const auto& [index, text] : th_items[0]) {
            if (index < 0 || index >= nn)
                continue;
            const std::string name = label(text);
            if (nodes.try_emplace(name).second)
                node_order.push_back(name);
            nodes[name].insert(index);
        }
        static constexpr const char* kKeys[3] = {"2d", "3d", "1d"};
        for (std::size_t slot = 1; slot < 4; ++slot) {
            for (std::size_t fi = 0; fi < families.size(); ++fi) {
                if (families[fi].mKey != kKeys[slot - 1])
                    continue;
                for (const auto& [index, text] : th_items[slot]) {
                    const auto c = cell_of.find({fi, static_cast<std::size_t>(index)});
                    if (index < 0 || c == cell_of.end())
                        continue;
                    const std::string name = label(text);
                    if (cells.try_emplace(name).second)
                        cell_order.push_back(name);
                    cells[name].insert(c->second);
                }
            }
        }
        const auto region = [&](const std::string& rName, RegionKind Kind,
                                const std::set<std::int64_t>& rIds, int Dim) {
            NDArray a(DType::Int64, {rIds.size()});
            std::copy(rIds.begin(), rIds.end(), a.As<std::int64_t>());
            mesh.AddRegion(Region(rName, Kind, Dim, -1, std::move(a)));
        };
        for (const std::string& name : node_order)
            region(name, RegionKind::Point, nodes[name], -1);
        for (const std::string& name : cell_order) {
            int dim = -1;
            for (const std::int64_t c : cells[name])
                dim = std::max(dim, cell_dim[static_cast<std::size_t>(c)]);
            region(name, RegionKind::Cell, cells[name], dim);
        }
    };
    if (block_types.empty()) {
        add_th_regions();
        return mesh;
    }

    // One array per block from `rGet(family, element, out)`.
    auto per_block = [&](std::size_t Width, double Fill, DType Type, auto&& rGet) {
        std::vector<NDArray> out;
        for (const std::string& type : block_types) {
            const std::vector<AnimCell>& list = members[type];
            const std::size_t w = Width ? Width : 1;
            NDArray a(Type, Width ? std::vector<std::size_t>{list.size(), Width}
                                  : std::vector<std::size_t>{list.size()});
            std::vector<double> row(w);
            for (std::size_t r = 0; r < list.size(); ++r) {
                std::fill(row.begin(), row.end(), Fill);
                rGet(list[r].mFamily, list[r].mElement, row.data());
                for (std::size_t j = 0; j < w; ++j) {
                    if (Type == DType::Float64)
                        a.As<double>()[r * w + j] = row[j];
                    else if (Type == DType::Int8)
                        a.As<std::int8_t>()[r * w + j] = static_cast<std::int8_t>(row[j]);
                    else
                        a.As<std::int64_t>()[r * w + j] = static_cast<std::int64_t>(row[j]);
                }
            }
            out.push_back(std::move(a));
        }
        return out;
    };

    // Per family and element: the part id, and the part's hierarchy values.
    std::vector<std::vector<std::int64_t>> part_id(families.size());
    std::vector<std::vector<std::array<std::int64_t, 2>>> part_matprop(families.size());
    struct AnimPart {
        std::string mName;
        std::int64_t mId;
        std::size_t mFamily;
        std::int64_t mStart, mEnd;
    };
    std::vector<AnimPart> parts;
    for (std::size_t fi = 0; fi < families.size(); ++fi) {
        const AnimFamily& fam = families[fi];
        part_id[fi].assign(fam.Size(), 0);
        part_matprop[fi].assign(fam.Size(), {0, 0});
        anim_for_parts(fam, [&](std::size_t k, std::int64_t b, std::int64_t e) {
            const std::string& text = fam.mPartTexts[k];
            const std::size_t colon = text.find(':');
            std::int64_t pid = 0;
            try {
                pid = std::stoll(text.substr(0, colon));
            } catch (...) {
                pid = 0;
            }
            std::string name = colon == std::string::npos ? text : text.substr(colon + 1);
            const std::size_t nb = name.find_first_not_of(" \t");
            name = nb == std::string::npos ? std::string()
                                           : name.substr(nb, name.find_last_not_of(" \t") - nb + 1);
            for (std::int64_t i = b; i < e; ++i) {
                part_id[fi][static_cast<std::size_t>(i)] = pid;
                if (fam.mHasHierarchy)
                    part_matprop[fi][static_cast<std::size_t>(i)] = {fam.mHierarchy[1][k],
                                                                     fam.mHierarchy[2][k]};
            }
            parts.push_back({name, pid, fi, b, e});
        });
    }
    mesh.AddCellData("radioss:part",
                     per_block(0, 0.0, DType::Int64, [&](std::size_t f, std::size_t e, double* p) {
                         *p = static_cast<double>(part_id[f][e]);
                     }));
    // A deleted (eroded) element's flag is 0; any other byte is alive (the
    // facets write 0xFF, bricks and beams 1).
    mesh.AddCellData("radioss:alive",
                     per_block(0, 0.0, DType::Int8, [&](std::size_t f, std::size_t e, double* p) {
                         *p = families[f].mAlive[e] ? 1.0 : 0.0;
                     }));
    auto all = [&](bool AnimFamily::* pMember) {
        for (const AnimFamily& fam : families)
            if (!(fam.*pMember))
                return false;
        return true;
    };
    if (all(&AnimFamily::mHasIds))
        mesh.AddCellData(
            "radioss:element_id",
            per_block(0, 0.0, DType::Int64, [&](std::size_t f, std::size_t e, double* p) {
                *p = static_cast<double>(families[f].mIds[e]);
            }));
    if (all(&AnimFamily::mHasMass))
        mesh.AddCellData("radioss:mass", per_block(0, 0.0, DType::Float64,
                                                   [&](std::size_t f, std::size_t e, double* p) {
                                                       *p = families[f].mMass[e];
                                                   }));
    if (all(&AnimFamily::mHasHierarchy)) {
        mesh.AddCellData(
            "radioss:material",
            per_block(0, 0.0, DType::Int64, [&](std::size_t f, std::size_t e, double* p) {
                *p = static_cast<double>(part_matprop[f][e][0]);
            }));
        mesh.AddCellData(
            "radioss:property",
            per_block(0, 0.0, DType::Int64, [&](std::size_t f, std::size_t e, double* p) {
                *p = static_cast<double>(part_matprop[f][e][1]);
            }));
    }

    // Element results: the union of the families' names, NaN where a family has
    // none; tensors as xx yy zz xy yz zx (a 2-D one's out-of-plane parts NaN),
    // 1-D force/moment sets with their nine components.
    const double nan = std::numeric_limits<double>::quiet_NaN();
    std::map<std::string, std::map<std::size_t, const std::vector<double>*>> scalars;
    std::map<std::string, std::map<std::size_t, std::pair<std::size_t, const std::vector<double>*>>>
        tensors;
    for (std::size_t fi = 0; fi < families.size(); ++fi) {
        for (const auto& [name, values] : families[fi].mScalars)
            scalars[name][fi] = &values;
        for (const auto& [name, width, values] : families[fi].mTensors)
            tensors[name][fi] = {width, &values};
    }
    for (const auto& [name, by_family] : scalars)
        mesh.AddCellData(
            name, per_block(0, nan, DType::Float64, [&](std::size_t f, std::size_t e, double* p) {
                const auto it = by_family.find(f);
                if (it != by_family.end())
                    *p = (*it->second)[e];
            }));
    for (const auto& [name, by_family] : tensors) {
        bool nine = false, other = false;
        for (const auto& [f, wv] : by_family)
            (wv.first == 9 ? nine : other) = true;
        if (nine && other)
            throw ReadError("Radioss animation: '" + rPath +
                            "' names both a 1-D force set and a tensor '" + name + "'");
        const std::size_t width = nine ? 9 : 6;
        mesh.AddCellData(name, per_block(width, nan, DType::Float64,
                                         [&](std::size_t f, std::size_t e, double* p) {
                                             const auto it = by_family.find(f);
                                             if (it == by_family.end())
                                                 return;
                                             const std::size_t w = it->second.first;
                                             const double* v = it->second.second->data() + e * w;
                                             if (w == 3) {  // xx yy xy
                                                 p[0] = v[0];
                                                 p[1] = v[1];
                                                 p[3] = v[2];
                                             } else {
                                                 std::copy(v, v + w, p);
                                             }
                                         }));
    }

    // Parts -> cell regions (a part id can name a 1-D and a 2-D part).
    std::map<std::pair<std::string, std::int64_t>, std::vector<std::int64_t>> regions;
    std::vector<std::pair<std::string, std::int64_t>> order;
    for (const AnimPart& p : parts) {
        const std::pair<std::string, std::int64_t> key{
            p.mName.empty() ? "Part " + std::to_string(p.mId) : p.mName, p.mId};
        auto [it, fresh] = regions.emplace(key, std::vector<std::int64_t>{});
        if (fresh)
            order.push_back(key);
        for (std::int64_t i = p.mStart; i < p.mEnd; ++i) {
            const auto c = cell_of.find({p.mFamily, static_cast<std::size_t>(i)});
            if (c != cell_of.end())
                it->second.push_back(c->second);
        }
    }
    for (const auto& key : order) {
        std::vector<std::int64_t>& ids = regions[key];
        std::sort(ids.begin(), ids.end());
        int dim = -1;
        for (std::int64_t c : ids)
            dim = std::max(dim, cell_dim[static_cast<std::size_t>(c)]);
        NDArray a(DType::Int64, {ids.size()});
        std::copy(ids.begin(), ids.end(), a.As<std::int64_t>());
        mesh.AddRegion(Region(key.first, RegionKind::Cell, dim, key.second, std::move(a)));
    }
    add_th_regions();
    return mesh;
}

MeshMetadata read_radioss_anim_metadata(const std::string& rPath, const ReadOptions& /*rOpts*/) {
    const Mesh mesh = read_radioss_anim(rPath);
    MeshMetadata meta = metadata_from_mesh(mesh);
    meta.mFellBackToFullRead = true;
    meta.mFormat = "radioss_anim";
    meta.mTimeValues = {mesh.FieldData("meshio:time").As<double>()[0]};
    return meta;
}


// ---------------------------------------------------------------------------
// The writer: the reader's inverse. One mesh is one state; a series is one file
// per step. The Python twin (`radioss_anim/_write.py`) writes the same bytes.
// ---------------------------------------------------------------------------
namespace {

/// Big-endian output buffer.
class AwOut {
public:
    void Ints(const std::vector<std::int64_t>& rValues) {
        for (const std::int64_t v : rValues) {
            const std::uint32_t u = static_cast<std::uint32_t>(static_cast<std::int32_t>(v));
            Be32(u);
        }
    }
    void Floats(const std::vector<double>& rValues) {
        for (const double v : rValues)
            Float(v);
    }
    void Float(double Value) {
        const float f = static_cast<float>(Value);
        std::uint32_t u;
        std::memcpy(&u, &f, 4);
        Be32(u);
    }
    void Be32(std::uint32_t U) {
        mBytes.push_back(static_cast<char>(U >> 24));
        mBytes.push_back(static_cast<char>(U >> 16));
        mBytes.push_back(static_cast<char>(U >> 8));
        mBytes.push_back(static_cast<char>(U));
    }
    void Text(const std::string& rText, std::size_t Width) {
        const std::string cut = rText.substr(0, Width - 1);
        mBytes += cut;
        mBytes.append(Width - cut.size(), '\0');
    }
    void Bytes(const std::vector<std::uint8_t>& rValues) {
        mBytes.append(reinterpret_cast<const char*>(rValues.data()), rValues.size());
    }
    void Zeros(std::size_t N) { mBytes.append(N, '\0'); }
    void Append(const AwOut& rOther) { mBytes += rOther.mBytes; }
    const std::string& Data() const { return mBytes; }

private:
    std::string mBytes;
};

struct AwFamily {
    std::vector<std::size_t> mIndex;                // global cell numbers, ordered by part
    std::vector<std::vector<std::int64_t>> mRows;  // file node rows
    std::vector<std::int64_t> mParts;               // part id per element
    std::size_t Size() const { return mIndex.size(); }
};

/// A cell array over all blocks (block-major) as doubles, with its width.
struct AwColumn {
    std::string mName;
    std::vector<double> mValues;
    std::size_t mWidth = 1;
};

enum AwKey : std::size_t { kAw2d = 0, kAw3d = 1, kAw1d = 2, kAwSph = 3 };

std::string aw_pad_id(std::int64_t Id) {
    std::string s = std::to_string(Id);
    if (s.size() < 9)
        s.insert(0, 9 - s.size(), ' ');
    return s;
}

std::vector<double> aw_values(const NDArray& rArray) {
    const detail::DoubleView view(rArray);
    return std::vector<double>(view.Data(), view.Data() + rArray.Size());
}

std::vector<std::int64_t> aw_int_values(const NDArray& rArray) {
    const detail::Int64View view(rArray);
    return std::vector<std::int64_t>(view.Data(), view.Data() + rArray.Size());
}

/// The block-major cell array `rName` flattened, or false.
bool aw_concat(const Mesh& rMesh, const std::string& rName, std::vector<double>& rOut) {
    if (!rMesh.HasCellData(rName))
        return false;
    rOut.clear();
    for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
        const std::vector<double> v = aw_values(rMesh.CellData(rName, b));
        rOut.insert(rOut.end(), v.begin(), v.end());
    }
    return true;
}

bool aw_concat_int(const Mesh& rMesh, const std::string& rName, std::vector<std::int64_t>& rOut) {
    if (!rMesh.HasCellData(rName))
        return false;
    rOut.clear();
    for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
        const std::vector<std::int64_t> v = aw_int_values(rMesh.CellData(rName, b));
        rOut.insert(rOut.end(), v.begin(), v.end());
    }
    return true;
}

int aw_family_of(const std::string& rType) {
    if (rType == "vertex")
        return kAwSph;
    if (rType == "line")
        return kAw1d;
    if (rType == "triangle" || rType == "quad")
        return kAw2d;
    if (rType == "tetra" || rType == "pyramid" || rType == "wedge" || rType == "hexahedron")
        return kAw3d;
    return -1;
}

bool aw_special(const std::string& rName) {
    return rName == "radioss:part" || rName == "radioss:alive" || rName == "radioss:element_id" ||
           rName == "radioss:mass" || rName == "radioss:material" || rName == "radioss:property";
}

double aw_time_of(const Mesh& rMesh) {
    if (!rMesh.HasFieldData(kSequenceTimeKey))
        return 0.0;
    const NDArray& a = rMesh.FieldData(kSequenceTimeKey);
    return a.Size() == 0 ? 0.0 : detail::DoubleView(a).Data()[0];
}

std::string aw_state_bytes(const Mesh& rMesh, double Time) {
    const std::size_t nn = rMesh.NumPoints();
    std::vector<double> points(nn * 3, 0.0);
    {
        const NDArray& pts = rMesh.Points();
        const detail::DoubleView view(pts);
        const std::size_t width = nn == 0 ? 3 : pts.Size() / nn;
        for (std::size_t i = 0; i < nn; ++i)
            for (std::size_t k = 0; k < 3 && k < width; ++k)
                points[i * 3 + k] = view.Data()[i * width + k];
    }
    // The element families.
    std::array<AwFamily, 4> fam;
    std::map<std::string, std::size_t> skipped;
    std::size_t ncells = 0;
    for (std::size_t b = 0; b < rMesh.NumCellBlocks(); ++b) {
        const auto cb = rMesh.Cells(b);
        const std::size_t count = cb.NumCells();
        const int key = aw_family_of(cb.Type());
        if (key < 0) {
            if (count > 0)
                skipped[cb.Type()] += count;
        } else {
            const detail::Int64View conn(cb.Conn());
            const std::size_t w = cb.NodesPerCell();
            AwFamily& f = fam[static_cast<std::size_t>(key)];
            for (std::size_t r = 0; r < count; ++r) {
                const std::int64_t* row = conn.Data() + r * w;
                for (std::size_t k = 0; k < w; ++k)
                    if (row[k] < 0 || static_cast<std::size_t>(row[k]) >= nn)
                        throw WriteError("Radioss animation: a '" + cb.Type() +
                                         "' cell refers to a point the mesh does not have");
                f.mIndex.push_back(ncells + r);
                if (key == kAwSph) {
                    f.mRows.push_back({row[0]});
                } else if (key == kAw2d) {
                    std::vector<std::int64_t> v(row, row + w);
                    if (w == 3)
                        v.push_back(row[2]);
                    f.mRows.push_back(std::move(v));
                } else if (key == kAw3d) {
                    const auto brick = detail::expand_brick(cb.Type(), row);
                    f.mRows.emplace_back(brick.begin(), brick.end());
                } else {
                    f.mRows.push_back({row[0], row[1]});
                }
            }
        }
        ncells += count;
    }
    for (const auto& [type, count] : skipped)
        log::warn("Radioss animation: {} '{}' cell(s) are not written", count, type);

    // Per-cell attributes.
    std::vector<std::int64_t> part_arr, eids, emat, eprop;
    std::vector<double> alive_d, emass;
    const bool have_part = aw_concat_int(rMesh, "radioss:part", part_arr);
    const bool have_alive = aw_concat(rMesh, "radioss:alive", alive_d);
    const bool have_eids = aw_concat_int(rMesh, "radioss:element_id", eids);
    const bool have_emass = aw_concat(rMesh, "radioss:mass", emass);
    const bool have_emat = aw_concat_int(rMesh, "radioss:material", emat);
    const bool have_eprop = aw_concat_int(rMesh, "radioss:property", eprop);
    std::vector<std::int64_t> node_ids;
    std::vector<double> nmass;
    const bool have_nids = rMesh.HasPointData("radioss:node_id");
    const bool have_nmass = rMesh.HasPointData("radioss:mass");
    if (have_nids)
        node_ids = aw_int_values(rMesh.PointData("radioss:node_id"));
    if (have_nmass)
        nmass = aw_values(rMesh.PointData("radioss:mass"));

    // Parts: radioss:part, else the cell regions, else part 1.
    std::vector<std::int64_t> region_pid(ncells, -1);
    std::map<std::int64_t, std::string> names_by_pid;
    bool have_regions = false;
    {
        std::size_t k = 0;
        for (std::size_t i = 0; i < rMesh.NumRegions(); ++i) {
            const auto& reg = rMesh.Region(i);
            if (reg.mKind != RegionKind::Cell ||
                reg.mName.rfind(kAnimThPrefix, 0) == 0)  // time-history items are not parts
                continue;
            have_regions = true;
            const std::int64_t pid = reg.mTag >= 0 ? reg.mTag : static_cast<std::int64_t>(k + 1);
            ++k;
            names_by_pid.emplace(pid, reg.mName);
            if (!have_part) {
                const detail::Int64View entries(reg.mEntries);
                for (std::size_t e = 0; e < reg.mEntries.Size(); ++e) {
                    const std::int64_t c = entries.Data()[e];
                    if (c >= 0 && static_cast<std::size_t>(c) < ncells &&
                        region_pid[static_cast<std::size_t>(c)] < 0)
                        region_pid[static_cast<std::size_t>(c)] = pid;
                }
            }
        }
    }
    auto pid_of = [&](std::size_t c) -> std::int64_t {
        if (have_part)
            return part_arr[c];
        if (have_regions && region_pid[c] >= 0)
            return region_pid[c];
        return 1;
    };
    for (AwFamily& f : fam) {
        std::vector<std::size_t> order(f.Size());
        for (std::size_t k = 0; k < order.size(); ++k)
            order[k] = k;
        std::stable_sort(order.begin(), order.end(), [&](std::size_t a, std::size_t b) {
            return pid_of(f.mIndex[a]) < pid_of(f.mIndex[b]);
        });
        AwFamily sorted;
        for (const std::size_t k : order) {
            sorted.mIndex.push_back(f.mIndex[k]);
            sorted.mRows.push_back(std::move(f.mRows[k]));
            sorted.mParts.push_back(pid_of(f.mIndex[k]));
        }
        f = std::move(sorted);
    }

    // Time-history items: each entry of a `radioss_th:<label>` region, as the index of a node or
    // of an element in its family (the order the sections above were just sorted into).
    std::array<std::vector<std::pair<std::int64_t, std::string>>, 4> th_items;
    {
        std::map<std::size_t, std::pair<std::size_t, std::size_t>> position;  // cell -> family, row
        for (std::size_t key = 0; key < fam.size(); ++key)
            for (std::size_t k = 0; k < fam[key].Size(); ++k)
                position[fam[key].mIndex[k]] = {key, k};
        const std::string prefix(kAnimThPrefix);
        for (std::size_t i = 0; i < rMesh.NumRegions(); ++i) {
            const auto& reg = rMesh.Region(i);
            if (reg.mName.rfind(prefix, 0) != 0)
                continue;
            const std::string label = reg.mName.substr(prefix.size());
            const detail::Int64View entries(reg.mEntries);
            for (std::size_t e = 0; e < reg.mEntries.Size(); ++e) {
                const std::int64_t v = entries.Data()[e];
                if (reg.mKind == RegionKind::Point) {
                    if (v >= 0 && static_cast<std::size_t>(v) < nn)
                        th_items[0].emplace_back(v, label);
                } else if (reg.mKind == RegionKind::Cell) {
                    const auto at = position.find(static_cast<std::size_t>(v));
                    if (v < 0 || at == position.end() || at->second.first == kAwSph)
                        continue;
                    const std::size_t slot = at->second.first == kAw2d   ? 1
                                             : at->second.first == kAw3d ? 2
                                                                         : 3;
                    th_items[slot].emplace_back(static_cast<std::int64_t>(at->second.second),
                                                label);
                }
            }
        }
    }
    bool have_th = false;
    for (const auto& items : th_items)
        have_th = have_th || !items.empty();

    // Nodal and element results.
    std::vector<AwColumn> scalars, vectors, escalars, tensors, forces;
    for (const std::string& name : rMesh.PointDataNames()) {
        if (name == "radioss:node_id" || name == "radioss:mass")
            continue;
        AwColumn col;
        col.mName = name;
        col.mValues = aw_values(rMesh.PointData(name));
        if (nn > 0 && col.mValues.size() == nn)
            scalars.push_back(std::move(col));
        else if (nn > 0 && col.mValues.size() == 3 * nn)
            vectors.push_back(std::move(col));
        else
            log::warn("Radioss animation: point data '{}' is not written", name);
    }
    for (const std::string& name : rMesh.CellDataNames()) {
        if (aw_special(name))
            continue;
        AwColumn col;
        col.mName = name;
        aw_concat(rMesh, name, col.mValues);
        if (ncells == 0 || col.mValues.size() % ncells != 0) {
            log::warn("Radioss animation: cell data '{}' is not written", name);
            continue;
        }
        col.mWidth = col.mValues.size() / ncells;
        if (col.mWidth == 1)
            escalars.push_back(std::move(col));
        else if (col.mWidth == 6)
            tensors.push_back(std::move(col));
        else if (col.mWidth == 9)
            forces.push_back(std::move(col));
        else
            log::warn("Radioss animation: cell data '{}' is not written", name);
    }

    const bool have_mass = have_emass || have_nmass;
    const bool have_ids = have_eids || have_nids;
    const bool have_hier = have_emat || have_eprop;
    const std::vector<std::int64_t> flags = {have_mass ? 1 : 0,
                                             have_ids ? 1 : 0,
                                             fam[kAw3d].Size() ? 1 : 0,
                                             fam[kAw1d].Size() ? 1 : 0,
                                             have_hier ? 1 : 0,
                                             have_th ? 1 : 0,
                                             0,
                                             fam[kAwSph].Size() ? 1 : 0,
                                             0,
                                             0};

    struct PartTable {
        std::vector<std::int64_t> mEnds, mMats, mProps;
        std::vector<std::string> mTexts;
    };
    auto part_table = [&](const AwFamily& f) {
        PartTable t;
        for (std::size_t k = 0; k < f.mParts.size(); ++k) {
            if (k + 1 != f.mParts.size() && f.mParts[k + 1] == f.mParts[k])
                continue;
            const std::int64_t pid = f.mParts[k];
            t.mEnds.push_back(static_cast<std::int64_t>(k + 1));
            const auto name = names_by_pid.find(pid);
            t.mTexts.push_back(aw_pad_id(pid) + ":" +
                               (name != names_by_pid.end() ? name->second
                                                           : "Part " + std::to_string(pid)));
            const std::size_t c = f.mIndex[k];
            t.mMats.push_back(have_emat ? emat[c] : 0);
            t.mProps.push_back(have_eprop ? eprop[c] : 0);
        }
        return t;
    };
    auto alive_bytes = [&](const AwFamily& f, bool Facets) {
        std::vector<std::uint8_t> a;
        for (const std::size_t c : f.mIndex) {
            const bool on = have_alive ? alive_d[c] != 0.0 : true;
            a.push_back(on ? (Facets ? 0xFF : 1) : 0);
        }
        return a;
    };
    auto masses_of = [&](const AwFamily& f) {
        std::vector<double> m;
        for (const std::size_t c : f.mIndex)
            m.push_back(have_emass ? emass[c] : 0.0);
        return m;
    };
    auto ids_of = [&](const AwFamily& f) {
        std::vector<std::int64_t> v;
        for (const std::size_t c : f.mIndex)
            v.push_back(have_eids ? eids[c] : static_cast<std::int64_t>(c + 1));
        return v;
    };
    auto rows_flat = [](const AwFamily& f) {
        std::vector<std::int64_t> v;
        for (const auto& r : f.mRows)
            v.insert(v.end(), r.begin(), r.end());
        return v;
    };
    // `width` columns of `rCol` for each element of a family.
    auto gather = [&](const AwColumn& rCol, const AwFamily& f, const std::vector<int>& rCols) {
        std::vector<double> v;
        for (const std::size_t c : f.mIndex)
            for (const int k : rCols)
                v.push_back(rCol.mValues[c * rCol.mWidth + static_cast<std::size_t>(k)]);
        return v;
    };

    AwOut out;
    out.Ints({kAnimMagic});
    out.Float(Time);
    for (const char* t : {"Time=", "ModAnim", "Radioss Run="})
        out.Text(t, 81);
    out.Ints(flags);

    // 2-D: the nodes and the facets.
    const AwFamily& f2 = fam[kAw2d];
    const PartTable pt2 = part_table(f2);
    out.Ints({static_cast<std::int64_t>(nn), static_cast<std::int64_t>(f2.Size()),
              static_cast<std::int64_t>(pt2.mEnds.size()),
              static_cast<std::int64_t>(scalars.size()),
              static_cast<std::int64_t>(escalars.size()),
              static_cast<std::int64_t>(vectors.size()),
              static_cast<std::int64_t>(tensors.size()), 0});
    out.Floats(points);
    out.Ints(rows_flat(f2));
    out.Bytes(alive_bytes(f2, true));
    out.Ints(pt2.mEnds);
    for (const std::string& t : pt2.mTexts)
        out.Text(t, 50);
    out.Zeros(2 * 3 * nn);  // nodal normals
    if (!scalars.empty() || !escalars.empty()) {
        for (const AwColumn& c : scalars)
            out.Text(c.mName, 81);
        for (const AwColumn& c : escalars)
            out.Text(c.mName, 81);
        for (const AwColumn& c : scalars)
            out.Floats(c.mValues);
        for (const AwColumn& c : escalars)
            out.Floats(gather(c, f2, {0}));
    }
    for (const AwColumn& c : vectors)
        out.Text(c.mName, 81);
    for (const AwColumn& c : vectors)
        out.Floats(c.mValues);
    if (!tensors.empty()) {
        for (const AwColumn& c : tensors)
            out.Text(c.mName, 81);
        for (const AwColumn& c : tensors)
            out.Floats(gather(c, f2, {0, 1, 3}));
    }
    if (flags[0]) {
        out.Floats(masses_of(f2));
        std::vector<double> pm(nn, 0.0);
        if (have_nmass)
            for (std::size_t i = 0; i < nn && i < nmass.size(); ++i)
                pm[i] = nmass[i];
        out.Floats(pm);
    }
    if (flags[1]) {
        std::vector<std::int64_t> nid(nn);
        for (std::size_t i = 0; i < nn; ++i)
            nid[i] = have_nids ? node_ids[i] : static_cast<std::int64_t>(i + 1);
        out.Ints(nid);
        out.Ints(ids_of(f2));
    }
    if (flags[4]) {
        out.Ints(std::vector<std::int64_t>(pt2.mEnds.size(), 1));
        out.Ints(pt2.mMats);
        out.Ints(pt2.mProps);
    }

    std::array<std::size_t, 4> part_counts = {pt2.mEnds.size(), 0, 0, 0};
    // The 3-D, 1-D and SPH sections share a tail.
    auto section = [&](const AwFamily& f, const std::vector<std::int64_t>& rCounts,
                       const std::vector<AwColumn>& rScalars,
                       const std::vector<AwColumn>& rTensors, bool Facets, std::size_t Slot) {
        const PartTable pt = part_table(f);
        part_counts[Slot] = pt.mEnds.size();
        std::vector<std::int64_t> counts = rCounts;
        counts[1] = static_cast<std::int64_t>(pt.mEnds.size());
        out.Ints(counts);
        out.Ints(rows_flat(f));
        out.Bytes(alive_bytes(f, Facets));
        out.Ints(pt.mEnds);
        for (const std::string& t : pt.mTexts)
            out.Text(t, 50);
        if (!rScalars.empty()) {
            for (const AwColumn& c : rScalars)
                out.Text(c.mName, 81);
            for (const AwColumn& c : rScalars)
                out.Floats(gather(c, f, {0}));
        }
        if (!rTensors.empty()) {
            for (const AwColumn& c : rTensors)
                out.Text(c.mName, 81);
            std::vector<int> all(rTensors.front().mWidth);
            for (std::size_t k = 0; k < all.size(); ++k)
                all[k] = static_cast<int>(k);
            for (const AwColumn& c : rTensors)
                out.Floats(gather(c, f, all));
        }
        if (flags[0])
            out.Floats(masses_of(f));
        if (flags[1])
            out.Ints(ids_of(f));
        if (flags[4]) {
            out.Ints(std::vector<std::int64_t>(pt.mEnds.size(), 1));
            out.Ints(pt.mMats);
            out.Ints(pt.mProps);
        }
    };
    const AwFamily& f3 = fam[kAw3d];
    if (flags[2])
        section(f3,
                {static_cast<std::int64_t>(f3.Size()), 0,
                 static_cast<std::int64_t>(escalars.size()),
                 static_cast<std::int64_t>(tensors.size())},
                escalars, tensors, false, kAw3d);
    const AwFamily& f1 = fam[kAw1d];
    if (flags[3])
        section(f1,
                {static_cast<std::int64_t>(f1.Size()), 0,
                 static_cast<std::int64_t>(escalars.size()),
                 static_cast<std::int64_t>(forces.size()), 0},
                escalars, forces, false, kAw1d);
    if (flags[4]) {
        // One subset holding every part, then the material and property tables.
        out.Ints({1});
        out.Text("model", 50);
        out.Ints({0, 0});
        for (const std::size_t slot : {static_cast<std::size_t>(kAw2d), static_cast<std::size_t>(kAw3d),
                                       static_cast<std::size_t>(kAw1d)}) {
            std::vector<std::int64_t> idx;
            for (std::size_t k = 0; k < part_counts[slot]; ++k)
                idx.push_back(static_cast<std::int64_t>(k));
            out.Ints({static_cast<std::int64_t>(idx.size())});
            out.Ints(idx);
        }
        std::set<std::int64_t> mats, props;
        for (const std::size_t slot : {static_cast<std::size_t>(kAw2d), static_cast<std::size_t>(kAw3d),
                                       static_cast<std::size_t>(kAw1d), static_cast<std::size_t>(kAwSph)}) {
            const PartTable pt = part_table(fam[slot]);
            mats.insert(pt.mMats.begin(), pt.mMats.end());
            props.insert(pt.mProps.begin(), pt.mProps.end());
        }
        out.Ints({static_cast<std::int64_t>(mats.size()), static_cast<std::int64_t>(props.size())});
        for (const std::int64_t m : mats)
            out.Text("Material " + std::to_string(m), 50);
        out.Ints(std::vector<std::int64_t>(mats.begin(), mats.end()));
        for (const std::int64_t p : props)
            out.Text("Property " + std::to_string(p), 50);
        out.Ints(std::vector<std::int64_t>(props.begin(), props.end()));
    }
    if (flags[5]) {
        out.Ints({static_cast<std::int64_t>(th_items[0].size()),
                  static_cast<std::int64_t>(th_items[1].size()),
                  static_cast<std::int64_t>(th_items[2].size()),
                  static_cast<std::int64_t>(th_items[3].size())});
        for (const auto& items : th_items) {
            std::vector<std::int64_t> ids;
            for (const auto& item : items)
                ids.push_back(item.first);
            out.Ints(ids);
            for (const auto& item : items)
                out.Text(item.second, 50);
        }
    }
    const AwFamily& fs = fam[kAwSph];
    if (flags[7])
        section(fs,
                {static_cast<std::int64_t>(fs.Size()), 0,
                 static_cast<std::int64_t>(escalars.size()),
                 static_cast<std::int64_t>(tensors.size())},
                escalars, tensors, false, kAwSph);
    return out.Data();
}

void aw_save(const std::string& rPath, const std::string& rBytes) {
    auto out = detail::make_classic_ofstream(rPath, std::ios::binary);
    if (!out)
        throw WriteError("Could not open file for writing: " + rPath);
    out.write(rBytes.data(), static_cast<std::streamsize>(rBytes.size()));
    out.close();
    if (!out)
        throw WriteError("Radioss animation: failed writing " + rPath);
}

}  // namespace

void write_radioss_anim(const std::string& rPath, const Mesh& rMesh) {
    const detail::ProvenanceSlotlessWrite slotless;
    aw_save(rPath, aw_state_bytes(rMesh, aw_time_of(rMesh)));
}

struct RadiossAnimSeriesWriter::Impl {
    std::filesystem::path mDir;
    std::string mStem;
    std::size_t mWidth = 3;
    std::uint64_t mNext = 1;
    std::size_t mSteps = 0;
};

RadiossAnimSeriesWriter::RadiossAnimSeriesWriter(const std::string& rPath)
    : mpImpl(std::make_unique<Impl>()) {
    const std::filesystem::path path(rPath);
    const std::string name = path.filename().string();
    std::size_t k = name.size();
    while (k > 0 && std::isdigit(static_cast<unsigned char>(name[k - 1])))
        --k;
    mpImpl->mDir = path.parent_path();
    if (name.size() - k < 3 || k < 2 || name[k - 1] != 'A') {
        // Not an animation file name: the name is the stem.
        mpImpl->mStem = name + "A";
        mpImpl->mWidth = 3;
        mpImpl->mNext = 1;
    } else {
        mpImpl->mStem = name.substr(0, k);
        mpImpl->mWidth = name.size() - k;
        mpImpl->mNext = std::stoull(name.substr(k));
    }
}

RadiossAnimSeriesWriter::~RadiossAnimSeriesWriter() = default;
RadiossAnimSeriesWriter::RadiossAnimSeriesWriter(RadiossAnimSeriesWriter&&) noexcept = default;
RadiossAnimSeriesWriter& RadiossAnimSeriesWriter::operator=(RadiossAnimSeriesWriter&&) noexcept =
    default;

void RadiossAnimSeriesWriter::Write(double Time, const Mesh& rMesh) {
    if (!mpImpl)
        throw WriteError("Radioss animation: series: the writer was moved from");
    Impl& s = *mpImpl;
    std::string number = std::to_string(s.mNext++);
    if (number.size() < s.mWidth)
        number.insert(0, s.mWidth - number.size(), '0');
    const detail::ProvenanceSlotlessWrite slotless;
    aw_save((s.mDir / (s.mStem + number)).string(), aw_state_bytes(rMesh, Time));
    ++s.mSteps;
}

std::size_t RadiossAnimSeriesWriter::NumSteps() const noexcept {
    return mpImpl ? mpImpl->mSteps : 0;
}

void RadiossAnimSeriesWriter::Finalize() {}

}  // namespace meshioplusplus
