#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <set>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr const char* kAggPrefix = "meshio++: agglomerate: ";

/// A staged output block: either an unchanged copy of a pass-through input
/// block (any of its three storage shapes), or the one merged polyhedron
/// block. Mirrors subdivide.cpp's own staging shape; not shared with it,
/// since that one is file-private there too.
struct AggOutBlock {
    std::string mType;
    std::size_t mNodesPerCell = 0;  // rectangular pass-through only
    std::vector<std::int64_t> mConn;
    std::vector<std::vector<std::int64_t>> mPolygonRows;
    std::vector<std::vector<std::vector<std::int64_t>>> mPolyhedronCells;
    bool mIsRagged = false;
    bool mIsPolyhedron = false;
};

AggOutBlock agg_stage_passthrough(const Mesh::CellView& rBlock) {
    AggOutBlock out;
    out.mType = std::string(rBlock.Type());
    if (rBlock.IsPolyhedron()) {
        out.mIsRagged = true;
        out.mIsPolyhedron = true;
        out.mPolyhedronCells.resize(rBlock.NumCells());
        for (std::size_t c = 0; c < rBlock.NumCells(); ++c) {
            for (std::size_t f = 0; f < rBlock.NumFaces(c); ++f) {
                const auto face = rBlock.Face(c, f);
                out.mPolyhedronCells[c].emplace_back(face.first, face.first + face.second);
            }
        }
    } else if (rBlock.IsRagged()) {
        out.mIsRagged = true;
        out.mPolygonRows.resize(rBlock.NumCells());
        for (std::size_t c = 0; c < rBlock.NumCells(); ++c) {
            const std::int64_t* row = rBlock.Row(c);
            out.mPolygonRows[c].assign(row, row + rBlock.RowSize(c));
        }
    } else {
        const NDArray& conn = rBlock.Conn();
        const std::size_t npc = rBlock.NodesPerCell();
        out.mNodesPerCell = npc;
        out.mConn.resize(rBlock.NumCells() * npc);
        for (std::size_t c = 0; c < rBlock.NumCells(); ++c)
            for (std::size_t k = 0; k < npc; ++k)
                out.mConn[c * npc + k] = detail::read_int(conn, c * npc + k);
    }
    return out;
}

void agg_emit_block(Mesh& rOut, AggOutBlock& rBlock) {
    if (rBlock.mIsPolyhedron) {
        rOut.AddPolyhedronBlock(rBlock.mType, std::move(rBlock.mPolyhedronCells));
    } else if (rBlock.mIsRagged) {
        rOut.AddPolygonBlock(rBlock.mType, std::move(rBlock.mPolygonRows));
    } else {
        const std::size_t npc = rBlock.mNodesPerCell;
        const std::size_t ncells = npc == 0 ? 0 : rBlock.mConn.size() / npc;
        NDArray conn = NDArray::Uninit(DType::Int64, {ncells, npc});
        std::int64_t* dst = conn.As<std::int64_t>();
        for (std::size_t i = 0; i < rBlock.mConn.size(); ++i)
            dst[i] = rBlock.mConn[i];
        rOut.AddCellBlock(rBlock.mType, std::move(conn));
    }
}

/// Area of global face `f`, gathering its corner coordinates into a local
/// buffer first -- GlobalFaces::Face() returns GLOBAL node ids, while
/// polygon_area's ring-taking overload expects local indices, so the plain
/// (no-ring) overload over a freshly gathered buffer is the fit.
double agg_face_area(const detail::GlobalFaces& rFaces, std::size_t f, const NDArray& rPoints,
                     std::size_t PointDim) {
    const std::size_t n = rFaces.FaceSize(f);
    const std::int64_t* ring = rFaces.Face(f);
    std::vector<detail::Vec3> coords(n);
    for (std::size_t k = 0; k < n; ++k) {
        const auto pid = static_cast<std::size_t>(ring[k]);
        for (std::size_t d = 0; d < 3; ++d)
            coords[k][d] = d < PointDim ? detail::read_double(rPoints, pid * PointDim + d) : 0.0;
    }
    return detail::polygon_area(coords.data(), n);
}

/// Newell area vector and vertex centroid of global face `f`, as stored
/// (wound out of its owner).
void agg_face_geometry(const detail::GlobalFaces& rFaces, std::size_t f, const NDArray& rPoints,
                       std::size_t PointDim, detail::Vec3& rArea, detail::Vec3& rCentroid) {
    const std::size_t n = rFaces.FaceSize(f);
    const std::int64_t* ring = rFaces.Face(f);
    std::vector<detail::Vec3> p(n);
    for (std::size_t k = 0; k < n; ++k) {
        const auto pid = static_cast<std::size_t>(ring[k]);
        for (std::size_t d = 0; d < 3; ++d)
            p[k][d] = d < PointDim ? detail::read_double(rPoints, pid * PointDim + d) : 0.0;
    }
    rArea = {0.0, 0.0, 0.0};
    rCentroid = {0.0, 0.0, 0.0};
    for (std::size_t k = 0; k < n; ++k) {
        rArea = detail::vec3_add(rArea, detail::vec3_cross(p[k], p[(k + 1) % n]));
        rCentroid = detail::vec3_add(rCentroid, p[k]);
    }
    rArea = detail::vec3_scale(rArea, 0.5);
    rCentroid = detail::vec3_scale(rCentroid, n ? 1.0 / static_cast<double>(n) : 0.0);
}

/// Sphericity `pi^(1/3) (6V)^(2/3) / A`: 1 for a ball.
double agg_sphericity(double Volume, double Area) {
    if (!(Area > 0.0) || !(Volume > 0.0))
        return 0.0;
    return std::cbrt(3.14159265358979323846) * std::pow(6.0 * Volume, 2.0 / 3.0) / Area;
}

/// Whether a polyhedron's faces close up: every undirected edge used by
/// exactly two of its faces.
bool agg_closed(const std::vector<std::vector<std::int64_t>>& rFaces) {
    std::vector<std::array<std::int64_t, 2>> edges;
    for (const auto& face : rFaces)
        for (std::size_t k = 0; k < face.size(); ++k) {
            std::int64_t u = face[k];
            std::int64_t v = face[(k + 1) % face.size()];
            if (u == v)
                continue;
            if (u > v)
                std::swap(u, v);
            edges.push_back({u, v});
        }
    std::sort(edges.begin(), edges.end());
    for (std::size_t i = 0; i < edges.size();) {
        std::size_t j = i + 1;
        while (j < edges.size() && edges[j] == edges[i])
            ++j;
        if (j - i != 2)
            return false;
        i = j;
    }
    return true;
}

/// Coplanar patches of external faces. Faces separating the same two sides
/// (group, group-or-boundary) that share an edge and lie on one plane fuse
/// into one ring, wound out of `mSideA` (the lower group; the group itself
/// against the boundary).
struct AggPatches {
    std::vector<std::int64_t> mPatchOfFace;  // per global face, -1 when unfused
    std::vector<std::vector<std::int64_t>> mRing;
    std::vector<std::int64_t> mSideA;
    std::vector<std::int64_t> mSideB;  // -1 for the boundary
    std::vector<std::size_t> mNumFaces;
};

AggPatches agg_coplanar_patches(const detail::GlobalFaces& rFaces,
                                const std::vector<std::int64_t>& rGroupOf,
                                const std::vector<detail::Vec3>& rAreaVec, double CosTol,
                                const std::vector<std::uint8_t>& rRejectedFace) {
    const std::size_t nf = rFaces.NumFaces();
    AggPatches out;
    out.mPatchOfFace.assign(nf, -1);
    // Side keys and orientation of every external face.
    std::vector<std::int64_t> side_a(nf, -2);
    std::vector<std::int64_t> side_b(nf, -2);
    std::vector<std::uint8_t> flip(nf, 0);
    for (std::size_t f = 0; f < nf; ++f) {
        const std::int64_t go = rGroupOf[static_cast<std::size_t>(rFaces.mOwner[f])];
        const std::int64_t nb = rFaces.mNeighbour[f];
        const std::int64_t gn = nb >= 0 ? rGroupOf[static_cast<std::size_t>(nb)] : -1;
        if (go == gn || rRejectedFace[f])
            continue;
        side_a[f] = gn < 0 ? go : std::min(go, gn);
        side_b[f] = gn < 0 ? -1 : std::max(go, gn);
        flip[f] = go == side_a[f] ? 0 : 1;
    }
    auto unit = [&](std::size_t f) {
        detail::Vec3 n = detail::vec3_normalize(rAreaVec[f]);
        return flip[f] ? detail::vec3_scale(n, -1.0) : n;
    };
    // Faces grouped by (side a, side b, undirected edge).
    struct EdgeUse {
        std::int64_t mA, mB, mLo, mHi, mFace;
        bool operator<(const EdgeUse& o) const {
            return std::tie(mA, mB, mLo, mHi, mFace) < std::tie(o.mA, o.mB, o.mLo, o.mHi, o.mFace);
        }
    };
    std::vector<EdgeUse> uses;
    for (std::size_t f = 0; f < nf; ++f) {
        if (side_a[f] == -2)
            continue;
        const std::size_t n = rFaces.FaceSize(f);
        const std::int64_t* ring = rFaces.Face(f);
        for (std::size_t k = 0; k < n; ++k) {
            const std::int64_t u = ring[k];
            const std::int64_t v = ring[(k + 1) % n];
            uses.push_back({side_a[f], side_b[f], std::min(u, v), std::max(u, v),
                            static_cast<std::int64_t>(f)});
        }
    }
    std::sort(uses.begin(), uses.end());
    std::vector<std::int64_t> parent(nf);
    for (std::size_t f = 0; f < nf; ++f)
        parent[f] = static_cast<std::int64_t>(f);
    auto find = [&](std::int64_t x) {
        while (parent[static_cast<std::size_t>(x)] != x) {
            parent[static_cast<std::size_t>(x)] =
                parent[static_cast<std::size_t>(parent[static_cast<std::size_t>(x)])];
            x = parent[static_cast<std::size_t>(x)];
        }
        return x;
    };
    for (std::size_t i = 0; i < uses.size();) {
        std::size_t j = i + 1;
        while (j < uses.size() && uses[j].mA == uses[i].mA && uses[j].mB == uses[i].mB &&
               uses[j].mLo == uses[i].mLo && uses[j].mHi == uses[i].mHi)
            ++j;
        if (j - i == 2) {
            const auto fa = static_cast<std::size_t>(uses[i].mFace);
            const auto fb = static_cast<std::size_t>(uses[i + 1].mFace);
            if (detail::vec3_dot(unit(fa), unit(fb)) >= CosTol) {
                const std::int64_t ra = find(static_cast<std::int64_t>(fa));
                const std::int64_t rb = find(static_cast<std::int64_t>(fb));
                if (ra != rb)
                    parent[static_cast<std::size_t>(std::max(ra, rb))] = std::min(ra, rb);
            }
        }
        i = j;
    }
    // Components with two or more faces, in ascending root order.
    std::vector<std::vector<std::size_t>> members(nf);
    for (std::size_t f = 0; f < nf; ++f)
        if (side_a[f] != -2)
            members[static_cast<std::size_t>(find(static_cast<std::int64_t>(f)))].push_back(f);
    for (std::size_t root = 0; root < nf; ++root) {
        const std::vector<std::size_t>& comp = members[root];
        if (comp.size() < 2)
            continue;
        const detail::Vec3 n0 = unit(comp.front());
        bool planar = true;
        for (std::size_t f : comp)
            planar = planar && detail::vec3_dot(unit(f), n0) >= CosTol;
        if (!planar)
            continue;
        // The outline: directed edges (wound out of side a) used once.
        std::size_t num_directed = 0;
        for (std::size_t f : comp)
            num_directed += rFaces.FaceSize(f);
        std::vector<std::array<std::int64_t, 2>> dir;
        dir.reserve(num_directed);
        for (std::size_t f : comp) {
            const std::size_t n = rFaces.FaceSize(f);
            const std::int64_t* ring = rFaces.Face(f);
            for (std::size_t k = 0; k < n; ++k) {
                std::int64_t u = ring[k];
                std::int64_t v = ring[(k + 1) % n];
                if (flip[f])
                    std::swap(u, v);
                if (u != v)
                    dir.push_back({u, v});
            }
        }
        std::vector<std::array<std::int64_t, 2>> sorted = dir;
        std::sort(sorted.begin(), sorted.end());
        std::vector<std::array<std::int64_t, 2>> outline;
        outline.reserve(dir.size());
        for (const auto& e : dir)
            if (!std::binary_search(sorted.begin(), sorted.end(),
                                    std::array<std::int64_t, 2>{e[1], e[0]}))
                outline.push_back(e);
        std::sort(outline.begin(), outline.end());
        // A single simple loop: every vertex leaves once and is reached once.
        bool simple = outline.size() >= 3;
        for (std::size_t k = 1; simple && k < outline.size(); ++k)
            simple = outline[k][0] != outline[k - 1][0];
        std::vector<std::int64_t> heads;
        heads.reserve(outline.size());
        for (const auto& e : outline)
            heads.push_back(e[1]);
        std::sort(heads.begin(), heads.end());
        for (std::size_t k = 1; simple && k < heads.size(); ++k)
            simple = heads[k] != heads[k - 1];
        std::vector<std::int64_t> ring;
        if (simple) {
            ring.reserve(outline.size());
            std::int64_t at = outline.front()[0];
            for (std::size_t steps = 0; steps < outline.size(); ++steps) {
                ring.push_back(at);
                const auto it = std::lower_bound(outline.begin(), outline.end(),
                                                 std::array<std::int64_t, 2>{at, INT64_MIN});
                if (it == outline.end() || (*it)[0] != at) {
                    simple = false;
                    break;
                }
                at = (*it)[1];
            }
            simple = simple && at == outline.front()[0];
        }
        if (!simple)
            continue;
        const auto pid = static_cast<std::int64_t>(out.mRing.size());
        for (std::size_t f : comp)
            out.mPatchOfFace[f] = pid;
        out.mRing.push_back(std::move(ring));
        out.mSideA.push_back(side_a[comp.front()]);
        out.mSideB.push_back(side_b[comp.front()]);
        out.mNumFaces.push_back(comp.size());
    }
    return out;
}

/// Frontier entry ordered by DESCENDING accumulated shared-face area, ties
/// broken by ASCENDING compact cell id -- storing the negated area keeps a
/// plain ascending std::set a max-by-area, min-by-id priority structure.
struct FrontierKey {
    double mNegArea;
    std::int64_t mId;
    bool operator<(const FrontierKey& rOther) const {
        if (mNegArea != rOther.mNegArea)
            return mNegArea < rOther.mNegArea;
        return mId < rOther.mId;
    }
};

}  // namespace

AgglomerateResult agglomerate(const Mesh& rMesh, const AgglomerateOptions& rOptions) {
    if (rOptions.mTargetGroupSize == 0)
        throw std::invalid_argument(std::string(kAggPrefix) + "mTargetGroupSize must be >= 1");
    if (!(rOptions.mCoplanarAngleDeg >= 0.0 && rOptions.mCoplanarAngleDeg < 90.0))
        throw std::invalid_argument(std::string(kAggPrefix) +
                                    "mCoplanarAngleDeg must lie in [0, 90)");
    if (!(rOptions.mMinSphericity >= 0.0 && rOptions.mMinSphericity <= 1.0))
        throw std::invalid_argument(std::string(kAggPrefix) + "mMinSphericity must lie in [0, 1]");

    const detail::GlobalFaces gf = detail::build_global_faces(rMesh);
    if (gf.mNumNonManifold > 0)
        throw std::invalid_argument(
            std::string(kAggPrefix) + "mesh contains " + std::to_string(gf.mNumNonManifold) +
            " face(s) shared by three or more cells (non-manifold); refusing rather than "
            "guessing a boundary classification");

    const std::size_t n_compact = gf.NumCells();
    const NDArray& points = rMesh.Points();
    const std::size_t pdim = rMesh.PointDim();

    // Every face's area, once and in parallel: the grow loop below used to
    // recompute one each time a face was pushed.
    std::vector<double> face_area(gf.NumFaces());
    parallel_for(gf.NumFaces(),
                 [&](std::size_t f) { face_area[f] = agg_face_area(gf, f, points, pdim); });

    // Face area vectors and centroids, for the cells' volumes (the gate) and
    // the face normals (coplanar merging); only when either is asked for.
    const bool gate = rOptions.mMinSphericity > 0.0;
    std::vector<detail::Vec3> area_vec;
    std::vector<double> cell_volume;
    std::vector<double> cell_area;
    if (gate || rOptions.mMergeCoplanarFaces) {
        area_vec.resize(gf.NumFaces());
        std::vector<detail::Vec3> centroid(gf.NumFaces());
        parallel_for(gf.NumFaces(), [&](std::size_t f) {
            agg_face_geometry(gf, f, points, pdim, area_vec[f], centroid[f]);
        });
        if (gate) {
            // Divergence theorem over each cell's outward faces.
            cell_volume.assign(n_compact, 0.0);
            cell_area.assign(n_compact, 0.0);
            parallel_for(n_compact, [&](std::size_t c) {
                const std::size_t nfc = gf.NumCellFaces(c);
                const std::int64_t* row = gf.CellFaces(c);
                double v = 0.0;
                double a = 0.0;
                for (std::size_t k = 0; k < nfc; ++k) {
                    const std::int64_t sid = row[k];
                    const auto f = static_cast<std::size_t>((sid > 0 ? sid : -sid) - 1);
                    const double d = detail::vec3_dot(centroid[f], area_vec[f]) / 3.0;
                    v += sid > 0 ? d : -d;
                    a += face_area[f];
                }
                cell_volume[c] = v;
                cell_area[c] = a;
            });
        }
    }
    std::int64_t num_rejected = 0;

    // --- greedy seed-and-grow over the face dual --------------------------
    std::vector<std::int64_t> group_of(n_compact, -1);
    std::vector<std::vector<std::int64_t>> groups;

    // A candidate's accumulated shared area, as dense per-cell arrays reset
    // through the ids a seed touched -- no hash map allocated per seed. Same
    // sums, in the same order.
    std::vector<double> pending(n_compact, 0.0);
    // 0 not on the frontier, 1 on it, kRefused refused by the gate for this
    // seed's group (never pushed again: a re-push would restart its shared
    // area from one face and misjudge the union).
    constexpr std::uint8_t kRefused = 2;
    std::vector<std::uint8_t> is_pending(n_compact, 0);
    std::vector<std::int64_t> touched;
    std::set<FrontierKey> frontier;

    for (std::size_t seed = 0; seed < n_compact; ++seed) {
        if (group_of[seed] != -1)
            continue;
        const auto gid = static_cast<std::int64_t>(groups.size());
        std::vector<std::int64_t> members{static_cast<std::int64_t>(seed)};
        group_of[seed] = gid;
        for (std::int64_t t : touched)
            is_pending[static_cast<std::size_t>(t)] = 0;
        touched.clear();
        frontier.clear();

        auto push_neighbours = [&](std::int64_t c) {
            const std::size_t nf = gf.NumCellFaces(static_cast<std::size_t>(c));
            const std::int64_t* row = gf.CellFaces(static_cast<std::size_t>(c));
            for (std::size_t k = 0; k < nf; ++k) {
                const std::int64_t sid = row[k];
                const auto f = static_cast<std::size_t>((sid > 0 ? sid : -sid) - 1);
                const std::int64_t owner = gf.mOwner[f];
                const std::int64_t neigh = gf.mNeighbour[f];
                const std::int64_t other = (owner == c) ? neigh : owner;
                if (other < 0)
                    continue;  // mesh boundary
                if (group_of[static_cast<std::size_t>(other)] != -1)
                    continue;  // already claimed (by this group or would be a bug otherwise)
                if (is_pending[static_cast<std::size_t>(other)] == kRefused)
                    continue;  // refused for this group
                const double a = face_area[f];
                double& acc = pending[static_cast<std::size_t>(other)];
                if (is_pending[static_cast<std::size_t>(other)]) {
                    frontier.erase(FrontierKey{-acc, other});
                    acc += a;
                } else {
                    acc = a;
                    is_pending[static_cast<std::size_t>(other)] = 1;
                    touched.push_back(other);
                }
                frontier.insert(FrontierKey{-acc, other});
            }
        };

        push_neighbours(static_cast<std::int64_t>(seed));
        double group_volume = gate ? cell_volume[seed] : 0.0;
        double group_area = gate ? cell_area[seed] : 0.0;

        while (members.size() < rOptions.mTargetGroupSize && !frontier.empty()) {
            const auto fit = frontier.begin();
            const std::int64_t c = fit->mId;
            frontier.erase(fit);
            is_pending[static_cast<std::size_t>(c)] = 0;
            if (group_of[static_cast<std::size_t>(c)] != -1)
                continue;  // defensive; unreachable given the push-time check above
            if (gate) {
                // The union's volume and external area: the shared faces leave
                // the surface from both sides.
                const auto ci = static_cast<std::size_t>(c);
                const double v = group_volume + cell_volume[ci];
                const double a = group_area + cell_area[ci] - 2.0 * pending[ci];
                if (agg_sphericity(v, a) < rOptions.mMinSphericity) {
                    ++num_rejected;
                    is_pending[ci] = kRefused;  // skipped for this group only
                    continue;
                }
                group_volume = v;
                group_area = a;
            }
            group_of[static_cast<std::size_t>(c)] = gid;
            members.push_back(c);
            push_neighbours(c);
        }

        std::sort(members.begin(), members.end());
        groups.push_back(std::move(members));
    }

    // --- coplanar patches (optional) -----------------------------------------
    AggPatches patches;
    patches.mPatchOfFace.assign(gf.NumFaces(), -1);
    std::vector<std::uint8_t> rejected_face(gf.NumFaces(), 0);
    const double cos_tol = std::cos(rOptions.mCoplanarAngleDeg * 3.14159265358979323846 / 180.0);
    std::int64_t num_faces_merged = 0;

    // --- emit: one polyhedron cell per group, external faces only ---------
    std::vector<std::vector<std::vector<std::int64_t>>> merged_cells(groups.size());
    for (int attempt = 0; attempt < 3; ++attempt) {
        if (rOptions.mMergeCoplanarFaces)
            patches = agg_coplanar_patches(gf, group_of, area_vec, cos_tol, rejected_face);
        num_faces_merged = 0;
        for (std::size_t g = 0; g < groups.size(); ++g) {
            auto& faces_out = merged_cells[g];
            faces_out.clear();
            std::vector<std::uint8_t> patch_done(patches.mRing.size(), 0);
            for (std::int64_t c : groups[g]) {
                const std::size_t nf = gf.NumCellFaces(static_cast<std::size_t>(c));
                const std::int64_t* row = gf.CellFaces(static_cast<std::size_t>(c));
                for (std::size_t k = 0; k < nf; ++k) {
                    const std::int64_t sid = row[k];
                    const auto f = static_cast<std::size_t>((sid > 0 ? sid : -sid) - 1);
                    const std::int64_t owner = gf.mOwner[f];
                    const std::int64_t neigh = gf.mNeighbour[f];
                    const std::int64_t other = (owner == c) ? neigh : owner;
                    if (other >= 0 && group_of[static_cast<std::size_t>(other)] ==
                                          group_of[static_cast<std::size_t>(c)])
                        continue;  // internal to the group: dropped from both sides
                    const std::int64_t pid = patches.mPatchOfFace[f];
                    if (pid >= 0) {
                        // A fused patch: its ring once, wound out of this group.
                        const auto pi = static_cast<std::size_t>(pid);
                        if (!patch_done[pi]) {
                            patch_done[pi] = 1;
                            std::vector<std::int64_t> ring_nodes = patches.mRing[pi];
                            if (patches.mSideA[pi] != static_cast<std::int64_t>(g))
                                std::reverse(ring_nodes.begin(), ring_nodes.end());
                            faces_out.push_back(std::move(ring_nodes));
                            num_faces_merged +=
                                static_cast<std::int64_t>(patches.mNumFaces[pi]) - 1;
                        }
                        continue;
                    }
                    const std::size_t n = gf.FaceSize(f);
                    const std::int64_t* ring = gf.Face(f);
                    std::vector<std::int64_t> face_nodes(ring, ring + n);
                    if (sid < 0)
                        std::reverse(face_nodes.begin(), face_nodes.end());
                    faces_out.push_back(std::move(face_nodes));
                }
            }
        }
        if (patches.mRing.empty())
            break;
        // A fusion must leave every polyhedron it touches closed; a patch of a
        // group that no longer closes is withdrawn (both sides) and the emit rerun.
        bool all_closed = true;
        for (std::size_t g = 0; g < groups.size(); ++g) {
            if (agg_closed(merged_cells[g]))
                continue;
            all_closed = false;
            for (std::size_t f = 0; f < gf.NumFaces(); ++f) {
                const std::int64_t pid = patches.mPatchOfFace[f];
                if (pid < 0)
                    continue;
                const auto pi = static_cast<std::size_t>(pid);
                if (patches.mSideA[pi] == static_cast<std::int64_t>(g) ||
                    patches.mSideB[pi] == static_cast<std::int64_t>(g))
                    rejected_face[f] = 1;
            }
        }
        if (all_closed)
            break;
        if (attempt == 2) {
            // Give up on fusion rather than emit an open polyhedron.
            log::warn("{}coplanar merging left an open polyhedron; faces kept unmerged",
                      kAggPrefix);
            std::fill(rejected_face.begin(), rejected_face.end(), std::uint8_t{1});
            attempt = 1;  // one more pass, with every face rejected
        }
    }

    // --- which original blocks carry volume, and the compact<->global bridge
    std::vector<bool> is_volume(rMesh.NumCellBlocks(), true);
    for (std::size_t b : gf.mNonCellBlocks)
        if (b < is_volume.size())
            is_volume[b] = false;

    const std::vector<std::int64_t> in_bases = detail::block_bases(rMesh);
    std::unordered_map<std::int64_t, std::int64_t> global_to_compact;
    global_to_compact.reserve(n_compact);
    for (std::size_t c = 0; c < n_compact; ++c)
        global_to_compact[gf.mCellToGlobal[c]] = static_cast<std::int64_t>(c);

    // --- build the output mesh's blocks, tracking where each original block
    // landed (pass-through) or whether it fed the merged block -----------
    Mesh out;
    out.AssignPoints(detail::data_owned_copy(points));

    const std::size_t nblocks_in = rMesh.NumCellBlocks();
    std::vector<std::int64_t> pass_out_block(nblocks_in, -1);
    std::int64_t merged_out_block = -1;
    bool merged_emitted = false;
    std::size_t bi = 0;
    std::int64_t out_block_idx = 0;
    for (const auto cb : rMesh.CellRange()) {
        if (is_volume[bi]) {
            if (!merged_emitted) {
                AggOutBlock mb;
                mb.mType = "polyhedron";
                mb.mIsRagged = true;
                mb.mIsPolyhedron = true;
                mb.mPolyhedronCells = std::move(merged_cells);
                if (!mb.mPolyhedronCells.empty()) {
                    agg_emit_block(out, mb);
                    merged_out_block = out_block_idx++;
                }
                merged_emitted = true;
            }
        } else {
            AggOutBlock pb = agg_stage_passthrough(cb);
            agg_emit_block(out, pb);
            pass_out_block[bi] = out_block_idx++;
        }
        ++bi;
    }

    const std::vector<std::int64_t> out_bases = detail::block_bases(out);

    // --- the flat cell map --------------------------------------------------
    NDArray cell_map =
        NDArray::Uninit(DType::Int64, {static_cast<std::size_t>(detail::total_cells(in_bases))});
    std::int64_t* cm = cell_map.As<std::int64_t>();
    bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        const std::int64_t base_in = in_bases[bi];
        if (is_volume[bi]) {
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::int64_t global_in = base_in + static_cast<std::int64_t>(r);
                const std::int64_t compact = global_to_compact.at(global_in);
                cm[global_in] = merged_out_block < 0
                                    ? -1
                                    : out_bases[static_cast<std::size_t>(merged_out_block)] +
                                          group_of[static_cast<std::size_t>(compact)];
            }
        } else {
            const std::int64_t ob = pass_out_block[bi];
            for (std::size_t r = 0; r < cb.NumCells(); ++r) {
                const std::int64_t global_in = base_in + static_cast<std::int64_t>(r);
                cm[global_in] =
                    out_bases[static_cast<std::size_t>(ob)] + static_cast<std::int64_t>(r);
            }
        }
        ++bi;
    }

    // --- point_data / field_data: unchanged, no new or pruned points -------
    for (const std::string& name : rMesh.PointDataNames())
        out.AddPointData(name, detail::data_owned_copy(rMesh.PointData(name)));
    for (const std::string& name : rMesh.FieldDataNames())
        out.AddFieldData(name, detail::data_owned_copy(rMesh.FieldData(name)));

    // --- cell_data: pass-through blocks copied verbatim; the merged block's
    // row for group g is its first (ascending compact id) member's row -----
    for (const std::string& name : rMesh.CellDataNames()) {
        const std::size_t ndata = rMesh.CellDataNumBlocks(name);
        if (ndata != nblocks_in) {
            log::warn(
                "{}cell_data '{}' does not have one array per input block; dropped rather "
                "than guessed at",
                kAggPrefix, name);
            continue;
        }
        std::vector<NDArray> out_blocks(static_cast<std::size_t>(out_block_idx));
        bi = 0;
        for (const auto cb : rMesh.CellRange()) {
            (void)cb;
            if (!is_volume[bi] && pass_out_block[bi] >= 0)
                out_blocks[static_cast<std::size_t>(pass_out_block[bi])] =
                    detail::data_owned_copy(rMesh.CellData(name, bi));
            ++bi;
        }
        if (merged_out_block >= 0) {
            // Resolve each group's first member's (block, row) and gather.
            const NDArray& first_src = rMesh.CellData(name, 0);
            std::vector<std::size_t> shape = first_src.Shape();
            shape[0] = groups.size();
            NDArray dst = NDArray::Uninit(first_src.Dtype(), std::move(shape));
            const std::size_t row_bytes =
                first_src.Nbytes() / std::max<std::size_t>(1, detail::rows(first_src));
            std::byte* p_dst = dst.Data();
            for (std::size_t g = 0; g < groups.size(); ++g) {
                const std::int64_t compact_first = groups[g].front();
                const std::int64_t global =
                    gf.mCellToGlobal[static_cast<std::size_t>(compact_first)];
                const auto [blk, row] = detail::global_to_block_row(in_bases, global);
                const NDArray& src = rMesh.CellData(name, blk);
                const std::byte* p_src = src.Data();
                std::memcpy(p_dst + g * row_bytes,
                            p_src + static_cast<std::size_t>(row) * row_bytes, row_bytes);
            }
            out_blocks[static_cast<std::size_t>(merged_out_block)] = std::move(dst);
        }
        out.AddCellData(name, std::move(out_blocks));
    }

    AgglomerateResult res;
    res.mMesh = std::move(out);
    res.mCellMap = std::move(cell_map);
    res.mNumFacesMerged = num_faces_merged;
    res.mNumRejected = num_rejected;

    detail::RegionRemap rmap;
    rmap.mCellMapKind = detail::CellMapKind::Global;
    rmap.pGlobalCellMap = &res.mCellMap;
    rmap.mOpName = "agglomerate";
    detail::remap_regions(rMesh, res.mMesh, rmap);

    return res;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/agglomerate.cpp =====
// ===== begin src/cpp/src/operations/blend.cpp =====
#include <cstddef>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {
namespace {

constexpr const char* kBlPrefix = "meshio++: blend_steps: ";

bool bl_is_float(DType Dt) {
    return Dt == DType::Float32 || Dt == DType::Float64;
}

// (1 - w) a + w b over two arrays of one shape; integers from the nearer one.
NDArray bl_blend(const NDArray& rA, const NDArray& rB, double W, const std::string& rWhat) {
    if (rA.Shape() != rB.Shape())
        throw std::invalid_argument(std::string(kBlPrefix) + rWhat +
                                    " has different shapes in the two steps");
    if (!bl_is_float(rA.Dtype()) || !bl_is_float(rB.Dtype()))
        return detail::data_owned_copy(W < 0.5 ? rA : rB);
    NDArray out = NDArray::Uninit(rA.Dtype(), rA.Shape());
    const double wa = 1.0 - W;
    parallel_for_bw(rA.Size(), [&](std::size_t i) {
        detail::write_double(out, i,
                             wa * detail::read_double(rA, i) + W * detail::read_double(rB, i));
    });
    return out;
}

void bl_check_topology(const Mesh& rA, const Mesh& rB) {
    if (rA.NumPoints() != rB.NumPoints() || rA.PointDim() != rB.PointDim())
        throw std::invalid_argument(std::string(kBlPrefix) + "the steps have " +
                                    std::to_string(rA.NumPoints()) + " and " +
                                    std::to_string(rB.NumPoints()) +
                                    " points; blending needs one topology across the steps");
    if (rA.NumCellBlocks() != rB.NumCellBlocks())
        throw std::invalid_argument(std::string(kBlPrefix) +
                                    "the steps have different numbers of cell blocks");
    for (std::size_t b = 0; b < rA.NumCellBlocks(); ++b) {
        const auto ca = rA.Cells(b);
        const auto cb = rB.Cells(b);
        if (std::string(ca.Type()) != std::string(cb.Type()) || ca.NumCells() != cb.NumCells())
            throw std::invalid_argument(std::string(kBlPrefix) + "cell block " + std::to_string(b) +
                                        " differs between the steps (" + std::string(ca.Type()) +
                                        " x" + std::to_string(ca.NumCells()) + " vs " +
                                        std::string(cb.Type()) + " x" +
                                        std::to_string(cb.NumCells()) + ")");
    }
    auto same_names = [&](const std::vector<std::string>& rX, const std::vector<std::string>& rY,
                          const char* pWhat) {
        if (rX != rY)
            throw std::invalid_argument(std::string(kBlPrefix) + "the steps carry different " +
                                        pWhat + " arrays");
    };
    same_names(rA.PointDataNames(), rB.PointDataNames(), "point_data");
    same_names(rA.CellDataNames(), rB.CellDataNames(), "cell_data");
    same_names(rA.FieldDataNames(), rB.FieldDataNames(), "field_data");
}

}  // namespace

Mesh blend_steps(const Mesh& rA, const Mesh& rB, double W, const BlendOptions& rOptions) {
    bl_check_topology(rA, rB);
    Mesh out = detail::clone_geometry(rA);
    if (rOptions.mBlendPoints)
        out.AssignPoints(bl_blend(rA.Points(), rB.Points(), W, "the point array"));
    for (const std::string& name : rA.PointDataNames())
        out.AddPointData(
            name, bl_blend(rA.PointData(name), rB.PointData(name), W, "point_data '" + name + "'"));
    for (const std::string& name : rA.CellDataNames()) {
        if (rA.CellDataNumBlocks(name) != rB.CellDataNumBlocks(name))
            throw std::invalid_argument(std::string(kBlPrefix) + "cell_data '" + name +
                                        "' has different block counts in the two steps");
        std::vector<NDArray> blocks;
        for (std::size_t b = 0; b < rA.CellDataNumBlocks(name); ++b)
            blocks.push_back(bl_blend(rA.CellData(name, b), rB.CellData(name, b), W,
                                      "cell_data '" + name + "'"));
        out.AddCellData(name, std::move(blocks));
    }
    for (const std::string& name : rA.FieldDataNames())
        out.AddFieldData(
            name, bl_blend(rA.FieldData(name), rB.FieldData(name), W, "field_data '" + name + "'"));
    return out;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/blend.cpp =====
// ===== begin src/cpp/src/operations/boundary_layer.cpp =====
#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <limits>
#include <map>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

using BlV3 = std::array<double, 3>;

constexpr const char* kBoundaryLayerPrefix = "meshio++: boundary_layer: ";
// The least cosine at which a point still sees all its faces.
constexpr double kBlVisible = 0.05;
// Offsets are divided by the least cosine, at most this many times.
constexpr double kBlMaxStretch = 4.0;
// A cell is valid when its least scaled corner Jacobian passes this.
constexpr double kBlMinJacobian = 1e-6;

[[noreturn]] void bl_fail(const std::string& rWhy) {
    throw std::invalid_argument(std::string(kBoundaryLayerPrefix) + rWhy);
}

BlV3 bl_sub(const BlV3& rA, const BlV3& rB) {
    return {rA[0] - rB[0], rA[1] - rB[1], rA[2] - rB[2]};
}
double bl_dot(const BlV3& rA, const BlV3& rB) {
    return rA[0] * rB[0] + rA[1] * rB[1] + rA[2] * rB[2];
}
BlV3 bl_cross(const BlV3& rA, const BlV3& rB) {
    return {rA[1] * rB[2] - rA[2] * rB[1], rA[2] * rB[0] - rA[0] * rB[2],
            rA[0] * rB[1] - rA[1] * rB[0]};
}
double bl_norm(const BlV3& rA) {
    return std::sqrt(bl_dot(rA, rA));
}
BlV3 bl_unit(const BlV3& rA) {
    const double l = bl_norm(rA);
    return l > 0.0 ? BlV3{rA[0] / l, rA[1] / l, rA[2] / l} : BlV3{0.0, 0.0, 0.0};
}

// Row I of a C-contiguous array, as bytes.
std::size_t bl_row_bytes(const NDArray& rA) {
    std::size_t r = dtype_size(rA.Dtype());
    for (std::size_t d = 1; d < rA.Ndim(); ++d)
        r *= rA.Shape()[d];
    return r;
}

// The rows `rFrom` of `rA`, as a new array.
NDArray bl_gather(const NDArray& rA, const std::vector<std::int64_t>& rFrom) {
    std::vector<std::size_t> shape = rA.Shape();
    if (shape.empty())
        shape.push_back(0);
    shape[0] = rFrom.size();
    NDArray out = NDArray::Uninit(rA.Dtype(), shape);
    const std::size_t row = bl_row_bytes(rA);
    for (std::size_t i = 0; i < rFrom.size(); ++i)
        std::memcpy(out.Data() + i * row, rA.Data() + static_cast<std::size_t>(rFrom[i]) * row,
                    row);
    return out;
}

}  // namespace

BoundaryLayerResult boundary_layer(const Mesh& rSurface, const BoundaryLayerOptions& rOptions) {
    const BoundaryLayerOptions& o = rOptions;
    if (!(std::isfinite(o.mFirstHeight) && o.mFirstHeight > 0.0))
        bl_fail("first_height must be positive and finite");
    if (!(std::isfinite(o.mGrowth) && o.mGrowth >= 1.0 && o.mGrowth <= 10.0))
        bl_fail("growth must be between 1 and 10");
    if (o.mNumLayers < 1 || o.mNumLayers > 1000)
        bl_fail("num_layers must be between 1 and 1000");
    if (!(o.mCollisionFraction > 0.0 && o.mCollisionFraction <= 1.0))
        bl_fail("collision_fraction must be in (0, 1]");
    if (o.mSmoothIterations < 0 || o.mSmoothIterations > 1000)
        bl_fail("smooth_iterations must be between 0 and 1000");
    if (o.mMaxShrink < 0 || o.mMaxShrink > 60)
        bl_fail("max_shrink must be between 0 and 60");
    const std::size_t np = rSurface.NumPoints();
    const NDArray& r_pts = rSurface.Points();
    if (np > 0 && (r_pts.Ndim() != 2 || r_pts.Shape()[1] != 3))
        bl_fail("the surface's points must be three-dimensional");
    std::vector<double> x(3 * np);
    for (std::size_t i = 0; i < 3 * np; ++i)
        x[i] = detail::read_double(r_pts, i);
    const auto point = [&](std::int64_t P) {
        const auto i = static_cast<std::size_t>(P);
        return BlV3{x[3 * i], x[3 * i + 1], x[3 * i + 2]};
    };

    // The faces, and where each comes from.
    std::vector<std::array<std::int64_t, 4>> faces;
    std::vector<std::array<std::size_t, 2>> source;  // (block, cell)
    std::vector<char> face_block(rSurface.NumCellBlocks(), 0);
    for (std::size_t b = 0; b < rSurface.NumCellBlocks(); ++b) {
        const auto cells = rSurface.Cells(b);
        const std::string type(cells.Type());
        if (type.rfind("line", 0) == 0 || type == "vertex")
            continue;
        if ((type != "triangle" && type != "quad") || cells.IsRagged())
            bl_fail("a '" + type + "' block: layers grow from triangles and quads (linearize or " +
                    "extract_surface first)");
        face_block[b] = 1;
        const std::size_t k = type == "triangle" ? 3 : 4;
        for (std::size_t c = 0; c < cells.NumCells(); ++c) {
            std::array<std::int64_t, 4> f{-1, -1, -1, -1};
            for (std::size_t i = 0; i < k; ++i) {
                f[i] = detail::read_int(cells.Conn(), k * c + i);
                if (f[i] < 0 || static_cast<std::size_t>(f[i]) >= np)
                    bl_fail("a face names a point out of range");
            }
            faces.push_back(f);
            source.push_back({b, c});
        }
    }
    if (faces.empty())
        bl_fail("the surface has no triangle or quad");
    const std::size_t nf = faces.size();
    const auto corners = [&](std::size_t F) { return faces[F][3] >= 0 ? 4 : 3; };
    // Manifold and consistently oriented.
    {
        std::map<std::pair<std::int64_t, std::int64_t>, std::array<int, 2>> uses;
        for (std::size_t f = 0; f < nf; ++f)
            for (int i = 0; i < corners(f); ++i) {
                const std::int64_t a = faces[f][static_cast<std::size_t>(i)];
                const std::int64_t b = faces[f][static_cast<std::size_t>((i + 1) % corners(f))];
                auto& r_u = uses[{std::min(a, b), std::max(a, b)}];
                ++r_u[0];
                r_u[1] += a < b ? 1 : -1;
            }
        for (const auto& [e, r_u] : uses) {
            if (r_u[0] > 2)
                bl_fail("edge (" + std::to_string(e.first) + ", " + std::to_string(e.second) +
                        ") is used by more than two faces");
            if (r_u[0] == 2 && r_u[1] != 0)
                bl_fail("the faces at edge (" + std::to_string(e.first) + ", " +
                        std::to_string(e.second) + ") disagree on its direction (orient them)");
        }
    }
    // Unit face normals along the growth, and each point's faces with its
    // corner angle there.
    const double sign = o.mReverse ? -1.0 : 1.0;
    std::vector<BlV3> fn(nf);
    std::vector<std::vector<std::pair<std::size_t, double>>> around(np);
    std::vector<std::vector<std::int64_t>> nbrs(np);
    for (std::size_t f = 0; f < nf; ++f) {
        const int k = corners(f);
        BlV3 n{0.0, 0.0, 0.0};
        for (int i = 0; i < k; ++i) {
            const BlV3 a = point(faces[f][static_cast<std::size_t>(i)]);
            const BlV3 b = point(faces[f][static_cast<std::size_t>((i + 1) % k)]);
            n = {n[0] + (a[1] - b[1]) * (a[2] + b[2]), n[1] + (a[2] - b[2]) * (a[0] + b[0]),
                 n[2] + (a[0] - b[0]) * (a[1] + b[1])};
        }
        n = bl_unit(n);
        fn[f] = {sign * n[0], sign * n[1], sign * n[2]};
        for (int i = 0; i < k; ++i) {
            const std::int64_t p = faces[f][static_cast<std::size_t>(i)];
            const std::int64_t q = faces[f][static_cast<std::size_t>((i + 1) % k)];
            const std::int64_t r = faces[f][static_cast<std::size_t>((i + k - 1) % k)];
            const BlV3 u = bl_unit(bl_sub(point(q), point(p)));
            const BlV3 v = bl_unit(bl_sub(point(r), point(p)));
            const double angle = std::acos(std::clamp(bl_dot(u, v), -1.0, 1.0));
            around[static_cast<std::size_t>(p)].push_back({f, angle});
            nbrs[static_cast<std::size_t>(p)].push_back(q);
            nbrs[static_cast<std::size_t>(p)].push_back(r);
        }
    }
    for (auto& r_n : nbrs) {
        std::sort(r_n.begin(), r_n.end());
        r_n.erase(std::unique(r_n.begin(), r_n.end()), r_n.end());
    }
    // Each point's most normal normal (Aubry and Löhner 2009): from the
    // angle-weighted mean, steps toward the face that sees it least.
    std::vector<BlV3> dir(np, BlV3{0.0, 0.0, 0.0});
    std::vector<double> stretch(np, 0.0), sigma(np, 0.0);
    std::vector<char> used(np, 0), not_visible(np, 0);
    parallel_for(
        np,
        [&](std::size_t P) {
            const auto& r_a = around[P];
            if (r_a.empty())
                return;
            used[P] = 1;
            BlV3 m{0.0, 0.0, 0.0};
            for (const auto& [f, w] : r_a)
                m = {m[0] + w * fn[f][0], m[1] + w * fn[f][1], m[2] + w * fn[f][2]};
            BlV3 n = bl_unit(m);
            const auto least = [&](const BlV3& rN, std::size_t& rWho) {
                double lo = std::numeric_limits<double>::infinity();
                for (const auto& [f, w] : r_a) {
                    (void)w;
                    const double d = bl_dot(rN, fn[f]);
                    if (d < lo) {
                        lo = d;
                        rWho = f;
                    }
                }
                return lo;
            };
            std::size_t who = 0;
            BlV3 best = n;
            double best_lo = least(n, who);
            for (int it = 0; it < 100 && r_a.size() > 1; ++it) {
                const double eta = 1.0 / double(it + 2);
                n = bl_unit(
                    {n[0] + eta * fn[who][0], n[1] + eta * fn[who][1], n[2] + eta * fn[who][2]});
                const double lo = least(n, who);
                if (lo > best_lo) {
                    best_lo = lo;
                    best = n;
                }
            }
            dir[P] = best;
            if (!(best_lo > kBlVisible)) {
                not_visible[P] = 1;
                return;
            }
            stretch[P] = 1.0 / std::max(best_lo, 1.0 / kBlMaxStretch);
            sigma[P] = 1.0;
        },
        64);
    // The levels' offsets, before each point's own fraction and stretch.
    const auto nl = static_cast<std::size_t>(o.mNumLayers);
    std::vector<double> level(nl);
    {
        double h = o.mFirstHeight, s = 0.0;
        for (std::size_t k = 0; k < nl; ++k) {
            s += h;
            level[k] = s;
            h *= o.mGrowth;
        }
    }
    const double total = level.back();
    // Collisions: a ray along each point's direction against the surface.
    detail::TriangleSoup soup;
    soup.mPoints.resize(np);
    for (std::size_t i = 0; i < np; ++i)
        soup.mPoints[i] = point(static_cast<std::int64_t>(i));
    for (std::size_t f = 0; f < nf; ++f) {
        const auto& r_f = faces[f];
        const auto tri = [&](std::int64_t A, std::int64_t B, std::int64_t C) {
            soup.mVertices.push_back({A, B, C});
            soup.mCorners.push_back(point(A));
            soup.mCorners.push_back(point(B));
            soup.mCorners.push_back(point(C));
            soup.mSourceCell.push_back(static_cast<std::int64_t>(f));
        };
        tri(r_f[0], r_f[1], r_f[2]);
        if (r_f[3] >= 0)
            tri(r_f[0], r_f[2], r_f[3]);
    }
    const detail::TriBvh tree = detail::build_tri_bvh(soup);
    parallel_for(
        np,
        [&](std::size_t P) {
            if (!(sigma[P] > 0.0))
                return;
            double shortest = std::numeric_limits<double>::infinity();
            for (const std::int64_t q : nbrs[P])
                shortest = std::min(shortest,
                                    bl_norm(bl_sub(point(q), point(static_cast<std::int64_t>(P)))));
            const double want = total * stretch[P];
            const detail::TriRayHit hit =
                detail::tri_bvh_ray(tree, point(static_cast<std::int64_t>(P)), dir[P],
                                    1e-6 * shortest, want / o.mCollisionFraction);
            if (hit.mTriangle >= 0)
                sigma[P] = std::min(1.0, o.mCollisionFraction * hit.mT / want);
        },
        64);
    // Tapered: each fraction at most the mean of itself and its neighbours'.
    for (int it = 0; it < o.mSmoothIterations; ++it) {
        std::vector<double> next = sigma;
        for (std::size_t p = 0; p < np; ++p) {
            if (!used[p] || nbrs[p].empty())
                continue;
            double mean = 0.0;
            for (const std::int64_t q : nbrs[p])
                mean += sigma[static_cast<std::size_t>(q)];
            mean /= double(nbrs[p].size());
            next[p] = std::min(sigma[p], 0.5 * (sigma[p] + mean));
        }
        sigma = std::move(next);
    }
    // Sweep, judge, shrink the points of the cells that fold, and again.
    detail::LayerSweepInput in;
    in.pPoints = x.data();
    in.mNumPoints = static_cast<std::int64_t>(np);
    // The sweep orients a cell by its face's normal: against it, each face
    // runs the other way.
    in.mFaces = faces;
    if (o.mReverse)
        for (auto& r_f : in.mFaces) {
            if (r_f[3] >= 0)
                std::swap(r_f[1], r_f[3]);
            else
                std::swap(r_f[1], r_f[2]);
        }
    in.mLayers = o.mNumLayers;
    in.mDirections.resize(3 * np);
    for (std::size_t p = 0; p < np; ++p)
        for (std::size_t c = 0; c < 3; ++c)
            in.mDirections[3 * p + c] = dir[p][c];
    std::vector<int> halvings(np, 0);
    detail::LayerSweepResult sweep;
    double min_sj = std::numeric_limits<double>::infinity();
    for (int round = 0;; ++round) {
        in.mOffsets.assign(np * nl, 0.0);
        for (std::size_t p = 0; p < np; ++p)
            if (sigma[p] > 0.0)
                for (std::size_t k = 0; k < nl; ++k)
                    in.mOffsets[p * nl + k] = sigma[p] * stretch[p] * level[k];
        sweep = detail::layer_sweep(in);
        std::vector<char> bad_point(np, 0);
        bool bad = false;
        min_sj = std::numeric_limits<double>::infinity();
        const auto judge = [&](const std::vector<detail::LayerSweepCell>& rCells, int Kind) {
            for (const auto& r_c : rCells) {
                const double sj =
                    detail::layer_cell_scaled_jacobian(sweep.mPoints.data(), r_c, Kind);
                min_sj = std::min(min_sj, sj);
                if (sj > kBlMinJacobian)
                    continue;
                bad = true;
                for (int i = 0; i < Kind; ++i)
                    bad_point[static_cast<std::size_t>(sweep.mOrigin[static_cast<std::size_t>(
                        r_c.mNodes[static_cast<std::size_t>(i)])])] = 1;
            }
        };
        judge(sweep.mHexahedra, 8);
        judge(sweep.mWedges, 6);
        judge(sweep.mPyramids, 5);
        judge(sweep.mTetrahedra, 4);
        if (!bad)
            break;
        if (round > 64 * (o.mMaxShrink + 2))
            throw std::logic_error(std::string(kBoundaryLayerPrefix) +
                                   "internal error: the layers do not settle");
        for (std::size_t p = 0; p < np; ++p)
            if (bad_point[p] && sigma[p] > 0.0) {
                if (halvings[p] < o.mMaxShrink) {
                    sigma[p] *= 0.5;
                    ++halvings[p];
                } else {
                    sigma[p] = 0.0;
                }
            }
    }

    // The mesh: the cells, then the wall and the cap.
    BoundaryLayerResult result;
    const auto warn = [&](const std::string& rMsg) {
        log::warn("boundary_layer: {}", rMsg);
        result.mWarnings.push_back(rMsg);
    };
    Mesh& r_m = result.mMesh;
    const std::size_t nout = sweep.mOrigin.size();
    NDArray pts = NDArray::Uninit(DType::Float64, {nout, std::size_t{3}});
    std::copy(sweep.mPoints.begin(), sweep.mPoints.end(), pts.As<double>());
    r_m.AssignPoints(std::move(pts));
    struct Block {
        const char* pType;
        const std::vector<detail::LayerSweepCell>* pCells;
        std::size_t mNodes;
        int mRole;  // 3 cells, 0 wall, 1 cap
    };
    const std::vector<Block> blocks = {
        {"wedge", &sweep.mWedges, 6, 3},           {"hexahedron", &sweep.mHexahedra, 8, 3},
        {"pyramid", &sweep.mPyramids, 5, 3},       {"tetra", &sweep.mTetrahedra, 4, 3},
        {"triangle", &sweep.mWallTriangles, 3, 0}, {"quad", &sweep.mWallQuads, 4, 0},
        {"triangle", &sweep.mCapTriangles, 3, 1},  {"quad", &sweep.mCapQuads, 4, 1}};
    std::vector<const Block*> written;
    std::vector<std::int64_t> wall_ids, cap_ids, cell_ids;
    std::int64_t global = 0;
    for (const Block& r_b : blocks) {
        if (r_b.pCells->empty())
            continue;
        NDArray conn = NDArray::Uninit(DType::Int64, {r_b.pCells->size(), r_b.mNodes});
        std::int64_t* pc = conn.As<std::int64_t>();
        for (std::size_t c = 0; c < r_b.pCells->size(); ++c) {
            for (std::size_t k = 0; k < r_b.mNodes; ++k)
                pc[r_b.mNodes * c + k] = (*r_b.pCells)[c].mNodes[k];
            (r_b.mRole == 3 ? cell_ids : r_b.mRole == 0 ? wall_ids : cap_ids).push_back(global++);
        }
        r_m.AddCellBlock(r_b.pType, std::move(conn));
        written.push_back(&r_b);
    }
    // The layer of every cell and face.
    {
        std::vector<NDArray> arrays;
        for (const Block* p_b : written) {
            NDArray a = NDArray::Uninit(DType::Int32, {p_b->pCells->size()});
            for (std::size_t c = 0; c < p_b->pCells->size(); ++c)
                a.As<std::int32_t>()[c] = (*p_b->pCells)[c].mLayer;
            arrays.push_back(std::move(a));
        }
        r_m.AddCellData(kBoundaryLayerName, std::move(arrays));
    }
    // The surface's own cell data, carried from each face to what grew from it.
    for (const std::string& name : rSurface.CellDataNames()) {
        if (name == kBoundaryLayerName)
            continue;
        const NDArray* p_first = nullptr;
        bool ok = true;
        for (std::size_t b = 0; b < rSurface.NumCellBlocks() && ok; ++b) {
            if (!face_block[b])
                continue;
            const NDArray& r_a = rSurface.CellData(name, b);
            if (!p_first)
                p_first = &r_a;
            else if (r_a.Dtype() != p_first->Dtype() ||
                     bl_row_bytes(r_a) != bl_row_bytes(*p_first) || r_a.Ndim() != p_first->Ndim())
                ok = false;
        }
        if (!p_first || !ok) {
            warn("cell data '" + name + "' differs between the surface's blocks and is dropped");
            continue;
        }
        // One array of every face's rows, then gathered per written block.
        std::vector<std::size_t> shape = p_first->Shape();
        shape[0] = nf;
        NDArray all = NDArray::Uninit(p_first->Dtype(), shape);
        const std::size_t row = bl_row_bytes(*p_first);
        for (std::size_t f = 0; f < nf; ++f)
            std::memcpy(all.Data() + f * row,
                        rSurface.CellData(name, source[f][0]).Data() + source[f][1] * row, row);
        std::vector<NDArray> arrays;
        for (const Block* p_b : written) {
            std::vector<std::int64_t> from(p_b->pCells->size());
            for (std::size_t c = 0; c < from.size(); ++c)
                from[c] = (*p_b->pCells)[c].mFace;
            arrays.push_back(bl_gather(all, from));
        }
        r_m.AddCellData(name, std::move(arrays));
    }
    for (const std::string& name : rSurface.PointDataNames())
        r_m.AddPointData(name, bl_gather(rSurface.PointData(name), sweep.mOrigin));
    for (const std::string& name : rSurface.FieldDataNames())
        r_m.AddFieldData(name, detail::data_owned_copy(rSurface.FieldData(name)));
    const auto column = [](const std::vector<std::int64_t>& rV) {
        NDArray a = NDArray::Uninit(DType::Int64, {rV.size()});
        std::copy(rV.begin(), rV.end(), a.As<std::int64_t>());
        return a;
    };
    // The surface's regions: a Cell region holds what grew from its faces
    // (cells, wall and cap), a Point region every copy of its points.
    {
        std::vector<std::int64_t> block_start(rSurface.NumCellBlocks() + 1, 0);
        for (std::size_t b = 0; b < rSurface.NumCellBlocks(); ++b)
            block_start[b + 1] =
                block_start[b] + static_cast<std::int64_t>(rSurface.Cells(b).NumCells());
        std::vector<std::int64_t> face_of_global(static_cast<std::size_t>(block_start.back()), -1);
        for (std::size_t f = 0; f < nf; ++f)
            face_of_global[static_cast<std::size_t>(block_start[source[f][0]]) + source[f][1]] =
                static_cast<std::int64_t>(f);
        std::size_t dropped = 0;
        for (std::size_t i = 0; i < rSurface.NumRegions(); ++i) {
            const Region& r_r = rSurface.Region(i);
            const NDArray& r_e = r_r.mEntries;
            std::vector<std::int64_t> entries;
            if (r_r.mKind == RegionKind::Cell) {
                std::vector<char> in_region(nf, 0);
                for (std::size_t k = 0; k < r_r.NumEntries(); ++k) {
                    const std::int64_t g = detail::read_int(r_e, k);
                    if (g >= 0 && static_cast<std::size_t>(g) < face_of_global.size() &&
                        face_of_global[static_cast<std::size_t>(g)] >= 0)
                        in_region[static_cast<std::size_t>(
                            face_of_global[static_cast<std::size_t>(g)])] = 1;
                }
                std::int64_t id = 0;
                for (const Block* p_b : written)
                    for (const auto& r_c : *p_b->pCells) {
                        if (in_region[static_cast<std::size_t>(r_c.mFace)])
                            entries.push_back(id);
                        ++id;
                    }
            } else if (r_r.mKind == RegionKind::Point) {
                std::vector<char> in_region(np, 0);
                for (std::size_t k = 0; k < r_r.NumEntries(); ++k) {
                    const std::int64_t q = detail::read_int(r_e, k);
                    if (q >= 0 && static_cast<std::size_t>(q) < np)
                        in_region[static_cast<std::size_t>(q)] = 1;
                }
                for (std::size_t q = 0; q < nout; ++q)
                    if (in_region[static_cast<std::size_t>(sweep.mOrigin[q])])
                        entries.push_back(static_cast<std::int64_t>(q));
            } else {
                ++dropped;
                continue;
            }
            r_m.AddRegion(Region(r_r.mName, r_r.mKind,
                                 r_r.mKind == RegionKind::Cell ? -1 : r_r.mDim, r_r.mTag,
                                 column(entries)));
        }
        if (dropped > 0)
            warn(std::to_string(dropped) + " side region(s) of the surface are dropped");
    }
    r_m.AddRegion(Region(kBoundaryLayerCells, RegionKind::Cell, 3, -1, column(cell_ids)));
    r_m.AddRegion(Region(kBoundaryLayerWall, RegionKind::Cell, 2, -1, column(wall_ids)));
    r_m.AddRegion(Region(kBoundaryLayerCap, RegionKind::Cell, 2, -1, column(cap_ids)));

    // The report.
    result.mNumWedges = static_cast<std::int64_t>(sweep.mWedges.size());
    result.mNumHexahedra = static_cast<std::int64_t>(sweep.mHexahedra.size());
    result.mNumPyramids = static_cast<std::int64_t>(sweep.mPyramids.size());
    result.mNumTetrahedra = static_cast<std::int64_t>(sweep.mTetrahedra.size());
    result.mNumCells =
        result.mNumWedges + result.mNumHexahedra + result.mNumPyramids + result.mNumTetrahedra;
    result.mMinScaledJacobian = result.mNumCells > 0 ? min_sj : 0.0;
    result.mMinThickness = std::numeric_limits<double>::infinity();
    result.mMaxThickness = 0.0;
    for (std::size_t p = 0; p < np; ++p) {
        if (!used[p])
            continue;
        result.mNumShrunk += sigma[p] < 1.0 ? 1 : 0;
        result.mNumCollapsed += sigma[p] > 0.0 ? 0 : 1;
        result.mNumNotVisible += not_visible[p] ? 1 : 0;
        result.mMinThickness = std::min(result.mMinThickness, sigma[p] * total);
        result.mMaxThickness = std::max(result.mMaxThickness, sigma[p] * total);
    }
    if (!std::isfinite(result.mMinThickness))
        result.mMinThickness = 0.0;
    {
        std::map<std::pair<std::int64_t, std::int64_t>, int> uses;
        for (const auto* p_cap : {&sweep.mCapTriangles, &sweep.mCapQuads})
            for (const auto& r_c : *p_cap) {
                const int k = r_c.mNodes[3] >= 0 ? 4 : 3;
                for (int i = 0; i < k; ++i) {
                    const std::int64_t a = r_c.mNodes[static_cast<std::size_t>(i)];
                    const std::int64_t b = r_c.mNodes[static_cast<std::size_t>((i + 1) % k)];
                    ++uses[{std::min(a, b), std::max(a, b)}];
                }
            }
        result.mCapClosed = !uses.empty();
        for (const auto& [e, n] : uses) {
            (void)e;
            if (n != 2)
                result.mCapClosed = false;
        }
    }
    if (result.mNumCollapsed > 0)
        warn(std::to_string(result.mNumCollapsed) +
             " points do not grow (their layers would fold or no direction sees all their "
             "faces); their cells are pyramids and tetrahedra");
    return result;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/boundary_layer.cpp =====
// ===== begin src/cpp/src/operations/clean.cpp =====
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <limits>
#include <string>
#include <vector>

// Project includes

// Project includes (private, not installed)

namespace meshioplusplus {

namespace {

using detail::Vec3;

// Row-preserving gather: out[j] = src[idx[j]] (whole trailing dims), dtype kept.
NDArray clean_gather_rows(const NDArray& rSrc, const std::vector<std::int64_t>& rIdx) {
    const std::vector<std::size_t>& shp = rSrc.Shape();
    std::size_t cols = 1;
    for (std::size_t d = 1; d < shp.size(); ++d)
        cols *= shp[d];
    std::vector<std::size_t> out_shape = shp;
    if (out_shape.empty())
        out_shape = {rIdx.size()};
    else
        out_shape[0] = rIdx.size();
    NDArray out = NDArray::Uninit(rSrc.Dtype(), out_shape);
    const std::size_t rb = cols * dtype_size(rSrc.Dtype());
    if (rb == 0)
        return out;
    const std::byte* s = rSrc.Data();
    std::byte* d = out.Data();
    parallel_for_bw(rIdx.size(), [&](std::size_t j) {
        std::memcpy(d + j * rb, s + static_cast<std::size_t>(rIdx[j]) * rb, rb);
    });
    return out;
}

// Keep-first weld (deterministic; detail/weld.hpp). Fills rWeldRep[g] in
// [0, W) and rRepSource[r] = the first global point that created
// representative r; returns W.
std::int64_t clean_build_weld_map(const NDArray& rPts, std::size_t n, std::size_t dim, double atol,
                                  std::vector<std::int64_t>& rWeldRep,
                                  std::vector<std::int64_t>& rRepSource) {
    const std::size_t ddim = std::min<std::size_t>(dim, 3);
    std::vector<double> xyz(n * 3, 0.0);
    detail::dispatch_dtype(rPts.Dtype(), [&]<class T>() {
        const T* src = rPts.As<T>();
        parallel_for_bw(n, [&](std::size_t g) {
            for (std::size_t d = 0; d < ddim; ++d)
                xyz[g * 3 + d] = static_cast<double>(src[g * dim + d]);
        });
    });
    detail::WeldMap weld = detail::weld_keep_first(xyz, n, ddim, atol);
    rWeldRep = std::move(weld.mRepOf);
    rRepSource = std::move(weld.mRepSource);
    return static_cast<std::int64_t>(rRepSource.size());
}

// Keep-first duplicate flags per cell: the non-degenerate cells' keys
// (`rKeys`, empty when duplicates are kept) grouped by the sort-based table
// (detail/slot_runs.hpp), every member of a run but its first flagged. The
// same cells a serial sweep through a hash set of keys drops.
std::vector<std::uint8_t> clean_later_duplicates(
    const std::vector<std::vector<std::int64_t>>& rKeys,
    const std::vector<std::uint8_t>& rDegenerate, std::size_t NumIds) {
    const std::size_t nc = rDegenerate.size();
    std::vector<std::uint8_t> duplicate(nc, 0);
    if (rKeys.empty())
        return duplicate;
    std::vector<std::uint64_t> live;
    live.reserve(nc);
    for (std::size_t c = 0; c < nc; ++c)
        if (!rDegenerate[c])
            live.push_back(c);
    const std::size_t nl = live.size();
    std::vector<std::uint64_t> length(nl);
    parallel_for_bw(nl, [&](std::size_t j) { length[j] = rKeys[live[j]].size(); });
    std::vector<std::uint64_t> offset(nl + 1);
    offset[nl] = parallel_exclusive_scan(length.data(), nl, offset.data(), std::uint64_t{0});
    std::vector<std::int64_t> values(offset[nl]);
    parallel_for(nl, [&](std::size_t j) {
        std::copy(rKeys[live[j]].begin(), rKeys[live[j]].end(), values.begin() + offset[j]);
    });
    const detail::SlotRuns runs = detail::group_int_rows(values, offset, NumIds);
    const std::vector<std::uint8_t> later = detail::later_duplicates(runs, nl);
    parallel_for_bw(nl, [&](std::size_t j) { duplicate[live[j]] = later[j]; });
    return duplicate;
}

}  // namespace

CleanResult clean(const Mesh& rMesh, const CleanOptions& rOpts) {
    const double eps = 1e-14;
    CleanResult res;

    const NDArray& points = rMesh.Points();
    const std::size_t n = rMesh.NumPoints();
    const std::size_t dim = rMesh.PointDim();

    // --- weld (or identity) -> welded representatives -----------------------
    std::vector<std::int64_t> weld_rep;    // global point -> rep in [0, W)
    std::vector<std::int64_t> rep_source;  // rep -> first contributing global point
    std::int64_t W = 0;
    if (rOpts.weld && n > 0 && dim > 0 && rOpts.atol > 0) {
        W = clean_build_weld_map(points, n, dim, rOpts.atol, weld_rep, rep_source);
    } else {
        weld_rep.resize(n);
        rep_source.resize(n);
        for (std::size_t g = 0; g < n; ++g) {
            weld_rep[g] = static_cast<std::int64_t>(g);
            rep_source[g] = static_cast<std::int64_t>(g);
        }
        W = static_cast<std::int64_t>(n);
    }
    res.mPointsWelded = static_cast<std::int64_t>(n) - W;

    // --- per-block cell filtering (rep-space connectivity) ------------------
    struct BlockOut {
        std::string type;
        int kind;  // 0 rect, 1 polygon, 2 polyhedron
        std::size_t npc = 0;
        std::vector<std::int64_t> rect_conn;                        // kind 0, flat (kept*npc)
        std::vector<std::vector<std::int64_t>> poly_rows;           // kind 1
        std::vector<std::vector<std::vector<std::int64_t>>> polyh;  // kind 2
        std::vector<std::int64_t> kept_cells;                       // old local indices kept
    };
    std::vector<BlockOut> blocks;
    std::vector<char> rep_used(static_cast<std::size_t>(W), 0);

    for (const auto cb : rMesh.CellRange()) {
        BlockOut bo;
        bo.type = std::string(cb.Type());
        const CellType ct = cell_type_from_name(bo.type);
        const std::size_t nc = cb.NumCells();

        if (cb.IsPolyhedron()) {
            bo.kind = 2;
            // Degenerate/duplicate detection for polyhedra (v9.16.1). Before
            // that these branches kept every cell unconditionally, so a welded
            // polyhedron that had collapsed to nothing survived `clean` while
            // the equivalent hexahedron did not.
            //
            // "Degenerate" here is: a face that lost corners to the weld and is
            // no longer a polygon, a face set that is no longer a closed
            // orientable surface, or a volume that is negligible next to the
            // cell's own size. "Duplicate" keys on the SET OF FACES (each face
            // a sorted node set, the whole cell then sorted), so two cells that
            // list the same faces in a different order or with different
            // per-face rotations still collide -- a plain sorted node list
            // could not tell a cube from a differently-connected solid on the
            // same eight nodes.
            //
            // Phase A (parallel): each cell's welded faces, its degenerate
            // test and its duplicate key -- the smallest id, the face count,
            // then every face's length and sorted distinct ids, faces sorted.
            std::vector<std::vector<std::vector<std::int64_t>>> cells(nc);
            std::vector<std::uint8_t> degenerate(nc, 0);
            std::vector<std::vector<std::int64_t>> keys(rOpts.drop_duplicate_cells ? nc : 0);
            parallel_for(nc, [&](std::size_t c) {
                std::vector<std::vector<std::int64_t>>& cell = cells[c];
                cell.resize(cb.NumFaces(c));
                bool degen = false;
                for (std::size_t f = 0; f < cb.NumFaces(c); ++f) {
                    auto face = cb.Face(c, f);
                    cell[f].reserve(face.second);
                    for (std::size_t k = 0; k < face.second; ++k)
                        cell[f].push_back(weld_rep[static_cast<std::size_t>(face.first[k])]);
                    if (rOpts.drop_degenerate) {
                        // Per-thread scratch: a sorted copy to count distinct nodes.
                        static thread_local std::vector<std::int64_t> u;
                        u.assign(cell[f].begin(), cell[f].end());
                        std::sort(u.begin(), u.end());
                        if (static_cast<std::size_t>(std::unique(u.begin(), u.end()) - u.begin()) <
                            3)
                            degen = true;  // the face collapsed below a triangle
                    }
                }
                if (rOpts.drop_degenerate && !degen) {
                    // Measure it through the shared kernel, on the WELDED nodes.
                    detail::CellRings rings;
                    std::vector<Vec3> coords;
                    rings.mFaceStart.push_back(0);
                    for (const std::vector<std::int64_t>& face : cell) {
                        for (std::int64_t id : face) {
                            std::uint32_t local = 0;
                            while (local < rings.mNodes.size() && rings.mNodes[local] != id)
                                ++local;
                            if (local == rings.mNodes.size()) {
                                rings.mNodes.push_back(id);
                                coords.push_back(detail::read_point(
                                    points, dim, rep_source[static_cast<std::size_t>(id)]));
                            }
                            rings.mFaceNodes.push_back(local);
                        }
                        rings.mFaceStart.push_back(
                            static_cast<std::uint32_t>(rings.mFaceNodes.size()));
                    }
                    if (detail::orient_rings(rings, coords.data()) ==
                        detail::RingOrientation::Unorientable) {
                        degen = true;
                    } else {
                        const detail::PolyMeasure pm = detail::poly_measure(rings, coords.data());
                        const double scale = pm.mSurfaceArea * std::sqrt(pm.mSurfaceArea);
                        if (!(std::abs(pm.mVolume) > eps * scale))
                            degen = true;
                    }
                }
                degenerate[c] = degen ? 1 : 0;
                if (degen || !rOpts.drop_duplicate_cells)
                    return;
                std::vector<std::vector<std::int64_t>> faces(cell);
                std::int64_t smallest = std::numeric_limits<std::int64_t>::max();
                for (std::vector<std::int64_t>& face : faces) {
                    std::sort(face.begin(), face.end());
                    face.erase(std::unique(face.begin(), face.end()), face.end());
                    if (!face.empty())
                        smallest = std::min(smallest, face.front());
                }
                std::sort(faces.begin(), faces.end());
                std::vector<std::int64_t>& key = keys[c];
                key.push_back(smallest);
                key.push_back(static_cast<std::int64_t>(faces.size()));
                for (const std::vector<std::int64_t>& face : faces) {
                    key.push_back(static_cast<std::int64_t>(face.size()));
                    key.insert(key.end(), face.begin(), face.end());
                }
            });
            // Phase B: keep-first duplicates among the non-degenerate cells.
            const std::vector<std::uint8_t> duplicate =
                clean_later_duplicates(keys, degenerate, static_cast<std::size_t>(W));
            // Phase C (serial, stored order): counts and the kept cells.
            for (std::size_t c = 0; c < nc; ++c) {
                if (degenerate[c]) {
                    ++res.mCellsDroppedDegenerate;
                    continue;
                }
                if (duplicate[c]) {
                    ++res.mCellsDroppedDuplicate;
                    continue;
                }
                for (const std::vector<std::int64_t>& face : cells[c])
                    for (std::int64_t r : face)
                        rep_used[static_cast<std::size_t>(r)] = 1;
                bo.polyh.push_back(std::move(cells[c]));
                bo.kept_cells.push_back(static_cast<std::int64_t>(c));
            }
        } else if (cb.IsRagged()) {
            bo.kind = 1;
            // Phase A (parallel): welded rows, the degenerate test and the
            // duplicate key (the sorted row).
            std::vector<std::vector<std::int64_t>> rows(nc);
            std::vector<std::uint8_t> degenerate(nc, 0);
            std::vector<std::vector<std::int64_t>> keys(rOpts.drop_duplicate_cells ? nc : 0);
            parallel_for(nc, [&](std::size_t c) {
                std::vector<std::int64_t>& row = rows[c];
                row.resize(cb.RowSize(c));
                for (std::size_t k = 0; k < cb.RowSize(c); ++k)
                    row[k] = weld_rep[static_cast<std::size_t>(cb.Row(c)[k])];
                if (rOpts.drop_degenerate) {
                    static thread_local std::vector<std::int64_t> u;
                    u.assign(row.begin(), row.end());
                    std::sort(u.begin(), u.end());
                    if (static_cast<std::size_t>(std::unique(u.begin(), u.end()) - u.begin()) < 3) {
                        degenerate[c] = 1;  // fewer than three distinct nodes is not a polygon
                        return;
                    }
                    static thread_local std::vector<Vec3> coords;
                    coords.resize(row.size());
                    for (std::size_t k = 0; k < row.size(); ++k)
                        coords[k] = detail::read_point(
                            points, dim, rep_source[static_cast<std::size_t>(row[k])]);
                    if (!(detail::polygon_area(coords.data(), coords.size()) > eps)) {
                        degenerate[c] = 1;
                        return;
                    }
                }
                if (rOpts.drop_duplicate_cells) {
                    keys[c] = row;
                    std::sort(keys[c].begin(), keys[c].end());
                }
            });
            const std::vector<std::uint8_t> duplicate =
                clean_later_duplicates(keys, degenerate, static_cast<std::size_t>(W));
            for (std::size_t c = 0; c < nc; ++c) {
                if (degenerate[c]) {
                    ++res.mCellsDroppedDegenerate;
                    continue;
                }
                if (duplicate[c]) {
                    ++res.mCellsDroppedDuplicate;
                    continue;
                }
                for (std::int64_t r : rows[c])
                    rep_used[static_cast<std::size_t>(r)] = 1;
                bo.poly_rows.push_back(std::move(rows[c]));
                bo.kept_cells.push_back(static_cast<std::int64_t>(c));
            }
        } else {
            bo.kind = 0;
            const NDArray& conn = cb.Conn();
            const std::size_t npc = cb.NodesPerCell();
            bo.npc = npc;
            const int corner_count = detail::cell_corner_count(ct);
            const int cdim = cell_type_dimension(ct);

            // Phase A (parallel): welded rows and the degenerate test, per cell.
            std::vector<std::int64_t> rows(nc * npc);
            std::vector<std::uint8_t> degenerate(nc, 0);
            parallel_for(nc, [&](std::size_t c) {
                std::int64_t* row = rows.data() + c * npc;
                for (std::size_t k = 0; k < npc; ++k)
                    row[k] =
                        weld_rep[static_cast<std::size_t>(detail::read_int(conn, c * npc + k))];
                if (!rOpts.drop_degenerate)
                    return;
                // degenerate: repeated corner node, or near-zero measure.
                const int cc = corner_count > 0 ? corner_count : static_cast<int>(npc);
                for (int i = 0; i < cc; ++i)
                    for (int j = i + 1; j < cc; ++j)
                        if (row[i] == row[j]) {
                            degenerate[c] = 1;
                            return;
                        }
                if (corner_count > 0) {
                    static thread_local std::vector<Vec3> coords;
                    coords.resize(static_cast<std::size_t>(corner_count));
                    for (int i = 0; i < corner_count; ++i)
                        coords[static_cast<std::size_t>(i)] = detail::read_point(
                            points, dim, rep_source[static_cast<std::size_t>(row[i])]);
                    double measure = std::nan("");
                    if (cdim == 2)
                        measure = detail::polygon_area(coords.data(),
                                                       static_cast<std::size_t>(corner_count));
                    else if (cdim == 3)
                        measure = std::abs(detail::cell_volume_from_corners(coords.data(), ct));
                    if (!std::isnan(measure) && measure < eps)
                        degenerate[c] = 1;
                }
            });

            // Phase B: exact duplicates, keep-first. A kept cell is a
            // duplicate when an earlier non-degenerate cell has the same
            // sorted connectivity: group those cells' sorted rows
            // (detail/slot_runs.hpp) and drop every member of a run but its
            // first.
            std::vector<std::uint8_t> duplicate(nc, 0);
            if (rOpts.drop_duplicate_cells && npc > 0) {
                std::vector<std::uint64_t> live;
                live.reserve(nc);
                for (std::size_t c = 0; c < nc; ++c)
                    if (!degenerate[c])
                        live.push_back(c);
                std::vector<std::int64_t> sorted(live.size() * npc);
                parallel_for(live.size(), [&](std::size_t j) {
                    const std::int64_t* row = rows.data() + live[j] * npc;
                    std::int64_t* out = sorted.data() + j * npc;
                    std::copy(row, row + npc, out);
                    std::sort(out, out + npc);
                });
                std::vector<std::uint64_t> slots(live.size());
                for (std::size_t j = 0; j < live.size(); ++j)
                    slots[j] = j;
                const std::size_t nreps = rep_source.size();
                const detail::SlotRuns runs = detail::group_slots(
                    slots, nreps + 1,
                    [&](std::uint64_t j) {
                        const std::int64_t lo = sorted[j * npc];
                        return lo >= 0 && static_cast<std::size_t>(lo) < nreps
                                   ? static_cast<std::size_t>(lo)
                                   : nreps;
                    },
                    [&](std::uint64_t x, std::uint64_t y) {
                        return std::lexicographical_compare(
                            sorted.data() + x * npc, sorted.data() + (x + 1) * npc,
                            sorted.data() + y * npc, sorted.data() + (y + 1) * npc);
                    });
                parallel_for(runs.NumRuns(), [&](std::size_t r) {
                    for (const std::uint64_t* q = runs.Begin(r) + 1; q < runs.End(r); ++q)
                        duplicate[live[*q]] = 1;
                });
            }

            // Phase C (serial, stored order): counts and the kept rows.
            for (std::size_t c = 0; c < nc; ++c) {
                if (degenerate[c]) {
                    ++res.mCellsDroppedDegenerate;
                    continue;
                }
                if (duplicate[c]) {
                    ++res.mCellsDroppedDuplicate;
                    continue;
                }
                const std::int64_t* row = rows.data() + c * npc;
                for (std::size_t k = 0; k < npc; ++k) {
                    bo.rect_conn.push_back(row[k]);
                    rep_used[static_cast<std::size_t>(row[k])] = 1;
                }
                bo.kept_cells.push_back(static_cast<std::int64_t>(c));
            }
        }
        blocks.push_back(std::move(bo));
    }

    // --- point compaction (orphan removal) ----------------------------------
    std::vector<std::int64_t> new_point(static_cast<std::size_t>(W), -1);
    std::vector<std::int64_t> kept_reps;  // reps surviving, ascending
    for (std::int64_t r = 0; r < W; ++r) {
        if (!rOpts.remove_orphans || rep_used[static_cast<std::size_t>(r)]) {
            new_point[static_cast<std::size_t>(r)] = static_cast<std::int64_t>(kept_reps.size());
            kept_reps.push_back(r);
        }
    }
    const std::int64_t P = static_cast<std::int64_t>(kept_reps.size());
    res.mPointsRemovedOrphan = W - P;

    // point gather indices (output row -> source global point, keep-first).
    std::vector<std::int64_t> point_src(kept_reps.size());
    for (std::size_t j = 0; j < kept_reps.size(); ++j)
        point_src[j] = rep_source[static_cast<std::size_t>(kept_reps[j])];

    // --- emit points + point_data ------------------------------------------
    Mesh& out = res.mMesh;
    {
        NDArray newpts = NDArray::Uninit(points.Dtype(), {static_cast<std::size_t>(P), dim});
        if (P > 0 && dim > 0) {
            const std::size_t rb = dim * dtype_size(points.Dtype());
            const std::byte* s = points.Data();
            std::byte* d = newpts.Data();
            parallel_for_bw(point_src.size(), [&](std::size_t j) {
                std::memcpy(d + j * rb, s + static_cast<std::size_t>(point_src[j]) * rb, rb);
            });
        }
        out.AssignPoints(std::move(newpts));
    }
    for (const std::string& name : rMesh.PointDataNames()) {
        const NDArray& a = rMesh.PointData(name);
        const std::size_t rows = a.Shape().empty() ? 0 : a.Shape()[0];
        if (rows == n)
            out.AddPointData(name, clean_gather_rows(a, point_src));
        else {
            NDArray c = a;
            c.MakeOwned();
            out.AddPointData(name, std::move(c));
        }
    }

    // --- emit cells (remap rep-space -> final point index) ------------------
    res.mCellMaps.clear();
    std::size_t bi = 0;
    for (const auto cb : rMesh.CellRange()) {
        BlockOut& bo = blocks[bi];
        // cell map: old local -> new local (or -1).
        NDArray cmap = NDArray::Uninit(DType::Int64, {cb.NumCells()});
        std::int64_t* cm = cmap.As<std::int64_t>();
        parallel_for_bw(cb.NumCells(), [&](std::size_t c) { cm[c] = -1; });
        parallel_for_bw(bo.kept_cells.size(), [&](std::size_t j) {
            cm[static_cast<std::size_t>(bo.kept_cells[j])] = static_cast<std::int64_t>(j);
        });
        res.mCellMaps.push_back(std::move(cmap));

        if (bo.kind == 0) {
            const std::size_t kept = bo.kept_cells.size();
            NDArray conn = NDArray::Uninit(DType::Int64, {kept, bo.npc});
            std::int64_t* cd = conn.As<std::int64_t>();
            parallel_for_bw(bo.rect_conn.size(), [&](std::size_t i) {
                cd[i] = new_point[static_cast<std::size_t>(bo.rect_conn[i])];
            });
            out.AddCellBlock(bo.type, std::move(conn));
        } else if (bo.kind == 1) {
            parallel_for_bw(bo.poly_rows.size(), [&](std::size_t r) {
                for (std::int64_t& v : bo.poly_rows[r])
                    v = new_point[static_cast<std::size_t>(v)];
            });
            out.AddPolygonBlock(bo.type, std::move(bo.poly_rows));
        } else {
            parallel_for_bw(bo.polyh.size(), [&](std::size_t ci) {
                for (auto& face : bo.polyh[ci])
                    for (std::int64_t& v : face)
                        v = new_point[static_cast<std::size_t>(v)];
            });
            out.AddPolyhedronBlock(bo.type, std::move(bo.polyh));
        }
        ++bi;
    }

    // --- emit cell_data (gather surviving cells per block) ------------------
    for (const std::string& name : rMesh.CellDataNames()) {
        std::vector<NDArray> outblocks;
        std::size_t b = 0;
        for (const auto cb : rMesh.CellRange()) {
            const NDArray& src = rMesh.CellData(name, b);
            const std::size_t rows = src.Shape().empty() ? 0 : src.Shape()[0];
            if (rows == cb.NumCells())
                outblocks.push_back(clean_gather_rows(src, blocks[b].kept_cells));
            else {
                NDArray c = src;
                c.MakeOwned();
                outblocks.push_back(std::move(c));
            }
            ++b;
        }
        out.AddCellData(name, std::move(outblocks));
    }
    for (const std::string& name : rMesh.FieldDataNames()) {
        NDArray c = rMesh.FieldData(name);
        c.MakeOwned();
        out.AddFieldData(name, std::move(c));
    }

    // --- point map (input global -> output point, or -1) --------------------
    res.mPointMap = NDArray::Uninit(DType::Int64, {n});
    std::int64_t* pm = res.mPointMap.As<std::int64_t>();
    parallel_for_bw(
        n, [&](std::size_t g) { pm[g] = new_point[static_cast<std::size_t>(weld_rep[g])]; });

    // --- named regions ------------------------------------------------------
    // Block structure is 1:1 and cell types are unchanged, so this is a Direct
    // map and side-set facets survive along with their cells.
    {
        detail::RegionRemap rmap;
        rmap.pPointMap = &res.mPointMap;
        rmap.mCellMapKind = detail::CellMapKind::Direct;
        rmap.pCellMaps = &res.mCellMaps;
        rmap.mOpName = "clean";
        detail::remap_regions(rMesh, out, rmap);
    }

    return res;
}

}  // namespace meshioplusplus
// ===== end src/cpp/src/operations/clean.cpp =====
// ===== begin src/cpp/src/operations/conservative_interpolate.cpp =====
#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

// Project includes

namespace meshioplusplus {

namespace {

constexpr const char* kProxySuffix = "__cons_interp_proxy__";

// Effective topological dimension of a block, matching surface.cpp's
// surface_effective_dim: a polyhedron's type name may be parameterized (e.g.
// "polyhedron12") and so miss the cell_type_from_name table.
int cons_effective_dim(const Mesh::CellView& rBlock) {
    if (rBlock.IsPolyhedron())
        return 3;
    return cell_type_dimension(cell_type_from_name(rBlock.Type()));
}

// The mesh's maximum effective cell-block dimension, or -1 if it has none.
int cons_max_dim(const Mesh& rMesh) {
    int max_dim = -1;
    for (const auto cb : rMesh.CellRange()) {
        if (cb.NumCells() == 0)
            continue;
        max_dim = std::max(max_dim, cons_effective_dim(cb));
    }
    return max_dim;
}

// -------------------------------------------------------------------------
// Simplex extraction: flatten every "want"-typed (triangle/tetra) block of a
// simplexified mesh into one flat connectivity array, plus each simplex's
// GLOBAL parent-cell index in the *original* (pre-simplexify) mesh, resolved
// via that mesh's own block_bases + the simplexified mesh's own
// "convert:parent_cell" cell_data (per-output-cell, index within its own
// block -- valid here because convert_cells preserves block structure 1:1).
// -------------------------------------------------------------------------
struct ConsSimplices {
    std::vector<std::int64_t> mConn;    ///< nv per simplex, ascending block-then-cell order
    std::vector<std::int64_t> mParent;  ///< one per simplex: global cell index in the original mesh
    std::size_t mNv = 0;                ///< 3 (triangle) or 4 (tetra)
};

ConsSimplices cons_extract_simplices(const Mesh& rOriginal, const Mesh& rSimplexMesh,
                                     bool wantTet) {
    ConsSimplices out;
    out.mNv = wantTet ? 4 : 3;
    const std::string want = wantTet ? "tetra" : "triangle";
    const std::vector<std::int64_t> bases = detail::block_bases(rOriginal);
    const bool has_parent = rSimplexMesh.HasCellData("convert:parent_cell");

    std::size_t block_idx = 0;
    for (const auto cb : rSimplexMesh.CellRange()) {
        if (cb.Type() == want && cb.NumCells() > 0) {
            const NDArray& conn = cb.Conn();
            const std::size_t n = cb.NumCells() * out.mNv;
            const std::size_t base = out.mConn.size();
            out.mConn.resize(base + n);
            for (std::size_t j = 0; j < n; ++j)
                out.mConn[base + j] = detail::read_int(conn, j);

            const std::size_t pbase = out.mParent.size();
            out.mParent.resize(pbase + cb.NumCells());
            if (has_parent) {
                const NDArray& pc = rSimplexMesh.CellData("convert:parent_cell", block_idx);
                for (std::size_t c = 0; c < cb.NumCells(); ++c)
                    out.mParent[pbase + c] = bases[block_idx] + detail::read_int(pc, c);
            } else {
                // 1:1 pass-through block (no children were ever created for
                // it) -- the local row index is already the parent's own.
                for (std::size_t c = 0; c < cb.NumCells(); ++c)
                    out.mParent[pbase + c] = bases[block_idx] + static_cast<std::int64_t>(c);
            }
        }
        ++block_idx;
    }
    return out;
}

// -------------------------------------------------------------------------
// Small vector helpers on top of detail::Vec3 -- plain doubles, since the
// clip kernel never needs anything the mesh's own dtype provides.
// -------------------------------------------------------------------------

double cons_signed_tet_volume(const detail::Vec3 v[4]) {
    return detail::triple_product(detail::vec3_sub(v[1], v[0]), detail::vec3_sub(v[2], v[0]),
                                  detail::vec3_sub(v[3], v[0])) /
           6.0;
}

// Positively-oriented copy of a tetra's 4 corners (swap the first two if the
// signed volume came out negative). The clip kernel's face table assumes
// this orientation, so this removes any dependence on convert_cells'
// simplexification always producing positive volumes.
std::array<detail::Vec3, 4> cons_oriented_tet(const detail::Vec3 v[4]) {
    if (cons_signed_tet_volume(v) < 0.0)
        return {v[1], v[0], v[2], v[3]};
    return {v[0], v[1], v[2], v[3]};
}

// Sutherland-Hodgman clip of a (planar or non-planar-but-convex) vertex ring
// against the half-space {p : dot(p - planePoint, planeNormal) <= 0}, i.e.
// "inside" is the non-positive side. Every newly interpolated (on-plane)
// vertex is additionally appended to *pNewPts when it is not null -- the
// mechanism the 3D tetra-tetra clip uses to collect the chord bounding its
// new capping face. Works unmodified for the 2D triangle-triangle clip too
// (called with pNewPts == nullptr there, since a planar 2D clip needs no
// capping step).
std::vector<detail::Vec3> cons_clip_ring(const std::vector<detail::Vec3>& rPoly,
                                         const detail::Vec3& rPlanePoint,
                                         const detail::Vec3& rPlaneNormal,
                                         std::vector<detail::Vec3>* pNewPts, double EpsSide = 0.0) {
    if (rPoly.empty())
        return {};
    const std::size_t n = rPoly.size();
    std::vector<detail::Vec3> out;
    out.reserve(n + 1);
    auto s = [&](const detail::Vec3& p) {
        return detail::vec3_dot(detail::vec3_sub(p, rPlanePoint), rPlaneNormal);
    };
    // A vertex within EpsSide of the plane is ON it, and on-plane counts as
    // inside. The 3D clip's capping step classifies with the same tolerance;
    // a vertex that is on the plane up to rounding (a coordinate like 1/3)
    // but clipped here as outside left a sliver with no cap over it.
    for (std::size_t i = 0; i < n; ++i) {
        const detail::Vec3& cur = rPoly[i];
        const detail::Vec3& prev = rPoly[(i + n - 1) % n];
        const double s_cur = s(cur);
        const double s_prev = s(prev);
        const bool cur_in = s_cur <= EpsSide;
        const bool prev_in = s_prev <= EpsSide;
        if (cur_in != prev_in) {
            // The inside end of the crossing edge: when it lies on the plane
            // it IS the crossing point (interpolating would overshoot it).
            const detail::Vec3& in_end = cur_in ? cur : prev;
            const double s_in = cur_in ? s_cur : s_prev;
            const detail::Vec3 ip =
                std::abs(s_in) <= EpsSide
                    ? in_end
                    : detail::vec3_add(prev, detail::vec3_scale(detail::vec3_sub(cur, prev),
                                                                s_prev / (s_prev - s_cur)));
            out.push_back(ip);
            if (pNewPts != nullptr)
                pNewPts->push_back(ip);
        }
        if (cur_in)
            out.push_back(cur);
    }
    return out;
}

// Exact overlap area of two triangles, in the xy-plane (z ignored) -- the
// same planar assumption interpolate.cpp's Barycentric triangle path already
// documents. Both inputs are first made CCW so the source triangle's three
// edges define three consistent "inside" half-planes.
double cons_clip_triangle_triangle_area(const detail::Vec3 tgtIn[3], const detail::Vec3 srcIn[3]) {
    auto ccw = [](const detail::Vec3 t[3]) -> std::array<detail::Vec3, 3> {
        const double a2 =
            (t[1][0] - t[0][0]) * (t[2][1] - t[0][1]) - (t[1][1] - t[0][1]) * (t[2][0] - t[0][0]);
        const detail::Vec3 p0{t[0][0], t[0][1], 0.0};
        const detail::Vec3 p1{t[1][0], t[1][1], 0.0};
        const detail::Vec3 p2{t[2][0], t[2][1], 0.0};
        if (a2 < 0.0)
            return {p0, p2, p1};
        return {p0, p1, p2};
    };
    const std::array<detail::Vec3, 3> tgt = ccw(tgtIn);
    const std::array<detail::Vec3, 3> src = ccw(srcIn);

    std::vector<detail::Vec3> poly{tgt[0], tgt[1], tgt[2]};
    for (int e = 0; e < 3 && !poly.empty(); ++e) {
        const detail::Vec3& a = src[static_cast<std::size_t>(e)];
        const detail::Vec3& b = src[static_cast<std::size_t>((e + 1) % 3)];
        // Left of a->b (CCW inside) written as a plane test: s <= 0 iff
        // cross_z(b - a, p - a) >= 0.
        const detail::Vec3 normal{b[1] - a[1], a[0] - b[0], 0.0};
        poly = cons_clip_ring(poly, a, normal, nullptr);
    }
    if (poly.size() < 3)
        return 0.0;
    return detail::polygon_area(poly.data(), poly.size());
}

// Exact overlap volume of two tetrahedra. Both operands are always
// tetrahedra (guaranteed by convert_cells(Simplexify)), which bounds this to
// a genuine but tractable 3D convex-polytope clip: the source tet's own 4
// faces are clipped against the target tet's 4 half-spaces in turn, and each
// clip's new boundary chord is capped with a fan-triangulated, angle-sorted
// polygon -- never a general polyhedron-polyhedron clipper. See the header
// doc comment for the full algorithm description.
double cons_clip_tetra_tetra_volume(const detail::Vec3 tgtIn[4], const detail::Vec3 srcIn[4]) {
    // Recentre on the source tet's own corner average before any arithmetic
    // -- poly_measure's own numerical-stability lesson: this keeps the final
    // divergence-theorem sum (and every plane-classification dot product
    // along the way) accurate for a mesh far from the origin.
    detail::Vec3 c{0.0, 0.0, 0.0};
    for (int i = 0; i < 4; ++i)
        c = detail::vec3_add(c, srcIn[i]);
    c = detail::vec3_scale(c, 0.25);

    detail::Vec3 src_raw[4];
    detail::Vec3 tgt_raw[4];
    for (int i = 0; i < 4; ++i) {
        src_raw[i] = detail::vec3_sub(srcIn[i], c);
        tgt_raw[i] = detail::vec3_sub(tgtIn[i], c);
    }
    const std::array<detail::Vec3, 4> src = cons_oriented_tet(src_raw);
    const std::array<detail::Vec3, 4> tgt = cons_oriented_tet(tgt_raw);

    // Dedup tolerance for chord endpoints, scaled to the source tet's own
    // size (recentring only shifted the origin, not the physical scale).
    double scale = 0.0;
    for (int i = 0; i < 4; ++i)
        for (int j = i + 1; j < 4; ++j)
            scale = std::max(scale,
                             detail::vec3_norm(detail::vec3_sub(src[static_cast<std::size_t>(i)],
                                                                src[static_cast<std::size_t>(j)])));
    const double eps_abs = 1e-9 * scale;
    const double eps_abs2 = eps_abs * eps_abs;

    // The outward-wound tetra face table (detail/cell_faces.hpp's own rows),
    // valid for a positively-oriented tetra.
    static constexpr int kFaces[4][3] = {{0, 1, 3}, {1, 2, 3}, {2, 0, 3}, {0, 2, 1}};

    std::vector<std::array<detail::Vec3, 3>> tris;
    tris.reserve(4);
    for (const auto& f : kFaces)
        tris.push_back({src[static_cast<std::size_t>(f[0])], src[static_cast<std::size_t>(f[1])],
                        src[static_cast<std::size_t>(f[2])]});

    for (const auto& f : kFaces) {
        if (tris.empty())
            break;
        const detail::Vec3& p0 = tgt[static_cast<std::size_t>(f[0])];
        const detail::Vec3& p1 = tgt[static_cast<std::size_t>(f[1])];
        const detail::Vec3& p2 = tgt[static_cast<std::size_t>(f[2])];
        const detail::Vec3 normal =
            detail::vec3_cross(detail::vec3_sub(p1, p0), detail::vec3_sub(p2, p0));

        // Distance-like test value of a point against this plane, and the
        // tolerance under which a point counts as lying ON it.
        auto side = [&](const detail::Vec3& rP) {
            return detail::vec3_dot(detail::vec3_sub(rP, p0), normal);
        };
        const double eps_side = 1e-12 * scale * detail::vec3_norm(normal);
        bool cuts = false;
        for (const auto& t : tris)
            for (const detail::Vec3& p : t)
                cuts = cuts || side(p) > eps_side;

        std::vector<std::array<detail::Vec3, 3>> kept;
        std::vector<detail::Vec3> chord;
        for (const auto& t : tris) {
            std::vector<detail::Vec3> new_pts;
            const std::vector<detail::Vec3> ring =
                cons_clip_ring({t[0], t[1], t[2]}, p0, normal, &new_pts, eps_side);
            for (const detail::Vec3& p : new_pts)
                chord.push_back(p);
            for (std::size_t i = 1; i + 1 < ring.size(); ++i)
                kept.push_back({ring[0], ring[i], ring[i + 1]});
        }
        tris = std::move(kept);
        if (!cuts)
            continue;  // nothing removed: no hole, and capping would double a face
        // The hole's boundary also runs through every kept vertex that lies ON
        // the plane -- a corner the clip kept rather than interpolated (s == 0
        // is "inside"), which aligned meshes produce all the time. Leaving it
        // out of the cap shrank the cap and under-measured the overlap.
        for (const auto& t : tris)
            for (const detail::Vec3& p : t)
                if (std::abs(side(p)) <= eps_side)
                    chord.push_back(p);

        // Cap the new hole (if this half-space actually cut anything) with
        // the dedup'd chord, angle-sorted around the cutting plane's own 2D
        // basis and fan-triangulated -- always valid, since the cap of a
        // convex polytope clipped by one more plane is itself convex.
        std::vector<detail::Vec3> uniq;
        for (const detail::Vec3& p : chord) {
            bool dup = false;
            for (const detail::Vec3& q : uniq) {
                if (detail::vec3_norm_sq(detail::vec3_sub(p, q)) < eps_abs2) {
                    dup = true;
                    break;
                }
            }
            if (!dup)
                uniq.push_back(p);
        }
        if (uniq.size() >= 3) {
            detail::Vec3 cc{0.0, 0.0, 0.0};
            for (const detail::Vec3& p : uniq)
                cc = detail::vec3_add(cc, p);
            cc = detail::vec3_scale(cc, 1.0 / static_cast<double>(uniq.size()));

            const detail::Vec3 w = detail::vec3_normalize(normal);
            const detail::Vec3 arbitrary =
                std::abs(w[0]) < 0.9 ? detail::Vec3{1.0, 0.0, 0.0} : detail::Vec3{0.0, 1.0, 0.0};
            const detail::Vec3 u = detail::vec3_normalize(
                detail::vec3_sub(arbitrary, detail::vec3_scale(w, detail::vec3_dot(arbitrary, w))));
            const detail::Vec3 v = detail::vec3_cross(w, u);

            std::vector<std::pair<double, std::size_t>> order(uniq.size());
            for (std::size_t i = 0; i < uniq.size(); ++i) {
                const detail::Vec3 d = detail::vec3_sub(uniq[i], cc);
                order[i] = {std::atan2(detail::vec3_dot(d, v), detail::vec3_dot(d, u)), i};
            }
            // Explicit, order-independent tie-break: ascending build index on
            // an exact angle tie (near-coplanar chord points), never
            // insertion order from an unordered container.
            std::sort(order.begin(), order.end(), [](const auto& a, const auto& b) {
                if (a.first != b.first)
                    return a.first < b.first;
                return a.second < b.second;
            });
            for (std::size_t i = 1; i + 1 < order.size(); ++i)
                tris.push_back(
                    {uniq[order[0].second], uniq[order[i].second], uniq[order[i + 1].second]});
        }
    }

    double vol6 = 0.0;
    for (const auto& t : tris)
        vol6 += detail::triple_product(t[0], t[1], t[2]);
    const double vol = vol6 / 6.0;
    return vol > 0.0 ? vol : 0.0;
}

// -------------------------------------------------------------------------
// The shared geometric overlap structure -- purely a function of the two
// meshes' geometry, independent of every array. Built once per call and
// reused for every requested array (direct cell_data and point-composed
// proxies alike).
// -------------------------------------------------------------------------
struct ConsOverlap {
    // Per target simplex: (source simplex id, overlap measure), deduplicated
    // and sorted ascending by source simplex id (broad-phase determinism).
    std::vector<std::vector<std::pair<std::int64_t, double>>> mBySimplex;
    ConsSimplices mSrc;
    ConsSimplices mTgt;
};

// A simplex's own (unclipped) measure, from its own corner coordinates.
double cons_own_measure(const detail::Vec3* pCorners, std::size_t nv) {
    if (nv == 3)
        return detail::polygon_area(pCorners, 3);
    detail::Vec3 v[4] = {pCorners[0], pCorners[1], pCorners[2], pCorners[3]};
    const double vol = detail::cell_volume_from_corners(v, CellType::Tetra);
    return std::abs(vol);
}

ConsOverlap cons_build_overlap(const Mesh& rSource, const Mesh& rTarget, const Mesh& rSourceSimp,
                               const Mesh& rTargetSimp, bool wantTet) {
    ConsOverlap out;
    out.mSrc = cons_extract_simplices(rSource, rSourceSimp, wantTet);
    out.mTgt = cons_extract_simplices(rTarget, rTargetSimp, wantTet);
    const std::size_t nv = out.mSrc.mNv;
    const std::size_t nsrc = out.mSrc.mParent.size();
    const std::size_t ntgt = out.mTgt.mParent.size();
    out.mBySimplex.resize(ntgt);
    if (nsrc == 0 || ntgt == 0)
        return out;

    const NDArray& spts = rSourceSimp.Points();
    const std::size_t sdim = rSourceSimp.PointDim();
    const NDArray& tpts = rTargetSimp.Points();
    const std::size_t tdim = rTargetSimp.PointDim();

    auto scoord = [&](std::size_t simp, std::size_t corner) {
        return detail::read_point(spts, sdim, out.mSrc.mConn[simp * nv + corner]);
    };
    auto tcoord = [&](std::size_t simp, std::size_t corner) {
        return detail::read_point(tpts, tdim, out.mTgt.mConn[simp * nv + corner]);
    };

    // Broad phase: quantize every source simplex's own bounding box into a
    // shared grid (interp_cell_size's cbrt-free sizing rule, kept local since
    // anon-namespace helpers cannot be shared across files).
    double lo[3], hi[3];
    {
        const detail::Vec3 first = scoord(0, 0);
        for (int d = 0; d < 3; ++d)
            lo[d] = hi[d] = first[d];
        for (std::size_t s = 0; s < nsrc; ++s)
            for (std::size_t k = 0; k < nv; ++k) {
                const detail::Vec3 p = scoord(s, k);
                for (int d = 0; d < 3; ++d) {
                    if (p[d] < lo[d])
                        lo[d] = p[d];
                    if (p[d] > hi[d])
                        hi[d] = p[d];
                }
            }
    }
    double max_extent = 0.0;
    for (int d = 0; d < 3; ++d)
        max_extent = std::max(max_extent, hi[d] - lo[d]);
    std::int64_t r = 1;
    while (r * r * r < static_cast<std::int64_t>(nsrc))
        ++r;
    const double cell = max_extent > 0.0 ? max_extent / static_cast<double>(r) : 1.0;

    detail::SpatialGrid grid(cell);
    std::vector<std::pair<detail::GridKey, detail::GridKey>> src_boxes(nsrc);
    parallel_for(nsrc, [&](std::size_t s) {
        detail::Vec3 blo = scoord(s, 0);
        detail::Vec3 bhi = blo;
        for (std::size_t k = 1; k < nv; ++k) {
            const detail::Vec3 p = scoord(s, k);
            for (int d = 0; d < 3; ++d) {
                if (p[d] < blo[d])
                    blo[d] = p[d];
                if (p[d] > bhi[d])
                    bhi[d] = p[d];
            }
        }
        src_boxes[s] = {grid.KeyOf(blo.data()), grid.KeyOf(bhi.data())};
    });
    for (std::size_t s = 0; s < nsrc; ++s)
        grid.InsertBox(src_boxes[s].first, src_boxes[s].second, static_cast<std::int64_t>(s));

    // Narrow phase, independent per target simplex -> parallel-safe.
    parallel_for(ntgt, [&](std::size_t t) {
        detail::Vec3 t_corners[4];
        for (std::size_t k = 0; k < nv; ++k)
            t_corners[k] = tcoord(t, k);
        detail::Vec3 tblo = t_corners[0];
        detail::Vec3 tbhi = t_corners[0];
        for (std::size_t k = 1; k < nv; ++k)
            for (int d = 0; d < 3; ++d) {
                if (t_corners[k][d] < tblo[d])
                    tblo[d] = t_corners[k][d];
                if (t_corners[k][d] > tbhi[d])
                    tbhi[d] = t_corners[k][d];
            }

        std::vector<std::int64_t> cand;
        grid.ForEachInBox(grid.KeyOf(tblo.data()), grid.KeyOf(tbhi.data()),
                          [&](const std::vector<std::int64_t>& rIds) {
                              cand.insert(cand.end(), rIds.begin(), rIds.end());
                          });
        std::sort(cand.begin(), cand.end());
        cand.erase(std::unique(cand.begin(), cand.end()), cand.end());

        auto& result = out.mBySimplex[t];
        result.reserve(cand.size());
        for (std::int64_t s : cand) {
            detail::Vec3 s_corners[4];
            for (std::size_t k = 0; k < nv; ++k)
                s_corners[k] = scoord(static_cast<std::size_t>(s), k);
            const double measure = nv == 3 ? cons_clip_triangle_triangle_area(t_corners, s_corners)
                                           : cons_clip_tetra_tetra_volume(t_corners, s_corners);
            if (measure > 0.0)
                result.push_back({s, measure});
        }
    });

    return out;
}

// -------------------------------------------------------------------------
// Accumulate one requested array's conservative remap: reads component
// values from `rValueSource.CellData(rSourceName, block)` (resolved through
// the source simplex's own global-parent index, indexing the block the
// *original* source mesh assigns that parent to), scatters
// `value * measure` into per-target-cell accumulators using `rOverlap`, and
// returns one Float64 NDArray per target cell block.
// -------------------------------------------------------------------------
std::vector<NDArray> cons_accumulate_array(const Mesh& rTarget, const ConsOverlap& rOverlap,
                                           const Mesh& rValueSource, const std::string& rSourceName,
                                           const std::vector<double>& rCoveredMeasure,
                                           const std::vector<double>& rOwnMeasure, double eps_rel,
                                           double defaultValue, std::vector<char>& rUncovered) {
    const std::size_t comps = data_num_components(rValueSource.CellData(rSourceName, 0));
    const std::vector<std::int64_t> src_bases = detail::block_bases(rValueSource);
    const std::size_t total_tgt =
        static_cast<std::size_t>(detail::total_cells(detail::block_bases(rTarget)));

    std::vector<double> numerator(total_tgt * comps, 0.0);

    // Serial scatter (target simplex -> its original target cell), ascending
    // target-simplex index -- floating-point addition is not associative, so
    // this many-to-few fold must not be parallelised (data_average.cpp's
    // cell-to-point averaging documents the identical rule).
    for (std::size_t t = 0; t < rOverlap.mBySimplex.size(); ++t) {
        const std::int64_t parent = rOverlap.mTgt.mParent[t];
        double* out_row = numerator.data() + static_cast<std::size_t>(parent) * comps;
        for (const auto& sm : rOverlap.mBySimplex[t]) {
            const std::int64_t src_parent =
                rOverlap.mSrc.mParent[static_cast<std::size_t>(sm.first)];
            const auto br = detail::global_to_block_row(src_bases, src_parent);
            const NDArray& src_arr = rValueSource.CellData(rSourceName, br.first);
            for (std::size_t c = 0; c < comps; ++c)
                out_row[c] +=
                    sm.second *
                    detail::read_double(src_arr, static_cast<std::size_t>(br.second) * comps + c);
        }
    }

    if (rUncovered.empty())
        rUncovered.assign(total_tgt, 0);
    for (std::size_t g = 0; g < total_tgt; ++g) {
        const bool covered = rOwnMeasure[g] > 0.0 && rCoveredMeasure[g] / rOwnMeasure[g] >= eps_rel;
        if (!covered) {
            rUncovered[g] = 1;
            for (std::size_t c = 0; c < comps; ++c)
                numerator[g * comps + c] = defaultValue;
        } else {
            for (std::size_t c = 0; c < comps; ++c)
                numerator[g * comps + c] /= rCoveredMeasure[g];
        }
    }

    std::vector<NDArray> out_blocks;
    out_blocks.reserve(rTarget.NumCellBlocks());
    std::size_t base = 0;
    const NDArray& sample = rValueSource.CellData(rSourceName, 0);
    std::vector<std::size_t> shape = sample.Shape();
    for (const auto cb : rTarget.CellRange()) {
        const std::size_t ncells = cb.NumCells();
        std::vector<std::size_t> block_shape = shape;
        if (block_shape.empty())
            block_shape = {ncells};
        else
            block_shape[0] = ncells;
        NDArray arr = NDArray::Uninit(DType::Float64, block_shape);
        double* o = arr.As<double>();
        for (std::size_t c = 0; c < ncells * comps; ++c)
            o[c] = numerator[base * comps + c];
        out_blocks.push_back(std::move(arr));
        base += ncells;
    }
    return out_blocks;
}

// The standard unknown-key diagnostic, covering both source locations.
std::string cons_unknown_array_message(const Mesh& rSource, const std::string& rName) {
    auto join = [](const std::vector<std::string>& rNames) -> std::string {
        if (rNames.empty())
            return "none";
        std::string s;
        for (std::size_t i = 0; i < rNames.size(); ++i) {
            if (i > 0)
                s += ", ";
            s += rNames[i];
        }
        return s;
    };
    return "meshio++: conservative_interpolate: no source point_data or cell_data array named '" +
           rName + "' (available point_data: " + join(data_names(rSource, DataLocation::Point)) +
           "; cell_data: " + join(data_names(rSource, DataLocation::Cell)) + ")";
}

std::string cons_resolve_name(const Mesh& rTarget, bool isPointData, const std::string& rName,
                              ConservativeInterpolateConflict Conflict) {
    const bool exists = isPointData ? rTarget.HasPointData(rName) : rTarget.HasCellData(rName);
    if (!exists)
        return rName;
    switch (Conflict) {
        case ConservativeInterpolateConflict::Overwrite:
            return rName;
        case ConservativeInterpolateConflict::Suffix: {
            const std::string suffixed = rName + "_interp";
            const bool taken =
                isPointData ? rTarget.HasPointData(suffixed) : rTarget.HasCellData(suffixed);
            if (taken)
                throw std::invalid_argument("meshio++: conservative_interpolate: array '" + rName +
                                            "' already exists on the target and so does '" +
                                            suffixed + "' (on_conflict='suffix')");
            return suffixed;
        }
        case ConservativeInterpolateConflict::Error:
        default:
            throw std::invalid_argument("meshio++: conservative_interpolate: array '" + rName +
                                        "' already exists on the target (on_conflict='error'; pass "
                                        "'overwrite' or 'suffix')");
    }
}

}  // namespace

ConservativeInterpolateConflict conservative_interpolate_conflict_from_name(
    const std::string& rName) {
    if (rName == "error")
        return ConservativeInterpolateConflict::Error;
    if (rName == "overwrite")
        return ConservativeInterpolateConflict::Overwrite;
    if (rName == "suffix")
        return ConservativeInterpolateConflict::Suffix;
    throw std::invalid_argument("meshio++: conservative_interpolate: unknown on_conflict '" +
                                rName + "' (expected 'error', 'overwrite' or 'suffix')");
}

Mesh conservative_interpolate(const Mesh& rSource, const Mesh& rTarget,
                              const ConservativeInterpolateOptions& rOptions) {
    if (rSource.NumPoints() == 0)
        throw std::invalid_argument(
            "meshio++: conservative_interpolate: the source mesh has no points");

    const int src_dim = cons_max_dim(rSource);
    const int tgt_dim = cons_max_dim(rTarget);
    if (src_dim != tgt_dim || (src_dim != 2 && src_dim != 3))
        throw std::invalid_argument(
            "meshio++: conservative_interpolate: source and target must share the same maximum "
            "topological dimension (2 or 3); got source=" +
            std::to_string(src_dim) + ", target=" + std::to_string(tgt_dim));
    const bool want_tet = src_dim == 3;

    // --- resolve which arrays transfer (validation before any work) --------
    std::vector<std::string> point_names;
    std::vector<std::string> cell_names;
    if (rOptions.mArrays.empty()) {
        point_names = rSource.PointDataNames();
        cell_names = rSource.CellDataNames();
    } else {
        for (const std::string& name : rOptions.mArrays) {
            bool any = false;
            if (rSource.HasPointData(name)) {
                point_names.push_back(name);
                any = true;
            }
            if (rSource.HasCellData(name)) {
                cell_names.push_back(name);
                any = true;
            }
            if (!any)
                throw std::invalid_argument(cons_unknown_array_message(rSource, name));
        }
    }
    for (const std::string& name : cell_names) {
        if (rSource.CellDataNumBlocks(name) != rSource.NumCellBlocks())
            throw std::invalid_argument("meshio++: conservative_interpolate: source cell_data '" +
                                        name + "' does not have one array per cell block");
    }

    std::vector<std::string> point_out(point_names.size());
    for (std::size_t i = 0; i < point_names.size(); ++i)
        point_out[i] = cons_resolve_name(rTarget, true, point_names[i], rOptions.mOnConflict);
    std::vector<std::string> cell_out(cell_names.size());
    for (std::size_t i = 0; i < cell_names.size(); ++i)
        cell_out[i] = cons_resolve_name(rTarget, false, cell_names[i], rOptions.mOnConflict);

    if (point_names.empty() && cell_names.empty())
        return detail::clone_mesh(rTarget);

    // --- simplexify both meshes once -----------------------------------------
    ConvertCellsOptions cco;
    cco.mMode = ConvertCellsMode::Simplexify;
    cco.mRecordParentIds = true;
    const ConvertCellsResult src_simp = convert_cells(rSource, cco);
    const ConvertCellsResult tgt_simp = convert_cells(rTarget, cco);
    const std::string want = want_tet ? "tetra" : "triangle";
    auto has_simplex = [&](const Mesh& rMesh) {
        for (const auto cb : rMesh.CellRange())
            if (cb.Type() == want && cb.NumCells() > 0)
                return true;
        return false;
    };
    if (!has_simplex(src_simp.mMesh) || !has_simplex(tgt_simp.mMesh))
        throw std::invalid_argument(
            "meshio++: conservative_interpolate: source and target both need at least one " + want +
            " cell after simplexification");

    // --- build the shared geometric overlap structure once ------------------
    const ConsOverlap overlap =
        cons_build_overlap(rSource, rTarget, src_simp.mMesh, tgt_simp.mMesh, want_tet);

    const std::size_t total_tgt =
        static_cast<std::size_t>(detail::total_cells(detail::block_bases(rTarget)));
    std::vector<double> covered_measure(total_tgt, 0.0);
    std::vector<double> own_measure(total_tgt, 0.0);
    {
        const NDArray& tpts = tgt_simp.mMesh.Points();
        const std::size_t tdim = tgt_simp.mMesh.PointDim();
        const std::size_t nv = overlap.mTgt.mNv;
        for (std::size_t t = 0; t < overlap.mTgt.mParent.size(); ++t) {
            const std::int64_t parent = overlap.mTgt.mParent[t];
            detail::Vec3 corners[4];
            for (std::size_t k = 0; k < nv; ++k)
                corners[k] = detail::read_point(tpts, tdim, overlap.mTgt.mConn[t * nv + k]);
            own_measure[static_cast<std::size_t>(parent)] += cons_own_measure(corners, nv);
            double m = 0.0;
            for (const auto& sm : overlap.mBySimplex[t])
                m += sm.second;
            covered_measure[static_cast<std::size_t>(parent)] += m;
        }
    }
    constexpr double kCoverageEpsRel = 1e-9;

    Mesh out = detail::clone_mesh(rTarget);

    // --- cell_data: direct -----------------------------------------------
    std::vector<char> uncovered;
    for (std::size_t i = 0; i < cell_names.size(); ++i) {
        std::vector<NDArray> blocks =
            cons_accumulate_array(rTarget, overlap, rSource, cell_names[i], covered_measure,
                                  own_measure, kCoverageEpsRel, rOptions.mDefaultValue, uncovered);
        out.AddCellData(cell_out[i], std::move(blocks));
    }

    // --- point_data: composed via a lumped cell proxy -----------------------
    if (!point_names.empty()) {
        DataAverageOptions pd2c;
        pd2c.names = point_names;
        pd2c.suffix = kProxySuffix;
        pd2c.overwrite = true;
        const Mesh src_proxy = point_data_to_cell_data(rSource, pd2c);

        Mesh tgt_proxy_scratch = detail::clone_geometry(rTarget);
        for (std::size_t i = 0; i < point_names.size(); ++i) {
            const std::string proxy_name = point_names[i] + kProxySuffix;
            std::vector<NDArray> blocks = cons_accumulate_array(
                rTarget, overlap, src_proxy, proxy_name, covered_measure, own_measure,
                kCoverageEpsRel, rOptions.mDefaultValue, uncovered);
            tgt_proxy_scratch.AddCellData(proxy_name, std::move(blocks));
        }

        DataAverageOptions c2pd;
        for (const std::string& name : point_names)
            c2pd.names.push_back(name + kProxySuffix);
        c2pd.weight = CellPointWeight::Measure;
        c2pd.suffix = "";
        c2pd.overwrite = true;
        const Mesh tgt_points = cell_data_to_point_data(tgt_proxy_scratch, c2pd);
        for (std::size_t i = 0; i < point_names.size(); ++i)
            out.AddPointData(
                point_out[i],
                detail::data_owned_copy(tgt_points.PointData(point_names[i] + kProxySuffix)));
    }

    const std::size_t n_uncovered =
        static_cast<std::size_t>(std::count(uncovered.begin(), uncovered.end(), char{1}));
    if (n_uncovered > 0)
        log::warn(
            "meshio++: conservative_interpolate: {} of {} target cells had no source overlap; "
            "filled with default_value = {}",
            n_uncovered, total_tgt, rOptions.mDefaultValue);

    return out;
}

}  // namespace meshioplusplus
